  (NULL, 'Corydalis', 'Corydalis yanhusuo', 'Tuber', 'Tetrahydropalmatine (L-THP)', 'Alkaloid', 'Protoberberine alkaloid', 'High', 'Marker', 'Principal analgesic alkaloid contributing to pain-relieving, sedative, and anxiolytic activity.', 'Corydalis yanhusuo is one of the few herbs whose medicinal activity is overwhelmingly dominated by a family of closely related alkaloids rather than a single marker compound. Including several of the principal protoberberine alkaloids provides a much more representative phytochemical fingerprint and will strengthen constituent-overlap analysis with herbs such as Barberry, Celandine, and California Poppy, while also highlighting Corydalis''s distinct analgesic chemistry driven by tetrahydropalmatine.'),
  (NULL, 'Corydalis', 'Corydalis yanhusuo', 'Tuber', 'Dehydrocorydaline', 'Alkaloid', 'Protoberberine alkaloid', 'High', 'Major', 'Major protoberberine alkaloid contributing analgesic and circulatory activity.', NULL),
