VALUES
  (57, 'Elder', 'Sambucus nigra', 'Flower', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Contributes antioxidant activity and supports immune and respiratory health.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Flower', 'Caffeic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Moderate', 'Present', 'Supports antioxidant and anti-inflammatory activity.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Flower', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Contributes antioxidant and mild anti-inflammatory activity.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Flower', 'Ursolic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Low–Moderate', 'Present', 'Contributes anti-inflammatory activity and supports tissue protection.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Berry', 'Cyanidin-3-glucoside', 'Flavonoid', 'Anthocyanin', 'High', 'Marker', 'Principal anthocyanin contributing antiviral, antioxidant, and immune-support activity.', 'I have intentionally treated elder flower separately from elder berry, consistent with Editorial Rule #5. Although both contain flavonoids and phenolic acids, the flower is characterized by a rutin-rich flavonoid profile, whereas the berry is defined by anthocyanins. Keeping them separate will make the constituent-overlap analysis considerably more meaningful than combining all parts into a single profile.'),
  (57, 'Elder', 'Sambucus nigra', 'Berry', 'Cyanidin-3-sambubioside', 'Flavonoid', 'Anthocyanin', 'High', 'Major', 'Major anthocyanin contributing antioxidant activity and characteristic berry pigmentation.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Berry', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Contributes antioxidant activity and supports immune and metabolic health.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Berry', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Supports capillary integrity and complements the berry''s antioxidant profile.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Berry', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity.', NULL),
  (57, 'Elder', 'Sambucus nigra', 'Berry', 'Cyanidin', 'Flavonoid', 'Anthocyanidin', 'Low–Moderate', 'Present', 'Anthocyanidin aglycone contributing antioxidant activity and produced through anthocyanin hydrolysis.', NULL),
