  (26, 'Echinacea', 'Echinacea purpurea', 'Root', 'Chicoric acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'High', 'Marker', 'Principal phenolic constituent contributing immunomodulatory, antioxidant, and antiviral activity.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Root', 'Caftaric acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Moderate', 'Major', 'Contributes antioxidant activity and supports the characteristic phenolic profile.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Root', 'Echinacoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Present', 'Contributes antioxidant and immunomodulatory activity; present in lower concentrations than in E. angustifolia.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Root', 'Dodeca-2E,4E,8Z,10E-tetraenoic acid isobutylamide', 'Lipid', 'Alkamide', 'High', 'Major', 'Principal alkamide contributing immunomodulatory activity and interaction with cannabinoid (CB₂) receptors.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Root', 'Undeca-2E,4E-diene-8,10-diynoic acid isobutylamide', 'Lipid', 'Alkamide', 'Moderate', 'Major', 'Characteristic alkamide complementing the immunologically active alkamide fraction.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Root', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'Moderate', 'Present', 'Contributes macrophage activation and innate immune support.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Aerial parts', 'Chicoric acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'High', 'Marker', 'Principal constituent contributing immunomodulatory, antioxidant, and antiviral activity; characteristic of the aerial parts.', 'This is one of the most chemically distinctive herbs in the database so far. The combination of caffeic acid derivatives, alkamides, and immunologically active polysaccharides defines Echinacea purpurea far better than any single constituent alone.'),
  (26, 'Echinacea', 'Echinacea purpurea', 'Aerial parts', 'Caftaric acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'High', 'Major', 'Major caffeic acid derivative supporting antioxidant and immune-modulating activity.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Contributes antioxidant activity and supports the phenolic profile.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Supports antioxidant activity and vascular integrity.', NULL),
  (26, 'Echinacea', 'Echinacea purpurea', 'Aerial parts', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'Moderate', 'Major', 'Contributes macrophage activation and innate immune support.', NULL),
  (448, 'Ephedra', 'Ephedra sinica', 'Aerial stems', 'Ephedrine', 'Alkaloid', 'Phenethylamine alkaloid', 'High', 'Marker', 'Principal sympathomimetic alkaloid responsible for bronchodilating, stimulant, and decongestant activity.', 'This is one of the clearest examples in the database of a herb whose medicinal activity is dominated almost entirely by one chemical family. The various phenethylamine alkaloids differ in potency and pharmacology, but together they define the therapeutic identity of Ephedra sinica.'),
  (448, 'Ephedra', 'Ephedra sinica', 'Aerial stems', 'Pseudoephedrine', 'Alkaloid', 'Phenethylamine alkaloid', 'High', 'Major', 'Major alkaloid contributing decongestant and bronchodilating activity with less central stimulation than ephedrine.', NULL),
  (448, 'Ephedra', 'Ephedra sinica', 'Aerial stems', 'Norephedrine', 'Alkaloid', 'Phenethylamine alkaloid', 'Moderate', 'Major', 'Contributes sympathomimetic and stimulant activity while complementing the principal alkaloid profile.', NULL),
  (448, 'Ephedra', 'Ephedra sinica', 'Aerial stems', 'Norpseudoephedrine', 'Alkaloid', 'Phenethylamine alkaloid', 'Moderate', 'Present', 'Minor sympathomimetic alkaloid consistently accompanying ephedrine and pseudoephedrine.', NULL),
  (448, 'Ephedra', 'Ephedra sinica', 'Aerial stems', 'Ephedroxane', 'Alkaloid', 'Phenethylamine alkaloid', 'Low–Moderate', 'Present', 'Minor characteristic alkaloid contributing to the unique alkaloid fingerprint of Ephedra.', NULL),
  (448, 'Ephedra', 'Ephedra sinica', 'Aerial stems', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Low', 'Present', 'Contributes antioxidant activity but is secondary to the characteristic alkaloid fraction.', NULL),
  (1441, 'Eucalyptus', 'Eucalyptus globulus', 'Leaf', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal constituent responsible for expectorant, mucolytic, antimicrobial, and decongestant activity.', 'Although eucalyptus is commonly identified with 1,8-cineole alone, authoritative references consistently describe a broader volatile oil profile that includes α-pinene, limonene, and globulol. Including these provides a more representative phytochemical fingerprint while still recognizing that 1,8-cineole overwhelmingly defines the herb''s medicinal actions.'),
  (1441, 'Eucalyptus', 'Eucalyptus globulus', 'Leaf', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Contributes antimicrobial activity and supports respiratory effects.', NULL),
  (1441, 'Eucalyptus', 'Eucalyptus globulus', 'Leaf', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Contributes antimicrobial, antioxidant, and aromatic activity.', NULL),
  (1441, 'Eucalyptus', 'Eucalyptus globulus', 'Leaf', 'Globulol', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Characteristic sesquiterpene alcohol contributing anti-inflammatory and antimicrobial activity.', NULL),
  (1441, 'Eucalyptus', 'Eucalyptus globulus', 'Leaf', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the leaf polyphenol fraction.', NULL),
  (1441, 'Eucalyptus', 'Eucalyptus globulus', 'Leaf', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Supports antioxidant and mild anti-inflammatory activity.', NULL),
  (211, 'European Mistletoe', 'Viscum album', 'Leaf & stem', 'Viscotoxin A3', 'Protein', 'Thionin', 'High', 'Marker', 'Principal cytotoxic protein contributing immunomodulatory activity and widely used for extract standardization.', NULL),
  (211, 'European Mistletoe', 'Viscum album', 'Leaf & stem', 'Mistletoe lectin I', 'Protein', 'Lectin', 'High', 'Marker', 'Principal lectin contributing immunomodulatory and apoptotic activity; extensively studied in oncology.', NULL),
  (211, 'European Mistletoe', 'Viscum album', 'Leaf & stem', 'Oleanolic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Major', 'Contributes anti-inflammatory activity and supports the triterpenoid fraction.', NULL),
  (211, 'European Mistletoe', 'Viscum album', 'Leaf & stem', 'Ursolic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Major', 'Supports anti-inflammatory and cytoprotective activity.', NULL),
  (211, 'European Mistletoe', 'Viscum album', 'Leaf & stem', 'Syringin', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Present', 'Contributes antioxidant activity and complements the phenolic profile.', NULL),
  (211, 'European Mistletoe', 'Viscum album', 'Leaf & stem', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and supports vascular protection.', NULL),
  (51, 'Eyebright', 'Euphrasia officinalis', 'Aerial parts', 'Aucubin', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid contributing anti-inflammatory activity and protection of irritated ocular and respiratory tissues.', 'Eyebright is another herb whose chemistry is driven primarily by iridoid glycosides and phenylethanoid glycosides, making it chemically closer to herbs such as Plantain, Devil''s Claw, and Balmony than its traditional indications alone would suggest. The inclusion of euphroside is particularly useful because it helps distinguish Euphrasia from other iridoid-rich herbs while remaining faithful to the database''s goal of emphasizing characteristic, pharmacologically relevant constituents.'),
  (51, 'Eyebright', 'Euphrasia officinalis', 'Aerial parts', 'Catalpol', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Supports anti-inflammatory activity and complements the iridoid profile.', NULL),
  (51, 'Eyebright', 'Euphrasia officinalis', 'Aerial parts', 'Euphroside', 'Glycoside', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Characteristic phenylethanoid glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (51, 'Eyebright', 'Euphrasia officinalis', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity.', NULL),
  (51, 'Eyebright', 'Euphrasia officinalis', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Supports anti-inflammatory and mild antispasmodic activity.', NULL),
  (51, 'Eyebright', 'Euphrasia officinalis', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and supports tissue protection.', NULL),
  (76, 'Fennel', 'Foeniculum vulgare', 'Fruit (seed)', 'trans-Anethole', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Marker', 'Principal constituent responsible for carminative, antispasmodic, expectorant, and mild estrogenic activity.', 'Fennel illustrates why recording individual volatile constituents rather than "essential oil" is valuable. Although trans-anethole dominates the medicinal activity, the balance of fenchone, estragole, and the accompanying monoterpenes distinguishes fennel chemically from related Apiaceae such as Anise, Caraway, and Coriander.'),
  (76, 'Fennel', 'Foeniculum vulgare', 'Fruit (seed)', 'Fenchone', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Contributes digestive stimulation, expectorant activity, and the characteristic aroma of bitter fennel.', NULL),
  (76, 'Fennel', 'Foeniculum vulgare', 'Fruit (seed)', 'Estragole', 'Phenylpropanoid', 'Phenylpropene', 'Moderate', 'Major', 'Contributes aromatic, carminative, and mild antispasmodic activity while complementing anethole.', NULL),
  (76, 'Fennel', 'Foeniculum vulgare', 'Fruit (seed)', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Contributes digestive, antimicrobial, and aromatic activity.', NULL),
  (76, 'Fennel', 'Foeniculum vulgare', 'Fruit (seed)', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Supports antimicrobial and digestive activity while contributing to the volatile oil profile.', NULL),
  (76, 'Fennel', 'Foeniculum vulgare', 'Fruit (seed)', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and supports vascular integrity.', NULL),
  (91, 'Fenugreek', 'Trigonella foenum-graecum', 'Seed', 'Diosgenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Marker', 'Principal steroidal sapogenin contributing endocrine-modulating activity and serving as the precursor to the seed''s steroidal saponins.', 'Fenugreek''s medicinal activity arises from the combination of steroidal sapogenins, galactomannan fiber, trigonelline, and 4-hydroxyisoleucine, each contributing through distinct mechanisms.'),
  (91, 'Fenugreek', 'Trigonella foenum-graecum', 'Seed', 'Trigonelline', 'Alkaloid', 'Pyridine alkaloid', 'High', 'Major', 'Contributes hypoglycemic activity and supports metabolic health.', NULL),
  (91, 'Fenugreek', 'Trigonella foenum-graecum', 'Seed', 'Galactomannan', 'Polysaccharide', 'Galactomannan', 'High', 'Major', 'Principal soluble fiber responsible for demulcent activity, glycemic regulation, and cholesterol-lowering effects.', NULL),
