  (39, 'Figwort', 'Scrophularia nodosa', 'Aerial parts', 'Harpagoside', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid contributing anti-inflammatory activity and supporting traditional use for swollen lymphatics and musculoskeletal conditions.', 'Figwort combines the iridoid glycosides of herbs like Devil''s Claw and Eyebright with the phenylethanoid glycosides found in Plantain and other members of the Scrophulariaceae.'),
  (39, 'Figwort', 'Scrophularia nodosa', 'Aerial parts', 'Harpagide', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Contributes anti-inflammatory activity and complements the characteristic iridoid profile.', NULL),
  (39, 'Figwort', 'Scrophularia nodosa', 'Aerial parts', 'Aucubin', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Supports anti-inflammatory activity and tissue protection.', NULL),
  (39, 'Figwort', 'Scrophularia nodosa', 'Aerial parts', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Major', 'Contributes antioxidant, anti-inflammatory, and tissue-protective activity.', NULL),
  (39, 'Figwort', 'Scrophularia nodosa', 'Aerial parts', 'Scrophuloside A', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Reported', 'Characteristic iridoid glycoside helping define the phytochemical profile of Scrophularia.', NULL),
  (39, 'Figwort', 'Scrophularia nodosa', 'Aerial parts', 'Caffeic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the phenolic fraction.', NULL),
  (180, 'Flax', 'Linum usitatissimum', 'Seed', 'Secoisolariciresinol diglucoside (SDG)', 'Glycoside', 'Lignan glycoside', 'High', 'Marker', 'Principal lignan glycoside contributing antioxidant activity and modulation of estrogen metabolism.', 'Flax is one of the most chemically distinctive herbs in the database because it combines lignans, omega-3 lipids, and mucilage in therapeutically meaningful amounts. This profile is quite unlike most medicinal herbs we''ve covered. I also think Omega-3 fatty acid is worth adding despite the general exclusion of fatty acids in Editorial Rule #2, because α-linolenic acid is unquestionably one of the defining medicinal constituents of flaxseed rather than merely a nutritional component.'),
  (180, 'Flax', 'Linum usitatissimum', 'Seed', 'Secoisolariciresinol', 'Polyphenol', 'Lignan', 'Moderate', 'Major', 'Lignan aglycone produced from SDG by intestinal metabolism; contributes phytoestrogenic and antioxidant activity.', NULL),
  (180, 'Flax', 'Linum usitatissimum', 'Seed', 'α-Linolenic acid', 'Lipid', 'Omega-3 fatty acid', 'High', 'Major', 'Principal omega-3 fatty acid contributing anti-inflammatory and cardioprotective activity.', NULL),
  (180, 'Flax', 'Linum usitatissimum', 'Seed', 'Arabinoxylan', 'Polysaccharide', 'Arabinoxylan', 'High', 'Major', 'Provides demulcent, bulk-forming, and laxative activity while supporting gastrointestinal health.', NULL),
  (180, 'Flax', 'Linum usitatissimum', 'Seed', 'Linustatin', 'Glycoside', 'Cyanogenic glycoside', 'Moderate', 'Present', 'Cyanogenic glycoside contributing to the seed''s natural chemical defense; largely inactivated by normal culinary processing.', NULL),
  (180, 'Flax', 'Linum usitatissimum', 'Seed', 'Neolinustatin', 'Glycoside', 'Cyanogenic glycoside', 'Moderate', 'Present', 'Accompanies linustatin as the principal cyanogenic glycoside in flaxseed.', NULL),
