  (124, 'Ginger', 'Zingiber officinale', 'Rhizome', '8-Gingerol', 'Phenylpropanoid', 'Phenolic ketone', 'Moderate', 'Major', 'Contributes anti-inflammatory and digestive activity while complementing 6-gingerol.', NULL),
