  (30, 'Goldenseal', 'Hydrastis canadensis', 'Rhizome & root', 'Berberine', 'Alkaloid', 'Protoberberine alkaloid', 'High', 'Marker', 'Principal antimicrobial alkaloid contributing broad-spectrum antimicrobial, bitter tonic, and cholagogue activity.', 'Goldenseal demonstrates why the database distinguishes individual alkaloid subclasses. Although berberine, canadine, and berberastine are all protoberberine alkaloids, hydrastine belongs to the distinct phthalide isoquinoline family and is a defining marker of Hydrastis canadensis. Capturing that distinction will improve future similarity analysis with Barberry, Oregon Grape, and Celandine, all of which share protoberberine alkaloids but lack hydrastine.'),
  (30, 'Goldenseal', 'Hydrastis canadensis', 'Rhizome & root', 'Hydrastine', 'Alkaloid', 'Phthalide isoquinoline alkaloid', 'High', 'Marker', 'Characteristic alkaloid contributing mucosal astringency and serving as a primary marker of authentic goldenseal.', NULL),
  (30, 'Goldenseal', 'Hydrastis canadensis', 'Rhizome & root', 'Canadine (Tetrahydroberberine)', 'Alkaloid', 'Tetrahydroprotoberberine alkaloid', 'Moderate', 'Major', 'Contributes antimicrobial activity and complements the characteristic protoberberine alkaloid profile.', NULL),
  (30, 'Goldenseal', 'Hydrastis canadensis', 'Rhizome & root', 'Berberastine', 'Alkaloid', 'Protoberberine alkaloid', 'Moderate', 'Present', 'Characteristic accompanying protoberberine alkaloid supporting the herb''s antimicrobial chemistry.', NULL),
  (30, 'Goldenseal', 'Hydrastis canadensis', 'Rhizome & root', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the alkaloid-dominated phytochemical profile.', NULL),
  (NULL, 'Gotu Kola', 'Centella asiatica', 'Aerial parts', 'Asiaticoside', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal constituent promoting collagen synthesis, wound healing, and connective tissue repair.', 'Gotu kola is one of the clearest examples of a herb whose medicinal activity is dominated by a matched pair of triterpenoid saponins and their aglycones. Including both the glycosides (asiaticoside, madecassoside) and the corresponding aglycones (asiatic acid, madecassic acid) captures the chemistry responsible for the herb''s well-established effects on wound healing and connective tissue remodeling while remaining faithful to the database''s emphasis on major, pharmacologically relevant constituents.'),
  (NULL, 'Gotu Kola', 'Centella asiatica', 'Aerial parts', 'Madecassoside', 'Glycoside', 'Triterpenoid saponin', 'High', 'Major', 'Contributes wound healing, anti-inflammatory activity, and microvascular support.', NULL),
  (NULL, 'Gotu Kola', 'Centella asiatica', 'Aerial parts', 'Asiatic acid', 'Terpenoid', 'Ursane triterpenoid', 'High', 'Major', 'Triterpenoid aglycone contributing tissue regeneration, neuroprotection, and anti-inflammatory activity.', NULL),
  (NULL, 'Gotu Kola', 'Centella asiatica', 'Aerial parts', 'Madecassic acid', 'Terpenoid', 'Ursane triterpenoid', 'Moderate', 'Major', 'Supports collagen production and complements the activity of asiatic acid.', NULL),
  (NULL, 'Gotu Kola', 'Centella asiatica', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'Gotu Kola', 'Centella asiatica', 'Aerial parts', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Supports antioxidant activity and complements the flavonoid profile.', NULL),
