  (117, 'Gravel Root', 'Eutrochium purpureum', 'Root', 'Euparin', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Characteristic constituent contributing antimicrobial activity and serving as the principal phytochemical marker.', NULL),
  (117, 'Gravel Root', 'Eutrochium purpureum', 'Root', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Contributes antioxidant activity and supports urinary tract health.', NULL),
