  (117, 'Gravel Root', 'Eutrochium purpureum', 'Root', 'Eupatorin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Characteristic flavone contributing antioxidant and anti-inflammatory activity.', NULL),
  (117, 'Gravel Root', 'Eutrochium purpureum', 'Root', 'Pyrrolizidine alkaloids', 'Alkaloid', 'Pyrrolizidine alkaloid', 'Low', 'Reported', 'Toxicologically significant constituents reported in some populations; included because of their safety relevance rather than therapeutic contribution.', NULL),
  (149, 'Green Tea', 'Camellia sinensis', 'Leaf', 'Epigallocatechin gallate (EGCG)', 'Flavonoid', 'Flavan-3-ol', 'High', 'Marker', 'Principal catechin contributing antioxidant, anti-inflammatory, cardioprotective, and chemoprotective activity.', 'Green tea is one of the strongest examples of why the database should include multiple major constituents rather than a single marker. Its pharmacology arises from the interplay between catechins, caffeine, and L-theanine, with the latter moderating many of caffeine''s effects. Representing all three chemical families creates a much more faithful phytochemical fingerprint than simply listing EGCG alone.'),
  (149, 'Green Tea', 'Camellia sinensis', 'Leaf', 'Epigallocatechin (EGC)', 'Flavonoid', 'Flavan-3-ol', 'High', 'Major', 'Major catechin supporting antioxidant activity and complementing EGCG.', NULL),
  (149, 'Green Tea', 'Camellia sinensis', 'Leaf', 'Epicatechin gallate (ECG)', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Contributes antioxidant and vascular protective activity.', NULL),
  (149, 'Green Tea', 'Camellia sinensis', 'Leaf', 'Epicatechin (EC)', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Supports antioxidant activity and serves as a precursor of condensed tannins.', NULL),
  (149, 'Green Tea', 'Camellia sinensis', 'Leaf', 'Caffeine', 'Alkaloid', 'Purine alkaloid', 'High', 'Major', 'Contributes central nervous system stimulation, alertness, and thermogenic activity.', NULL),
  (149, 'Green Tea', 'Camellia sinensis', 'Leaf', 'L-Theanine', 'Nitrogenous compound', 'Amino acid derivative', 'High', 'Major', 'Contributes relaxation, improved attention, and modulation of caffeine''s stimulant effects.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'High', 'Marker', 'Principal flavonoid contributing cardioprotective, antioxidant, and vascular-support activity.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Vitexin-2''''-O-rhamnoside', 'Flavonoid', 'Flavone glycoside', 'High', 'Marker', 'Characteristic flavone glycoside contributing coronary vasodilation and positive inotropic activity.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Supports capillary integrity and complements the flavonoid profile.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Contributes antioxidant activity and supports cardiovascular protection.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Procyanidin B2', 'Tannin', 'Condensed tannin', 'High', 'Major', 'Major oligomeric procyanidin contributing vascular protection and antioxidant activity.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Procyanidin C1', 'Tannin', 'Condensed tannin', 'Moderate', 'Present', 'Higher oligomeric procyanidin contributing to the characteristic OPC profile and endothelial support.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Berry', 'Cyanidin-3-galactoside', 'Flavonoid', 'Anthocyanin', 'High', 'Marker', 'Principal anthocyanin contributing antioxidant activity and supporting cardiovascular health.', 'Separating hawthorn berry from leaf & flower reveals an important phytochemical distinction. The berry is characterized by anthocyanins, particularly cyanidin glycosides, whereas the leaf & flower are richer in flavonoids such as vitexin-2''''-O-rhamnoside and are the plant parts most commonly standardized in modern clinical extracts. Both parts share procyanidins and chlorogenic acid, but their differing marker constituents make them valuable as separate entries for constituent-overlap analysis.'),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Berry', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'High', 'Major', 'Major flavonoid contributing capillary support, antioxidant activity, and vascular protection.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Berry', 'Procyanidin B2', 'Tannin', 'Condensed tannin', 'High', 'Major', 'Principal oligomeric procyanidin supporting endothelial function and cardiovascular protection.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Berry', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Contributes antioxidant activity and supports cardiovascular and metabolic health.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Berry', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Contributes antioxidant and mild anti-inflammatory activity.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Berry', 'Procyanidin C1', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Monomeric flavan-3-ol contributing antioxidant activity and serving as a building block for procyanidins.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Female strobile', 'Humulone', 'Phloroglucinol', 'Prenylated phloroglucinol', 'High', 'Marker', 'Principal α-acid contributing bitter tonic, antimicrobial, and anti-inflammatory activity.', 'Hops introduces several chemically distinctive compounds that don''t fit comfortably into the existing flavonoid taxonomy. Xanthohumol is one of the best-studied prenylated chalcones, while 8-prenylnaringenin is the best-known prenylated flavanone. Likewise, humulone and lupulone belong to the characteristic prenylated phloroglucinols (hop bitter acids), a recurring chemical family within Humulus.'),
  (129, 'Hops', 'Humulus lupulus', 'Female strobile', 'Lupulone', 'Phloroglucinol', 'Prenylated phloroglucinol', 'High', 'Major', 'Principal β-acid contributing antimicrobial activity and complementing the bitter resin fraction.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Female strobile', 'Xanthohumol', 'Flavonoid', 'Prenylated chalcone', 'High', 'Major', 'Major prenylated flavonoid contributing antioxidant, anti-inflammatory, and chemoprotective activity.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Female strobile', '8-Prenylnaringenin', 'Flavonoid', 'Prenylated flavanone', 'Moderate', 'Major', 'Potent phytoestrogen contributing endocrine-modulating activity.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Female strobile', 'Myrcene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Contributes aromatic, antimicrobial, and mild sedative activity.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Female strobile', 'β-Caryophyllene', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Contributes anti-inflammatory activity and complements the volatile oil profile.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Marrubiin', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Principal bitter diterpene contributing expectorant, bitter tonic, and digestive-stimulant activity.', 'Horehound is chemically distinctive because its medicinal activity is driven by labdane diterpenes, especially marrubiin, rather than the volatile oils that dominate many other members of the mint family. The addition of verbascoside also creates another meaningful overlap with herbs such as Figwort, Devil''s Claw, and Eyebright, illustrating how constituent-based analysis reveals relationships that are not obvious from traditional herbal classifications.'),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Premarrubiin', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Biosynthetic precursor of marrubiin contributing to the herb''s bitter diterpene profile.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Marrubenol', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Present', 'Contributes smooth muscle relaxation and complements the diterpene fraction.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Contributes antioxidant, anti-inflammatory, and tissue-protective activity.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Supports antioxidant activity and complements the flavonoid profile.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Aescin', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal constituent responsible for venotonic, anti-edematous, and capillary-protective activity.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Protoaescigenin', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal triterpenoid aglycone contributing anti-inflammatory and vascular protective activity.', NULL),
