  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Esculin', 'Glycoside', 'Coumarin glycoside', 'Moderate', 'Major', 'Contributes capillary protection and antioxidant activity; characteristic coumarin glycoside of the seed.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Fraxin', 'Coumarin', 'Simple coumarin', 'Low–Moderate', 'Present', 'Complements the coumarin profile and contributes antioxidant activity.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Silicic acid', 'Silicon compound', 'Orthosilicic acid', 'High', 'Marker', 'Principal source of bioavailable silica, contributing to connective tissue, bone, hair, nail, and skin support.', 'Horsetail is unique among medicinal herbs because bioavailable silica is one of its defining medicinal constituents. Orthosilicic acid is not simply a mineral—it is the bioavailable chemical form of silicon that has recognized pharmacological relevance.'),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Isoquercitrin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Contributes antioxidant activity and supports capillary integrity.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Supports antioxidant and anti-inflammatory activity.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Contributes antioxidant activity and complements the flavonoid profile.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Caffeic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Low–Moderate', 'Present', 'Supports antioxidant and tissue-protective activity.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Nicotine', 'Alkaloid', 'Pyridine alkaloid', 'Low', 'Reported', 'Minor alkaloid reported in some populations; included because it is consistently documented despite its low abundance.', NULL),
  (29, 'Guaiacum', 'Guaiacum officinale', 'Heartwood', 'Guaiaconic acid', 'Polyphenol', 'Lignan', 'High', 'Marker', 'Principal resin constituent contributing anti-inflammatory and antioxidant activity; historically used as the analytical marker of guaiac resin.', 'This is one of the few herbs where the medicinal chemistry is centered on a lignan-rich resin rather than volatile oils or glycosides.'),
  (29, 'Guaiacum', 'Guaiacum officinale', 'Heartwood', 'Guaiaretic acid', 'Polyphenol', 'Lignan', 'High', 'Major', 'Major lignan contributing antioxidant activity and complementing the resin''s pharmacological profile.', NULL),
  (29, 'Guaiacum', 'Guaiacum officinale', 'Heartwood', 'Guaiacyl resinol', 'Polyphenol', 'Lignan', 'Moderate', 'Major', 'Characteristic lignan resin constituents contributing anti-inflammatory activity and defining the chemistry of guaiac resin.', NULL),
  (29, 'Guaiacum', 'Guaiacum officinale', 'Heartwood', 'Vanillic acid', 'Polyphenol', 'Phenolic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the phenolic fraction.', NULL),
  (29, 'Guaiacum', 'Guaiacum officinale', 'Heartwood', 'Ferulic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Low–Moderate', 'Present', 'Supports antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'Gymnema', 'Gymnema sylvestre', 'Leaf', 'Gymnemic acid I', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal constituent responsible for suppression of sweet taste perception and support of healthy glucose metabolism.', 'Gymnema is unusual because two chemically unrelated constituent families contribute to the same hallmark action. The gymnemic acids (triterpenoids) are responsible for much of the herb''s metabolic activity, while gurmarin, a small peptide, also suppresses sweet taste perception through a different mechanism.'),
  (NULL, 'Gymnema', 'Gymnema sylvestre', 'Leaf', 'Gymnemic acid IV', 'Glycoside', 'Triterpenoid saponin', 'High', 'Major', 'Major gymnemic acid contributing antihyperglycemic activity and inhibition of intestinal glucose absorption.', NULL),
  (NULL, 'Gymnema', 'Gymnema sylvestre', 'Leaf', 'Gymnemagenin', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal triterpenoid aglycone contributing to the characteristic gymnemic acid profile.', NULL),
  (NULL, 'Gymnema', 'Gymnema sylvestre', 'Leaf', 'Gymnemasaponin V', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Characteristic saponin contributing to the herb''s metabolic and sweet taste–modulating activity.', NULL),
  (NULL, 'Gymnema', 'Gymnema sylvestre', 'Leaf', 'Gurmarin', 'Protein', 'Peptide', 'Moderate', 'Present', 'Sweet taste–suppressing peptide that complements the activity of the gymnemic acids.', NULL),
  (NULL, 'Gymnema', 'Gymnema sylvestre', 'Leaf', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the triterpenoid-dominated phytochemical profile.', NULL),
  (NULL, 'Hibiscus', 'Hibiscus sabdariffa', 'Calyx', 'Delphinidin-3-sambubioside', 'Flavonoid', 'Anthocyanin', 'High', 'Marker', 'Principal anthocyanin contributing antioxidant activity, cardiovascular support, and the characteristic deep red color.', 'Hibiscus is the first herb where an organic acid is genuinely one of the defining medicinal constituents. Although organic acids are common throughout the plant kingdom, they are usually minor accompanying compounds. Hibiscus acid, however, is characteristic of Hibiscus sabdariffa and contributes directly to both its pharmacology and its organoleptic profile.'),
  (NULL, 'Hibiscus', 'Hibiscus sabdariffa', 'Calyx', 'Cyanidin-3-sambubioside', 'Flavonoid', 'Anthocyanin', 'High', 'Major', 'Major anthocyanin complementing delphinidin derivatives and contributing antihypertensive activity.', NULL),
  (NULL, 'Hibiscus', 'Hibiscus sabdariffa', 'Calyx', 'Hibiscus acid', 'Other', 'Organic acid', 'High', 'Marker', 'Characteristic organic acid contributing the herb''s sour flavor and supporting digestive and antihypertensive activity.', NULL),
  (NULL, 'Hibiscus', 'Hibiscus sabdariffa', 'Calyx', 'Protocatechuic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Major', 'Contributes antioxidant, anti-inflammatory, and hepatoprotective activity.', NULL),
  (NULL, 'Hibiscus', 'Hibiscus sabdariffa', 'Calyx', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Contributes antioxidant activity and complements the phenolic profile.', NULL),
  (NULL, 'Hibiscus', 'Hibiscus sabdariffa', 'Calyx', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Supports antioxidant activity and complements the anthocyanin-rich chemistry.', NULL),
  (13, 'Holy Basil', 'Ocimum tenuiflorum', 'Leaf', 'Eugenol', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Marker', 'Principal constituent contributing antimicrobial, anti-inflammatory, analgesic, and adaptogenic activity.', NULL),
  (13, 'Holy Basil', 'Ocimum tenuiflorum', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'High', 'Major', 'Contributes antioxidant, anti-inflammatory, and immunomodulatory activity.', NULL),
  (13, 'Holy Basil', 'Ocimum tenuiflorum', 'Leaf', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Moderate', 'Major', 'Supports anti-inflammatory, adaptogenic, and tissue-protective activity.', NULL),
  (13, 'Holy Basil', 'Ocimum tenuiflorum', 'Leaf', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity while complementing the phenolic profile.', NULL),
  (13, 'Holy Basil', 'Ocimum tenuiflorum', 'Leaf', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Supports antioxidant activity and complements the flavonoid fraction.', NULL),
  (13, 'Holy Basil', 'Ocimum tenuiflorum', 'Leaf', 'β-Caryophyllene', 'Terpenoid', 'Sesquiterpene', 'Low–Moderate', 'Present', 'Contributes anti-inflammatory and antimicrobial activity while enriching the characteristic essential oil profile.', NULL),
  (212, 'Black Horehound', 'Ballota nigra', 'Aerial parts', 'Ballotenol', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Principal diterpene contributing bitter tonic, mild sedative, and antispasmodic activity.', 'Although Black Horehound is traditionally grouped with White Horehound (Marrubium vulgare), their phytochemistry differs in meaningful ways. They share marrubiin and a flavonoid-rich profile, but Ballota nigra is notably richer in phenylethanoid glycosides, particularly verbascoside and forsythoside B, which likely contribute to its more pronounced calming and anti-inflammatory actions. This makes it a good example of how constituent-based comparison can distinguish closely related herbs with overlapping traditional uses.'),
  (212, 'Black Horehound', 'Ballota nigra', 'Aerial parts', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Major', 'Contributes antioxidant, anti-inflammatory, and tissue-protective activity.', NULL),
  (212, 'Black Horehound', 'Ballota nigra', 'Aerial parts', 'Forsythoside B', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Characteristic phenylethanoid glycoside contributing antioxidant and antimicrobial activity.', NULL),
  (212, 'Black Horehound', 'Ballota nigra', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity.', NULL),
  (212, 'Black Horehound', 'Ballota nigra', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Supports antioxidant activity and complements the flavonoid profile.', NULL),
  (212, 'Black Horehound', 'Ballota nigra', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and supports tissue protection.', NULL),
  (113, 'Horseradish', 'Armoracia rusticana', 'Root', 'Sinigrin', 'Glycoside', 'Glucosinolate', 'High', 'Marker', 'Principal glucosinolate that is enzymatically converted to allyl isothiocyanate, contributing pungent antimicrobial, rubefacient, and respiratory stimulant activity.', 'Horseradish introduces one of the major phytochemical families: glucosinolates. These sulfur-containing glycosides define the chemistry of the Brassicaceae and are responsible for the formation of biologically active isothiocyanates upon tissue disruption.'),
  (113, 'Horseradish', 'Armoracia rusticana', 'Root', 'Allyl isothiocyanate', 'Organosulfur compound', 'Isothiocyanate', 'High', 'Major', 'Primary hydrolysis product of sinigrin responsible for the herb''s pungency and broad-spectrum antimicrobial activity.', NULL),
  (113, 'Horseradish', 'Armoracia rusticana', 'Root', 'Gluconasturtiin', 'Glycoside', 'Glucosinolate', 'Moderate', 'Major', 'Characteristic glucosinolate yielding phenethyl isothiocyanate and complementing the antimicrobial profile.', NULL),
  (113, 'Horseradish', 'Armoracia rusticana', 'Root', 'Phenethyl isothiocyanate', 'Organosulfur compound', 'Isothiocyanate', 'Moderate', 'Present', 'Contributes antimicrobial and chemoprotective activity following glucosinolate hydrolysis.', NULL),
  (113, 'Horseradish', 'Armoracia rusticana', 'Root', 'Sinapine', 'Phenylpropanoid', 'Choline ester', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and represents a characteristic seed and root phenolic ester found in Brassicaceae.', NULL),
  (113, 'Horseradish', 'Armoracia rusticana', 'Root', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the glucosinolate-dominated chemistry.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Pinocamphone', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal ketone monoterpene contributing expectorant, antimicrobial, and stimulating respiratory activity.', 'Hyssop is another member of the mint family whose medicinal identity depends on the combination of a distinctive volatile oil and non-volatile phenolics. Unlike many Lamiaceae herbs dominated by thymol or carvacrol, Hyssopus officinalis is characterized by pinocamphone and isopinocamphone, making its essential oil chemically distinctive. Including rosmarinic acid alongside these terpenoids captures both the traditional respiratory actions and the broader anti-inflammatory chemistry of the herb.')
INSERT INTO herbal.constituent_profiles
  (herb_id, common_name, latin_name, plant_part, constituent, class, subclass, importance, status, notes, editorial_note)
VALUES
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Isopinocamphone', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major companion monoterpene contributing to the characteristic essential oil profile and respiratory effects.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'High', 'Major', 'Contributes antioxidant, anti-inflammatory, and antiviral activity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Ursolic acid', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Present', 'Characteristic diterpene contributing bitter tonic and expectorant activity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Diosmin', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Present', 'Contributes antioxidant activity and supports vascular integrity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Supports antioxidant and anti-inflammatory activity while complementing the flavonoid profile.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Lichenin', 'Polysaccharide', 'β-Glucan', 'High', 'Marker', 'Principal polysaccharide contributing demulcent activity and soothing irritated respiratory and gastrointestinal mucosa.', 'This is one of the most chemically unique herbs in the database. Lichen acids (depsidones) are a hallmark of medicinal lichens and represent a distinct natural product family not encountered in higher plants. Likewise, lichenin and isolichenin are chemically well-defined glucans that account for Iceland moss''s classic demulcent action.'),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Isolichenin', 'Polysaccharide', 'α-Glucan', 'High', 'Major', 'Storage polysaccharide contributing immunomodulatory and nutritive properties.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Cetraric acid', 'Depsidone', 'Depsidone', 'High', 'Marker', 'Principal bitter lichen acid contributing antimicrobial activity and digestive bitter effects.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Fumarprotocetraric acid', 'Depsidone', 'Depsidone', 'Moderate', 'Major', 'Characteristic lichen acid contributing antimicrobial and antioxidant activity.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Protocetraric acid', 'Depsidone', 'Depsidone', 'Moderate', 'Present', 'Supports the characteristic bitter lichen acid profile and contributes antimicrobial activity.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Atranorin', 'Dibenzofuran', 'Dibenzofuran', 'Low–Moderate', 'Reported', 'Antimicrobial lichen metabolite reported in some material but not consistently abundant in Cetraria islandica.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal volatile constituent contributing diuretic, antimicrobial, and urinary antiseptic activity.', 'Juniper is another herb whose medicinal identity is largely defined by its volatile oil, but unlike many aromatic herbs, it also contains biflavonoids, particularly amentoflavone, that are characteristic of the Cupressaceae.'),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Sabinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major monoterpene contributing antimicrobial activity and the characteristic juniper aroma.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Myrcene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Contributes anti-inflammatory activity and complements the volatile oil profile.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Terpinen-4-ol', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Contributes diuretic activity and supports antimicrobial effects in the urinary tract.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Amentoflavone', 'Flavonoid', 'Biflavonoid', 'Moderate', 'Present', 'Characteristic biflavonoid contributing antioxidant and anti-inflammatory activity.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the polyphenol fraction.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Kavain', 'α-Pyrone', 'Kavalactone', 'High', 'Marker', 'Principal anxiolytic constituent contributing relaxation, anxiolysis, and skeletal muscle relaxation without significant cognitive impairment.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Dihydrokavain', 'α-Pyrone', 'Kavalactone', 'High', 'Major', 'Major kavalactone complementing kavain and contributing anxiolytic and sedative activity.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Methysticin', 'α-Pyrone', 'Kavalactone', 'High', 'Major', 'Contributes anxiolytic activity and inhibition of monoamine oxidase while supporting the characteristic kavalactone profile.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Dihydromethysticin', 'α-Pyrone', 'Kavalactone', 'Moderate', 'Major', 'Supports anxiolytic and muscle-relaxant activity while complementing methysticin.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Yangonin', 'α-Pyrone', 'Kavalactone', 'Moderate', 'Major', 'Contributes anxiolytic effects and interacts with the endocannabinoid system through CB₁ receptor affinity.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Desmethoxyyangonin', 'α-Pyrone', 'Kavalactone', 'Moderate', 'Present', 'Characteristic kavalactone completing the principal six-kavalactone profile used for chemotype classification.', NULL),
  (NULL, 'Kelp', 'Laminaria digitata', 'Thallus', 'Fucoidan', 'Polysaccharide', 'Sulfated fucan', 'High', 'Marker', 'Principal sulfated polysaccharide contributing immunomodulatory, anticoagulant, and anti-inflammatory activity.', NULL),
  (NULL, 'Kelp', 'Laminaria digitata', 'Thallus', 'Alginic acid', 'Polysaccharide', 'Alginate', 'High', 'Major', 'Major structural polysaccharide providing demulcent activity and binding bile acids and heavy metals.', NULL),
  (NULL, 'Kelp', 'Laminaria digitata', 'Thallus', 'Laminarin', 'Polysaccharide', 'β-Glucan', 'High', 'Major', 'Storage β-glucan contributing immunomodulatory activity and supporting innate immunity.', NULL),
  (NULL, 'Kelp', 'Laminaria digitata', 'Thallus', 'Mannitol', 'Carbohydrate', 'Sugar alcohol', 'Moderate', 'Major', 'Principal storage carbohydrate contributing osmotic balance and mild diuretic activity.', NULL),
  (NULL, 'Kelp', 'Laminaria digitata', 'Thallus', 'Fucoxanthin', 'Terpenoid', 'Carotenoid', 'Moderate', 'Major', 'Characteristic marine carotenoid contributing antioxidant and metabolic-support activity.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal constituent contributing anxiolytic, calming, antimicrobial, and analgesic activity.', 'Lavender is another herb whose medicinal activity depends on the synergy between a volatile oil and non-volatile polyphenols. While linalool and linalyl acetate dominate both the aroma and pharmacology, rosmarinic acid and ursolic acid contribute important anti-inflammatory and antioxidant effects, particularly in whole-herb preparations. Including both fractions gives a more representative phytochemical fingerprint than focusing solely on the essential oil.'),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Linalyl acetate', 'Terpenoid', 'Monoterpene ester', 'High', 'Major', 'Major ester contributing sedative, anxiolytic, and antispasmodic activity while defining the characteristic aroma.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Lavandulol', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene alcohol contributing calming and antimicrobial activity.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Terpinen-4-ol', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Contributes antimicrobial activity and complements the essential oil profile.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Moderate', 'Major', 'Contributes antioxidant and anti-inflammatory activity, complementing the volatile oil fraction.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Low–Moderate', 'Present', 'Supports anti-inflammatory activity and tissue protection.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Macamide B', 'Lipid', 'Fatty acid amide', 'High', 'Marker', 'Principal macamide contributing adaptogenic activity and modulation of the endocannabinoid system.', 'Maca is chemically quite distinct from most herbs in the database. Its defining constituents are the macamides, a unique family of fatty acid amides that are essentially restricted to Lepidium meyenii and are thought to underlie many of its adaptogenic and fertility-related effects. Including both the glucosinolate/isothiocyanate system and the macamides produces a phytochemical fingerprint that clearly distinguishes maca from other Brassicaceae herbs such as Horseradish, despite their shared glucosinolate chemistry.'),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'N-Benzylhexadecanamide', 'Lipid', 'Fatty acid amide', 'High', 'Major', 'Characteristic macamide contributing neuroprotective and energy-supporting activity.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Macaridine', 'Alkaloid', 'Imidazole alkaloid', 'Moderate', 'Major', 'Characteristic alkaloid contributing to the unique phytochemical profile of maca.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Benzyl glucosinolate (Glucotropaeolin)', 'Glycoside', 'Glucosinolate', 'Moderate', 'Major', 'Characteristic glucosinolate yielding benzyl isothiocyanate and contributing antimicrobial activity.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Benzyl isothiocyanate', 'Organosulfur compound', 'Isothiocyanate', 'Moderate', 'Present', 'Hydrolysis product of glucotropaeolin contributing antimicrobial and chemoprotective activity.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'β-Sitosterol', 'Sterol', 'Phytosterol', 'Low–Moderate', 'Present', 'Supports anti-inflammatory activity and complements the lipid fraction.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'High', 'Marker', 'Principal phenolic constituent contributing antiviral, anxiolytic, antioxidant, and anti-inflammatory activity.', 'Lemon balm is an excellent example of a herb whose medicinal activity depends on both volatile monoterpenes and non-volatile caffeic acid derivatives. The volatile oil is highly variable among chemotypes, but rosmarinic acid is consistently abundant and serves as a more reliable phytochemical marker than any single terpene. Including both fractions provides a stable chemical fingerprint while still capturing the herb''s characteristic aroma and antiviral activity.'),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Citral (Geranial + Neral)', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Principal aldehydic monoterpenes contributing antiviral, antimicrobial, and calming activity while defining the characteristic lemon aroma.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Citronellal', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Contributes calming, antispasmodic, and insect-repellent activity.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'β-Caryophyllene', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Contributes anti-inflammatory activity and complements the essential oil profile.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Caffeic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Moderate', 'Present', 'Supports antioxidant activity and serves as a precursor to rosmarinic acid.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity while complementing the phenolic fraction.', NULL),
  (NULL, 'Lemon Verbena', 'Aloysia citrodora', 'Leaf', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Marker', 'Principal phenylethanoid glycoside contributing antioxidant, anti-inflammatory, and tissue-protective activity.', 'Lemon Verbena bridges two phytochemical themes found elsewhere in the database. Its citral-rich volatile oil aligns it with aromatic lemon-scented herbs, while its abundant verbascoside creates strong chemical overlap with herbs such as Figwort and Eyebright. This combination makes it chemically distinct despite its familiar aroma.'),
  (NULL, 'Lemon Verbena', 'Aloysia citrodora', 'Leaf', 'Citral (Geranial + Neral)', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Defines the characteristic lemon aroma while contributing digestive, antimicrobial, and calming activity.', NULL),
  (NULL, 'Lemon Verbena', 'Aloysia citrodora', 'Leaf', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Contributes digestive support and complements the characteristic volatile oil profile.', NULL),
  (NULL, 'Lemon Verbena', 'Aloysia citrodora', 'Leaf', 'Luteolin-7-diglucuronide', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'Lemon Verbena', 'Aloysia citrodora', 'Leaf', 'Apigenin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Complements the flavonoid profile with antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'Lemon Verbena', 'Aloysia citrodora', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Low–Moderate', 'Present', 'Supports antioxidant activity and complements the phenylethanoid-rich chemistry.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Glycyrrhizin', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal constituent responsible for demulcent, anti-inflammatory, antiviral, and adrenal-support activity.', 'Licorice possesses one of the richest flavonoid profiles in the database. Beyond the characteristic triterpenoid saponin glycyrrhizin, its pharmacology is strongly influenced by structurally diverse flavonoids, including flavanone glycosides, chalcones, and isoflavans. Recognizing these subclasses preserves chemically meaningful relationships with future Fabaceae herbs such as Red Clover, Kudzu, and Sophora.'),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Glycyrrhetinic acid', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Active aglycone contributing anti-inflammatory effects and modulation of corticosteroid metabolism.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Liquiritin', 'Flavonoid', 'Flavanone glycoside', 'High', 'Major', 'Characteristic flavonoid glycoside contributing antioxidant, anti-inflammatory, and spasmolytic activity.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Isoliquiritigenin', 'Flavonoid', 'Chalcone', 'Moderate', 'Major', 'Chalcone contributing antioxidant activity and phytoestrogenic effects while complementing the flavonoid profile.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Glabridin', 'Flavonoid', 'Isoflavan', 'Moderate', 'Major', 'Characteristic isoflavan contributing antioxidant, antimicrobial, and skin-protective activity.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Licochalcone A', 'Flavonoid', 'Isoflavone', 'Low–Moderate', 'Present', 'Characteristic chalcone contributing antimicrobial, anti-inflammatory, and antioxidant activity while complementing the flavonoid profile.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower with bract', 'Tiliroside', 'Flavonoid', 'Flavonol glycoside', 'High', 'Marker', 'Principal flavonoid contributing mild anxiolytic, anti-inflammatory, and antioxidant activity.', 'Linden combines a flavonoid-rich profile with demulcent polysaccharides, reflecting its dual traditional use as both a calming nervine and a soothing remedy for upper respiratory irritation. Tiliroside remains the defining phytochemical marker, while arabinogalactan provides a chemically defined representative of the mucilage fraction.'),
  (NULL, 'Linden', 'Tilia cordata', 'Flower with bract', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Major', 'Supports antioxidant activity and vascular protection.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower with bract', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Moderate', 'Major', 'Complements the flavonoid profile and contributes antioxidant activity.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower with bract', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Supports capillary integrity and complements the major flavonoids.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower with bract', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'Moderate', 'Major', 'Principal mucilage polysaccharide contributing demulcent activity for irritated respiratory and gastrointestinal mucosa.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower with bract', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the phenolic profile.', NULL),
  (132, 'Lobelia', 'Lobelia inflata', 'Aerial parts', 'Lobeline', 'Alkaloid', 'Piperidine alkaloid', 'High', 'Marker', 'Principal alkaloid responsible for respiratory stimulation, bronchodilation, and modulation of nicotinic acetylcholine receptors.', 'Lobelia is one of the clearest examples of an herb whose medicinal identity is defined by a family of closely related alkaloids rather than a single dominant constituent. '),
