  (83, 'Mallow', 'Malva sylvestris', 'Leaf & flower', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'High', 'Marker', 'Principal mucilage polysaccharide contributing demulcent activity for irritated respiratory, digestive, and urinary tissues.', 'Mallow is one of the clearest examples of a mucilage-dominated medicinal herb. Unlike marshmallow, whose chemistry is dominated by root polysaccharides, Malva sylvestris derives much of its demulcent activity from the polysaccharides of the leaf and flower, accompanied by anthocyanins and flavonoids that contribute antioxidant and tissue-protective effects. This combination gives Mallow a distinctive phytochemical fingerprint while remaining faithful to the database''s emphasis on characteristic constituents.'),
  (83, 'Mallow', 'Malva sylvestris', 'Leaf & flower', 'Rhamnogalacturonan', 'Polysaccharide', 'Pectin', 'High', 'Major', 'Major pectic polysaccharide contributing soothing, moisture-retaining, and mucosal protective activity.', NULL),
  (83, 'Mallow', 'Malva sylvestris', 'Leaf & flower', 'Malvidin-3-glucoside', 'Flavonoid', 'Anthocyanin', 'Moderate', 'Major', 'Characteristic anthocyanin contributing antioxidant activity and the flower''s purple coloration.', NULL),
