  (83, 'Mallow', 'Malva sylvestris', 'Leaf & flower', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity while complementing the demulcent polysaccharide fraction.', NULL),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'High', 'Marker', 'Principal mucilage polysaccharide providing demulcent activity and protecting irritated mucous membranes.', 'Marshmallow is one of the archetypal demulcent herbs, with medicinal activity dominated by structurally diverse mucilage polysaccharides rather than low-molecular-weight phytochemicals. Representing the principal polysaccharide families rather than the generic term "mucilage" produces a chemically meaningful fingerprint while remaining faithful to the database''s preference for defined constituents.'),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Rhamnogalacturonan', 'Polysaccharide', 'Pectin', 'High', 'Major', 'Major pectic polysaccharide contributing mucosal soothing, hydration, and barrier protection.', NULL),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Arabinan', 'Polysaccharide', 'Arabinan', 'Moderate', 'Major', 'Contributes to the root''s demulcent mucilage, helping soothe and protect irritated mucous membranes.', NULL),
