  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Salicylaldehyde', 'Phenylpropanoid', 'Aromatic aldehyde', 'High', 'Marker', 'Characteristic salicylate precursor contributing anti-inflammatory and analgesic activity.', 'Meadowsweet''s chemistry is unusual because it combines salicylate derivatives with ellagitannins, producing both anti-inflammatory and gastric-protective effects. Unlike willow, where salicin predominates, Filipendula ulmaria is characterized by a mixture of volatile and glycosidic salicylates, making its phytochemical fingerprint distinct despite similar traditional uses.'),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Spiraein (Salicylaldehyde glycoside)', 'Glycoside', 'Phenolic glycoside', 'High', 'Major', 'Characteristic salicylate glycoside contributing analgesic and anti-inflammatory activity.', NULL),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Monotropitoside', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Major', 'Major salicylate glycoside contributing anti-inflammatory activity and serving as a precursor to volatile salicylates', NULL),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Rugosin D', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Major ellagitannin contributing astringent, antioxidant, and mucosal protective activity.', NULL),
