  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Complements the flavonoid profile with antioxidant activity.', NULL),
  (206, 'Milk Thistle', 'Silybum marianum', 'Seed', 'Silibinin (Silybin A + B)', 'Flavonoid', 'Flavonolignan', 'High', 'Marker', 'Principal flavonolignan complex responsible for hepatoprotective, antioxidant, and membrane-stabilizing activity.', 'Milk thistle is one of the few medicinal plants whose pharmacology is dominated almost entirely by a single family of compounds: the flavonolignans collectively known as silymarin. Following your editorial rules, the profile lists the principal individual flavonolignans rather than the mixture silymarin, producing a chemically precise fingerprint while preserving the relationships among the individual constituents.'),
  (206, 'Milk Thistle', 'Silybum marianum', 'Seed', 'Isosilybin A', 'Flavonoid', 'Flavonolignan', 'Moderate', 'Major', 'Characteristic flavonolignan contributing antioxidant and hepatoprotective activity.', NULL),
  (206, 'Milk Thistle', 'Silybum marianum', 'Seed', 'Silychristin', 'Flavonoid', 'Flavonolignan', 'Moderate', 'Major', 'Contributes antioxidant activity and complements the silymarin complex.', NULL),
  (206, 'Milk Thistle', 'Silybum marianum', 'Seed', 'Silydianin', 'Flavonoid', 'Flavonolignan', 'Moderate', 'Present', 'Characteristic flavonolignan supporting the overall hepatoprotective profile.', NULL),
  (206, 'Milk Thistle', 'Silybum marianum', 'Seed', 'Taxifolin', 'Flavonoid', 'Flavanonol', 'Low–Moderate', 'Present', 'Biosynthetic precursor of the flavonolignans contributing antioxidant activity.', NULL),
  (211, 'Mistletoe', 'Viscum album', 'Leaf & stem', 'Viscotoxin A3', 'Protein', 'Thionin', 'High', 'Marker', 'Principal cytotoxic peptide contributing immunomodulatory activity and the herb''s characteristic biological effects.', 'Mistletoe is one of the rare herbs where proteins are unquestionably defining medicinal constituents. Both the mistletoe lectins and viscotoxins are central to its pharmacology and are the basis of standardized injectable preparations used in European phytotherapy.'),
  (211, 'Mistletoe', 'Viscum album', 'Leaf & stem', 'Mistletoe lectin I', 'Protein', 'Lectin', 'High', 'Marker', 'Characteristic lectin contributing immunomodulatory and cytotoxic activity.', NULL),
  (211, 'Mistletoe', 'Viscum album', 'Leaf & stem', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Major', 'Contributes anti-inflammatory activity and complements the protein fraction.', NULL),
  (211, 'Mistletoe', 'Viscum album', 'Leaf & stem', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Moderate', 'Major', 'Supports anti-inflammatory and tissue-protective activity.', NULL),
  (211, 'Mistletoe', 'Viscum album', 'Leaf & stem', 'Syringaresinol diglucoside', 'Glycoside', 'Lignan glycoside', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the immunomodulatory protein and triterpenoid fractions.', NULL),
  (211, 'Mistletoe', 'Viscum album', 'Leaf & stem', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the triterpenoid profile.', NULL),
  (131, 'Motherwort', 'Leonurus cardiaca', 'Aerial parts', 'Lavandulifolioside', 'Polyphenol', 'Phenylethanoid glycoside', 'Low–Moderate', 'Present', 'Characteristic phenylethanoid glycoside contributing antioxidant activity and complementing the herb''s cardiotonic constituents.', 'Motherwort is chemically unusual because its traditional cardiovascular and gynecological uses are associated with a distinctive group of guanidine alkaloids, particularly leonurine, rather than the terpene or flavonoid constituents that dominate many other members of the mint family. These alkaloids form a recognizable chemical signature for the genus and warrant dedicated subclasses in the database.'),
  (131, 'Motherwort', 'Leonurus cardiaca', 'Aerial parts', 'Stachydrine', 'Alkaloid', 'Pyrrolidine alkaloid', 'High', 'Major', 'Characteristic alkaloid supporting cardioprotective and uterine tonic activity.', NULL),
