  (131, 'Motherwort', 'Leonurus cardiaca', 'Aerial parts', 'Leonurinine', 'Alkaloid', 'Guanidine alkaloid', 'Low–Moderate', 'Present', 'Minor guanidine alkaloid complementing the characteristic leonurine profile.', NULL),
  (115, 'Mugwort', 'Artemisia vulgaris', 'Aerial parts', 'α-Thujone', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Characteristic monoterpene ketone contributing aromatic bitter, digestive stimulant, and nervous system activity.', 'Mugwort''s chemistry reflects the characteristic Artemisia pattern of combining a volatile monoterpene-rich essential oil with sesquiterpene lactones responsible for much of its bitter tonic activity. Unlike wormwood, mugwort contains little or no thujone in many chemotypes, making artemisia ketone a more representative marker for the species.'),
  (115, 'Mugwort', 'Artemisia vulgaris', 'Aerial parts', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Contributes aromatic, digestive, and respiratory-supporting activity.', NULL),
  (115, 'Mugwort', 'Artemisia vulgaris', 'Aerial parts', 'Camphor', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Provides aromatic stimulant and mild topical analgesic activity.', NULL),
