  (115, 'Mugwort', 'Artemisia vulgaris', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the terpene-rich chemistry.', NULL),
  (115, 'Mugwort', 'Artemisia vulgaris', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Supports antioxidant activity and complements the bitter constituents.', NULL),
  (61, 'Mullein', 'Verbascum thapsus', 'Leaf', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Marker', 'Principal phenylethanoid glycoside contributing anti-inflammatory, antioxidant, and antimicrobial activity.', 'Mullein''s medicinal profile is defined by the combination of phenylethanoid glycosides and iridoid glycosides, with relatively little dependence on volatile oils. This chemistry aligns it more closely with herbs such as Plantain, Eyebright, and Figwort than with the aromatic respiratory herbs, illustrating the value of constituent-based relationships over traditional therapeutic groupings.'),
  (61, 'Mullein', 'Verbascum thapsus', 'Leaf', 'Aucubin', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Characteristic iridoid contributing antimicrobial activity and supporting respiratory tissue repair.', NULL),
  (61, 'Mullein', 'Verbascum thapsus', 'Leaf', 'Catalpol', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Supports anti-inflammatory activity and complements the iridoid profile.', NULL),
  (61, 'Mullein', 'Verbascum thapsus', 'Leaf', 'Luteolin-7-O-glucoside', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity while complementing the iridoid and phenylethanoid glycosides.', NULL),
  (61, 'Mullein', 'Verbascum thapsus', 'Leaf', 'Apigenin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity while complementing the phenolic fraction.', NULL),
  (61, 'Mullein', 'Verbascum thapsus', 'Leaf', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Low–Moderate', 'Present', 'Supports anti-inflammatory activity and complements the respiratory-active constituents.', NULL),
  (116, 'Mustard', 'Brassica spp.', 'Seed', 'Sinigrin', 'Glycoside', 'Glucosinolate', 'High', 'Marker', 'Principal glucosinolate serving as the precursor to pungent isothiocyanates responsible for rubefacient and antimicrobial activity.', 'Mustard exemplifies the characteristic glucosinolate–isothiocyanate defense system of the Brassicaceae. Unlike horseradish, which is dominated by sinigrin, using Brassica spp. allows both sinigrin (black/brown mustard) and sinalbin (white mustard) to be represented, providing a broader yet still characteristic phytochemical fingerprint for medicinal mustard seed.'),
  (116, 'Mustard', 'Brassica spp.', 'Seed', 'Allyl isothiocyanate', 'Organosulfur compound', 'Isothiocyanate', 'High', 'Marker', 'Principal hydrolysis product responsible for the characteristic pungency, rubefacient, and antimicrobial activity of black and brown mustard.', NULL),
  (116, 'Mustard', 'Brassica spp.', 'Seed', 'Sinalbin', 'Glycoside', 'Glucosinolate', 'Moderate', 'Major', 'Characteristic glucosinolate of white mustard contributing pungency through enzymatic hydrolysis.', NULL),
