  (178, 'Oat', 'Avena sativa', 'Milky seed', 'Avenacoside A', 'Glycoside', 'Steroidal glycoside', 'High', 'Marker', 'Characteristic steroidal glycoside contributing to the restorative and nutritive properties of milky oat seed.', 'The chemistry of milky oat seed (avenanthramides and steroidal constituents) differs substantially from oat straw, which is dominated by flavonoids and silica-associated compounds.'),
  (178, 'Oat', 'Avena sativa', 'Milky seed', 'Avenanthramide A', 'Polyphenol', 'Phenylpropanoid ester', 'High', 'Marker', 'Principal phenolic amide contributing antioxidant, anti-inflammatory, and soothing activity.', NULL),
