  (106, 'Olive', 'Olea europaea', 'Leaf', 'Oleuropein', 'Glycoside', 'Secoiridoid glycoside', 'High', 'Marker', 'Principal secoiridoid responsible for antioxidant, cardioprotective, antihypertensive, and antimicrobial activity.', 'Olive leaf is chemically defined by its exceptionally high concentration of secoiridoid glycosides, especially oleuropein, which distinguishes it from nearly every other medicinal herb in the database. The accompanying hydroxytyrosol, verbascoside, and flavonoids reinforce the herb''s antioxidant and cardiovascular actions while providing meaningful constituent overlap with other iridoid- and phenylethanoid-rich herbs.'),
  (106, 'Olive', 'Olea europaea', 'Leaf', 'Hydroxytyrosol', 'Phenylpropanoid', 'Phenolic alcohol', 'High', 'Major', 'Potent antioxidant phenolic alcohol produced from oleuropein hydrolysis, contributing cardioprotective and anti-inflammatory activity.', NULL),
  (106, 'Olive', 'Olea europaea', 'Leaf', 'Ligstroside', 'Glycoside', 'Secoiridoid glycoside', 'Moderate', 'Major', 'Characteristic secoiridoid glycoside complementing oleuropein and contributing antioxidant activity.', NULL),
  (106, 'Olive', 'Olea europaea', 'Leaf', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity while complementing the secoiridoid fraction.', NULL),
  (106, 'Olive', 'Olea europaea', 'Leaf', 'Luteolin-7-O-glucoside', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Present', 'Characteristic flavonoid glycoside contributing antioxidant activity and vascular protection.', NULL),
  (106, 'Olive', 'Olea europaea', 'Leaf', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'Low–Moderate', 'Present', 'Supports anti-inflammatory activity and complements the phenolic constituents.', NULL),
  (208, 'Onion', 'Allium cepa', 'Bulb', 'Isoalliin', 'Organosulfur compound', 'Sulfoxide', 'High', 'Marker', 'Principal sulfur precursor contributing to the formation of characteristic bioactive sulfur compounds after tissue disruption.', 'Onion shares the characteristic organosulfur chemistry of the genus Allium but differs substantially from garlic. Whereas garlic is dominated by alliin → allicin, onion is characterized by isoalliin, cepaenes, and abundant quercetin. This produces a distinct phytochemical fingerprint despite the close botanical relationship.'),
  (208, 'Onion', 'Allium cepa', 'Bulb', 'Dipropyl thiosulfinate', 'Organosulfur compound', 'Thiosulfinate', 'High', 'Major', 'Principal thiosulfinate contributing antimicrobial activity and characteristic fresh-onion pungency following tissue disruption.', NULL),
  (208, 'Onion', 'Allium cepa', 'Bulb', 'Cepaene', 'Organosulfur compound', 'Sulfide', 'Moderate', 'Major', 'Characteristic sulfur compound contributing anti-inflammatory and antiplatelet activity.', NULL),
  (208, 'Onion', 'Allium cepa', 'Bulb', 'Quercetin', 'Flavonoid', 'Flavonol', 'High', 'Major', 'Principal flavonoid contributing antioxidant, anti-inflammatory, and vascular protective activity.', NULL),
  (208, 'Onion', 'Allium cepa', 'Bulb', 'Quercetin-4′-O-glucoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Major flavonoid glycoside serving as a natural storage form of quercetin.', NULL),
  (208, 'Onion', 'Allium cepa', 'Bulb', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Complements the flavonoid profile with antioxidant activity.', NULL),
  (33, 'Oregon Grape', 'Mahonia aquifolium', 'Root & stem bark', 'Berberine', 'Alkaloid', 'Protoberberine alkaloid', 'High', 'Marker', 'Principal isoquinoline alkaloid contributing antimicrobial, bitter tonic, cholagogue, and hepatobiliary activity.', 'Oregon grape is one of the clearest examples of a medicinal herb whose activity is dominated by a family of closely related isoquinoline alkaloids. Rather than relying solely on berberine, including the principal companion alkaloids creates a much more representative phytochemical fingerprint and distinguishes Mahonia from other berberine-containing genera such as Berberis and Hydrastis.'),
  (33, 'Oregon Grape', 'Mahonia aquifolium', 'Root & stem bark', 'Jatrorrhizine', 'Alkaloid', 'Protoberberine alkaloid', 'High', 'Major', 'Characteristic protoberberine alkaloid complementing berberine''s antimicrobial and bitter tonic activity.', NULL),
  (33, 'Oregon Grape', 'Mahonia aquifolium', 'Root & stem bark', 'Palmatine', 'Alkaloid', 'Protoberberine alkaloid', 'Moderate', 'Major', 'Contributes antimicrobial and anti-inflammatory activity while complementing the principal alkaloids.', NULL),
  (33, 'Oregon Grape', 'Mahonia aquifolium', 'Root & stem bark', 'Columbamine', 'Alkaloid', 'Protoberberine alkaloid', 'Moderate', 'Present', 'Characteristic protoberberine alkaloid contributing to the herb''s bitter and antimicrobial profile.', NULL),
  (33, 'Oregon Grape', 'Mahonia aquifolium', 'Root & stem bark', 'Magnoflorine', 'Alkaloid', 'Aporphine alkaloid', 'Low–Moderate', 'Present', 'Complements the isoquinoline alkaloid profile and contributes mild anti-inflammatory activity.', NULL),
  (33, 'Oregon Grape', 'Mahonia aquifolium', 'Root & stem bark', 'Oxyacanthine', 'Alkaloid', 'Benzylisoquinoline alkaloid', 'Low–Moderate', 'Present', 'Characteristic bisbenzylisoquinoline alkaloid complementing the antimicrobial and bitter alkaloid profile.', NULL),
  (104, 'Osha', 'Ligusticum porteri', 'Root', 'Z-Ligustilide', 'Phthalide', 'Phthalide', 'High', 'Marker', 'Principal phthalide contributing respiratory stimulant, antispasmodic, and circulatory activity.', 'Osha shares a characteristic Apiaceae chemistry with herbs such as Angelica and Dong Quai, particularly through its abundant phthalides, but differs in emphasizing respiratory applications rather than gynecological uses. Including both phthalides and polyacetylenes provides a representative phytochemical fingerprint while maintaining the database''s focus on characteristic, pharmacologically important constituents.'),
  (104, 'Osha', 'Ligusticum porteri', 'Root', 'Butylidenephthalide', 'Phthalide', 'Phthalide', 'High', 'Major', 'Characteristic phthalide complementing the respiratory and smooth muscle effects of ligustilide.', NULL),
  (104, 'Osha', 'Ligusticum porteri', 'Root', 'Ferulic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Moderate', 'Major', 'Contributes antioxidant and anti-inflammatory activity while complementing the phthalide fraction.', NULL),
  (104, 'Osha', 'Ligusticum porteri', 'Root', 'Falcarindiol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Present', 'Contributes antimicrobial and anti-inflammatory activity characteristic of many Apiaceae roots.', NULL),
  (104, 'Osha', 'Ligusticum porteri', 'Root', 'Myristicin', 'Phenylpropanoid', 'Phenylpropene', 'Low–Moderate', 'Present', 'Contributes aromatic, antimicrobial, and respiratory-supporting activity while complementing the characteristic phthalides.', NULL),
  (104, 'Osha', 'Ligusticum porteri', 'Root', 'Terpinen-4-ol', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Complements the volatile oil profile with antimicrobial and respiratory activity.', NULL),
  (120, 'Parsley', 'Petroselinum crispum', 'Seed', 'Apiol', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Marker', 'Principal phenylpropanoid contributing carminative, urinary tract, and emmenagogue activity.', 'I chose to profile the seed, as medicinal parsley is traditionally represented by the seed and its volatile oil rather than the culinary leaf. The combination of phenylpropenes, furanocoumarins, and polyacetylenes gives parsley a phytochemical profile closely related to other medicinal Apiaceae while remaining distinct through its high apiol content.'),
  (120, 'Parsley', 'Petroselinum crispum', 'Seed', 'Myristicin', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Major', 'Characteristic aromatic constituent contributing carminative and urinary tract activity.', NULL),
  (120, 'Parsley', 'Petroselinum crispum', 'Seed', 'Isopimpinellin', 'Coumarin', 'Furanocoumarin', 'Moderate', 'Major', 'Characteristic furanocoumarin contributing antimicrobial activity and complementing the seed''s aromatic phenylpropanoids.', NULL),
  (120, 'Parsley', 'Petroselinum crispum', 'Seed', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity.', NULL),
  (120, 'Parsley', 'Petroselinum crispum', 'Seed', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Complements the flavonoid profile with antioxidant activity.', NULL),
  (120, 'Parsley', 'Petroselinum crispum', 'Seed', 'Falcarinol', 'Polyacetylene', 'Polyacetylene', 'Low–Moderate', 'Present', 'Characteristic Apiaceae polyacetylene contributing antimicrobial and anti-inflammatory activity.', NULL),
  (137, 'Passionflower', 'Passiflora incarnata', 'Aerial parts', 'Vitexin', 'Flavonoid', 'Flavone glycoside', 'High', 'Marker', 'Principal flavonoid contributing anxiolytic activity through modulation of GABAergic signaling.', 'Passionflower is unusual in that its medicinal activity is associated primarily with a family of C-glycosyl flavones rather than volatile oils or alkaloids. The profile emphasizes these characteristic flavonoids, which are consistently recognized across modern pharmacopoeias and better represent the herb than the historically overemphasized harmala alkaloids, now known to occur only in trace amounts or inconsistently.'),
  (137, 'Passionflower', 'Passiflora incarnata', 'Aerial parts', 'Isovitexin', 'Flavonoid', 'Flavone glycoside', 'High', 'Major', 'Characteristic flavonoid glycoside complementing vitexin in the herb''s calming activity.', NULL),
  (137, 'Passionflower', 'Passiflora incarnata', 'Aerial parts', 'Orientin', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Contributes antioxidant and neuroprotective activity while complementing the flavonoid profile.', NULL),
  (137, 'Passionflower', 'Passiflora incarnata', 'Aerial parts', 'Isoorientin', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic C-glycosyl flavone contributing antioxidant and anxiolytic activity.', NULL),
  (137, 'Passionflower', 'Passiflora incarnata', 'Aerial parts', 'Chrysin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Contributes anxiolytic activity and complements the characteristic flavone glycosides.', NULL),
  (137, 'Passionflower', 'Passiflora incarnata', 'Aerial parts', 'Schaftoside', 'Flavonoid', 'Flavone glycoside', 'Low–Moderate', 'Present', 'Characteristic C-glycosyl flavone contributing antioxidant activity and complementing the anxiolytic flavonoid profile.', NULL),
  (291, 'Pau d''Arco', 'Handroanthus impetiginosus (syn. Tabebuia impetiginosa)', 'Inner bark', 'Lapachol', 'Polyphenol', 'Naphthoquinone', 'High', 'Marker', 'Principal naphthoquinone contributing antimicrobial, antifungal, and antiproliferative activity.', 'Pau d''Arco is one of the few medicinal herbs whose chemistry is dominated by naphthoquinones. Rather than emphasizing the many minor phenolics reported from the bark, this profile focuses on the characteristic lapachol derivatives that consistently distinguish Handroanthus impetiginosus from other medicinal barks and account for much of its traditional antimicrobial reputation.'),
  (291, 'Pau d''Arco', 'Handroanthus impetiginosus', 'Inner bark', 'β-Lapachone', 'Polyphenol', 'Naphthoquinone', 'High', 'Major', 'Characteristic naphthoquinone contributing antimicrobial activity and redox-mediated biological effects.', NULL),
  (291, 'Pau d''Arco', 'Handroanthus impetiginosus', 'Inner bark', 'Dehydro-α-lapachone', 'Polyphenol', 'Naphthoquinone', 'Moderate', 'Major', 'Characteristic naphthoquinone complementing the lapachol profile.', NULL),
  (291, 'Pau d''Arco', 'Handroanthus impetiginosus', 'Inner bark', 'Deoxylapachol', 'Polyphenol', 'Naphthoquinone', 'Moderate', 'Present', 'Contributes antimicrobial activity and complements the characteristic quinone fraction.', NULL),
  (291, 'Pau d''Arco', 'Handroanthus impetiginosus', 'Inner bark', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the quinone-rich chemistry.', NULL),
  (291, 'Pau d''Arco', 'Handroanthus impetiginosus', 'Inner bark', 'Dehydrolapachone', 'Polyphenol', 'Naphthoquinone', 'Low–Moderate', 'Present', 'Characteristic naphthoquinone that complements the lapachol derivatives and contributes to the bark''s antimicrobial profile.', NULL),
  (NULL, 'Peony', 'Paeonia lactiflora', 'Root', 'Paeoniflorin', 'Glycoside', 'Monoterpene glycoside', 'High', 'Marker', 'Principal constituent contributing antispasmodic, analgesic, anti-inflammatory, and immunomodulatory activity.', 'Peony is one of the clearest examples of a medicinal herb whose chemistry is dominated by a family of closely related monoterpene glycosides. Rather than listing unrelated minor constituents, this profile emphasizes the paeoniflorin family, which defines both the pharmacology and the chemotaxonomy of Paeonia lactiflora. This follows the same editorial approach used for Milk Thistle (flavonolignans) and Kava (kavalactones).'),
  (NULL, 'Peony', 'Paeonia lactiflora', 'Root', 'Albiflorin', 'Glycoside', 'Monoterpene glycoside', 'High', 'Major', 'Major companion glycoside contributing antispasmodic and neuroprotective activity.', NULL),
  (NULL, 'Peony', 'Paeonia lactiflora', 'Root', 'Oxypaeoniflorin', 'Glycoside', 'Monoterpene glycoside', 'Moderate', 'Major', 'Characteristic monoterpene glycoside complementing the paeoniflorin profile.', NULL),
  (NULL, 'Peony', 'Paeonia lactiflora', 'Root', 'Benzoylpaeoniflorin', 'Glycoside', 'Monoterpene glycoside', 'Moderate', 'Present', 'Characteristic derivative contributing to the distinctive monoterpene glycoside chemistry of peony.', NULL),
  (NULL, 'Peony', 'Paeonia lactiflora', 'Root', 'Paeonol', 'Phenylpropanoid', 'Phenolic ketone', 'Moderate', 'Major', 'Contributes anti-inflammatory, analgesic, and antioxidant activity while complementing the glycoside fraction.', NULL)
INSERT INTO herbal.constituent_profiles
  (herb_id, common_name, latin_name, plant_part, constituent, class, subclass, importance, status, notes, editorial_note)
VALUES
  (NULL, 'Peony', 'Paeonia lactiflora', 'Root', 'Benzoic acid', 'Phenylpropanoid', 'Aromatic acid', 'Low–Moderate', 'Present', 'Characteristic aromatic acid contributing to the root''s anti-inflammatory profile and complementing the paeoniflorin glycosides.', NULL),
  (NULL, 'Pipsissewa', 'Chimaphila umbellata', 'Aerial parts', 'Chimaphilin', 'Polyphenol', 'Naphthoquinone', 'High', 'Marker', 'Principal naphthoquinone contributing urinary antiseptic, antimicrobial, and anti-inflammatory activity.', 'Pipsissewa combines two phytochemical themes that rarely occur together: hydroquinone glycosides typical of urinary antiseptic herbs and the distinctive naphthoquinone chimaphilin, which serves as an excellent chemotaxonomic marker for the genus. This combination clearly distinguishes it from related Ericaceae herbs such as uva ursi despite their shared arbutin chemistry.'),
  (NULL, 'Pipsissewa', 'Chimaphila umbellata', 'Aerial parts', 'Arbutin', 'Glycoside', 'Phenolic glycoside', 'High', 'Major', 'Characteristic glycoside contributing urinary antiseptic activity through hydrolysis to hydroquinone.', NULL),
  (NULL, 'Pipsissewa', 'Chimaphila umbellata', 'Aerial parts', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Moderate', 'Major', 'Contributes anti-inflammatory activity and complements the urinary tract actions of the herb.', NULL),
  (NULL, 'Pipsissewa', 'Chimaphila umbellata', 'Aerial parts', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Contributes antioxidant activity and complements the phenolic profile.', NULL),
  (NULL, 'Pipsissewa', 'Chimaphila umbellata', 'Aerial parts', 'Methyl arbutin', 'Glycoside', 'Phenolic glycoside', 'Low–Moderate', 'Present', 'Characteristic hydroquinone glycoside complementing arbutin and reinforcing the herb''s traditional urinary antiseptic activity.', NULL),
  (NULL, 'Pipsissewa', 'Chimaphila umbellata', 'Aerial parts', 'Isohomoarbutin', 'Glycoside', 'Phenolic glycoside', 'Low–Moderate', 'Present', 'Characteristic hydroquinone glycoside complementing arbutin and supporting urinary antiseptic activity.', NULL),
  (85, 'Plantain', 'Plantago major', 'Leaf', 'Aucubin', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid contributing wound healing, antimicrobial, and anti-inflammatory activity.', 'Plantain is an excellent example of an herb whose medicinal profile is defined by the combination of iridoid glycosides and phenylethanoid glycosides. Including both verbascoside and plantamajoside distinguishes it from related wound-healing herbs while highlighting the chemistry responsible for its traditional vulnerary, antimicrobial, and anti-inflammatory uses.'),
  (85, 'Plantain', 'Plantago major', 'Leaf', 'Catalpol', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Major iridoid complementing aucubin and supporting tissue repair.', NULL),
  (85, 'Plantain', 'Plantago major', 'Leaf', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Major', 'Principal phenylethanoid glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (85, 'Plantain', 'Plantago major', 'Leaf', 'Plantamajoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Characteristic phenylethanoid glycoside contributing antimicrobial and wound-healing activity.', NULL),
  (85, 'Plantain', 'Plantago major', 'Leaf', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Contributes antioxidant and anti-inflammatory activity while complementing the iridoid and phenylethanoid glycosides.', NULL),
  (85, 'Plantain', 'Plantago major', 'Leaf', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Low–Moderate', 'Present', 'Supports anti-inflammatory activity and complements the wound-healing constituents.', NULL),
  (67, 'Pleurisy Root', 'Asclepias tuberosa', 'Root', 'Asclepiadin', 'Steroid', 'Steroidal glycoside', 'High', 'Marker', 'Principal cardiac glycoside contributing the herb''s characteristic cardiotonic and expectorant activity.', 'Pleurisy Root is chemically distinct among North American respiratory herbs because it contains cardenolides (cardiac glycosides), albeit in much lower concentrations than Digitalis or Convallaria. These compounds are sufficiently characteristic to warrant emphasizing them over the more ubiquitous flavonoids, providing a phytochemical fingerprint that aligns well with the traditional Eclectic literature while remaining chemically precise.'),
  (67, 'Pleurisy Root', 'Asclepias tuberosa', 'Root', 'Asclepin', 'Steroid', 'Cardiac glycoside', 'Moderate', 'Major', 'Characteristic cardenolide complementing asclepiadin and contributing to the root''s distinctive cardiotonic chemistry.', NULL),
  (67, 'Pleurisy Root', 'Asclepias tuberosa', 'Root', 'Calotropin', 'Steroid', 'Steroidal glycoside', 'Moderate', 'Present', 'Cardiac glycoside contributing to the characteristic steroidal profile of the root.', NULL),
  (67, 'Pleurisy Root', 'Asclepias tuberosa', 'Root', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Contributes antioxidant activity and complements the steroidal constituents.', NULL),
  (67, 'Pleurisy Root', 'Asclepias tuberosa', 'Root', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Provides antioxidant activity while complementing the flavonoid profile.', NULL),
  (67, 'Pleurisy Root', 'Asclepias tuberosa', 'Root', 'Lupeol', 'Terpenoid', 'Pentacyclic triterpenoid', 'Low–Moderate', 'Present', 'Supports anti-inflammatory activity and complements the herb''s characteristic steroidal constituents.', NULL),
  (35, 'Poke', 'Phytolacca americana', 'Root', 'Phytolaccatoxin', 'Triterpenoid', 'Triterpenoid saponin', 'High', 'Marker', 'Principal triterpenoid saponin contributing the herb''s characteristic lymphatic stimulant and irritant activity.', 'Poke is one of the few North American medicinal herbs whose chemistry is overwhelmingly dominated by triterpenoid saponins. Rather than emphasizing ubiquitous flavonoids or phenolic acids, this profile focuses on the phytolaccatoxin/phytolaccoside family that defines both the pharmacology and toxicology of the root. This produces a much more distinctive phytochemical fingerprint consistent with your database philosophy.'),
  (35, 'Poke', 'Phytolacca americana', 'Root', 'Phytolaccigenin', 'Terpenoid', 'Pentacyclic triterpenoid', 'High', 'Major', 'Major sapogenin contributing to the biological activity of poke root saponins.', NULL),
  (35, 'Poke', 'Phytolacca americana', 'Root', 'Esculentoside A', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Characteristic triterpenoid saponin complementing the phytolaccatoxin fraction.', NULL),
  (35, 'Poke', 'Phytolacca americana', 'Root', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Present', 'Characteristic triterpenoid contributing anti-inflammatory activity and complementing the root''s saponin-rich chemistry.', NULL),
  (35, 'Poke', 'Phytolacca americana', 'Root', 'α-Spinasterol', 'Sterol', 'Phytosterol', 'Low–Moderate', 'Present', 'Contributes anti-inflammatory activity while complementing the triterpenoid profile.', NULL),
  (35, 'Poke', 'Phytolacca americana', 'Root', 'Phytolaccoside B', 'Glycoside', 'Triterpenoid saponin', 'Low–Moderate', 'Present', 'Characteristic saponin expanding the representative phytolacca saponin profile.', NULL),
  (123, 'Prickly Ash', 'Zanthoxylum americanum', 'Bark', 'Chelerythrine', 'Alkaloid', 'Benzophenanthridine alkaloid', 'High', 'Marker', 'Principal alkaloid contributing circulatory stimulant, antimicrobial, and analgesic activity.', 'Prickly Ash is chemically distinct among North American circulatory herbs because it combines benzophenanthridine alkaloids, furoquinoline alkaloids, and coumarins. While many texts emphasize only its pungent taste and volatile oil, its alkaloid profile provides a much more distinctive chemotaxonomic fingerprint and better explains its overlap with other members of the Rutaceae.'),
  (123, 'Prickly Ash', 'Zanthoxylum americanum', 'Bark', 'Nitidine', 'Alkaloid', 'Benzophenanthridine alkaloid', 'High', 'Major', 'Characteristic alkaloid complementing the antimicrobial and circulatory activity of chelerythrine.', NULL),
  (123, 'Prickly Ash', 'Zanthoxylum americanum', 'Bark', 'γ-Fagarine', 'Alkaloid', 'Furoquinoline alkaloid', 'Moderate', 'Major', 'Characteristic alkaloid contributing the distinctive chemistry of Zanthoxylum species and supporting antimicrobial activity.', NULL),
  (123, 'Prickly Ash', 'Zanthoxylum americanum', 'Bark', 'Herculin', 'Alkaloid', 'Furoquinoline alkaloid', 'Moderate', 'Present', 'Characteristic furoquinoline alkaloid contributing to the bark''s pungent circulatory stimulant profile while complementing γ-fagarine.', NULL),
  (123, 'Prickly Ash', 'Zanthoxylum americanum', 'Bark', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Contributes aromatic, digestive stimulant, and circulatory-supporting activity.', NULL),
  (123, 'Prickly Ash', 'Zanthoxylum americanum', 'Bark', 'Xanthyletin', 'Coumarin', 'Simple coumarin', 'Low–Moderate', 'Present', 'Characteristic coumarin contributing vasodilatory and antimicrobial activity.', NULL),
  (NULL, 'Psyllium', 'Plantago ovata', 'Seed husk', 'Arabinoxylan', 'Polysaccharide', 'Arabinoxylan', 'High', 'Marker', 'Principal gel-forming polysaccharide responsible for the bulk-forming laxative and demulcent actions of psyllium husk.', 'Psyllium husk is unusual because its medicinal activity is driven overwhelmingly by its complex arabinoxylan-rich mucilage, rather than small-molecule phytochemicals. For that reason, the profile emphasizes the principal polysaccharide families that define the husk''s gel-forming properties, while including only two low-molecular-weight constituents that are consistently documented for the species. This better reflects both the pharmacology and the characteristic chemistry of Plantago ovata.'),
  (NULL, 'Psyllium', 'Plantago ovata', 'Seed husk', 'Rhamnogalacturonan', 'Polysaccharide', 'Pectin', 'High', 'Major', 'Major pectic polysaccharide contributing water retention, viscosity, and mucosal protection.', NULL),
  (NULL, 'Psyllium', 'Plantago ovata', 'Seed husk', 'Arabinan', 'Polysaccharide', 'Arabinan', 'Moderate', 'Major', 'Structural polysaccharide that complements the mucilage network and contributes to gel formation.', NULL),
  (NULL, 'Psyllium', 'Plantago ovata', 'Seed husk', 'Galactan', 'Polysaccharide', 'Galactomannan', 'Low–Moderate', 'Present', 'Minor structural polysaccharide contributing to the architecture and hydration properties of the mucilage.', NULL),
  (NULL, 'Psyllium', 'Plantago ovata', 'Seed husk', 'Aucubin', 'Glycoside', 'Iridoid glycoside', 'Low–Moderate', 'Present', 'Characteristic iridoid glycoside contributing mild anti-inflammatory and tissue-protective activity.', NULL),
  (NULL, 'Psyllium', 'Plantago ovata', 'Seed husk', 'Plantamajoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Low–Moderate', 'Present', 'Characteristic phenylethanoid glycoside contributing antioxidant activity and complementing the mucilage-rich chemistry.', NULL),
  (42, 'Red Clover', 'Trifolium pratense', 'Flowering tops', 'Biochanin A', 'Flavonoid', 'Isoflavone', 'High', 'Marker', 'Principal isoflavone contributing phytoestrogenic, antioxidant, and menopausal-support activity.', 'Red Clover is one of the few medicinal herbs whose chemistry is overwhelmingly dominated by isoflavones. Rather than emphasizing ubiquitous flavonoids or phenolic acids, this profile focuses on the compounds that define both the herb''s pharmacology and its chemotaxonomy. The four principal isoflavones—biochanin A, formononetin, genistein, and daidzein—account for most of the herb''s characteristic phytoestrogenic activity, while the remaining constituents provide a representative fingerprint without diluting the profile with ubiquitous metabolites.'),
  (42, 'Red Clover', 'Trifolium pratense', 'Flowering tops', 'Formononetin', 'Flavonoid', 'Isoflavone', 'High', 'Major', 'Major isoflavone contributing phytoestrogenic activity and serving as a precursor to daidzein.', NULL),
  (42, 'Red Clover', 'Trifolium pratense', 'Flowering tops', 'Genistein', 'Flavonoid', 'Isoflavone', 'Moderate', 'Major', 'Contributes estrogen receptor modulation and antioxidant activity.', NULL),
  (42, 'Red Clover', 'Trifolium pratense', 'Flowering tops', 'Daidzein', 'Flavonoid', 'Isoflavone', 'Moderate', 'Major', 'Complements the characteristic isoflavone profile and contributes phytoestrogenic activity.', NULL),
  (42, 'Red Clover', 'Trifolium pratense', 'Flowering tops', 'Pratensin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Characteristic flavone contributing antioxidant activity and complementing the isoflavone-rich chemistry.', NULL),
  (42, 'Red Clover', 'Trifolium pratense', 'Flowering tops', 'Trifolirhizin', 'Flavonoid', 'Flavanone glycoside', 'Low–Moderate', 'Present', 'Characteristic flavonoid glycoside contributing antioxidant activity and expanding the representative flavonoid profile.', NULL),
  (11, 'Reishi', 'Ganoderma lucidum', 'Fruiting body', 'Ganoderic acid A', 'Terpenoid', 'Pentacyclic triterpenoid', 'High', 'Marker', 'Principal triterpenoid contributing immunomodulatory, hepatoprotective, and anti-inflammatory activity.', 'Reishi is one of the clearest examples of a medicinal fungus whose pharmacology is defined by two complementary constituent families: β-glucans, which account for much of its immunomodulatory activity, and lanostane-type triterpenoids, represented here by the ganoderic acids and ganodermanontriol. Rather than emphasizing miscellaneous sterols or proteins, this profile focuses on the constituents consistently recognized across pharmacopoeias as defining the medicinal chemistry of Ganoderma lucidum.'),
  (11, 'Reishi', 'Ganoderma lucidum', 'Fruiting body', 'Ganoderic acid B', 'Terpenoid', 'Pentacyclic triterpenoid', 'High', 'Major', 'Major triterpenoid complementing ganoderic acid A and contributing hepatoprotective activity.', NULL),
  (11, 'Reishi', 'Ganoderma lucidum', 'Fruiting body', 'β-(1→3),(1→6)-D-glucan', 'Polysaccharide', 'β-Glucan', 'High', 'Marker', 'Principal immunomodulatory polysaccharide responsible for activation of innate and adaptive immune responses.', NULL),
  (11, 'Reishi', 'Ganoderma lucidum', 'Fruiting body', 'Ganoderan A', 'Polysaccharide', 'β-Glucan', 'Moderate', 'Major', 'Characteristic β-glucan contributing immunomodulatory activity and complementing the broader polysaccharide fraction.', NULL),
  (11, 'Reishi', 'Ganoderma lucidum', 'Fruiting body', 'Ganoderic acid C2', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Present', 'Characteristic lanostane triterpenoid contributing anti-inflammatory and hepatoprotective activity while expanding the representative ganoderic acid profile.', NULL),
  (11, 'Reishi', 'Ganoderma lucidum', 'Fruiting body', 'Ganodermanontriol', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Present', 'Characteristic oxygenated triterpenoid contributing anti-inflammatory activity and complementing the ganoderic acids.', NULL),
  (16, 'Rhodiola', 'Rhodiola rosea', 'Rhizome & root', 'Rosavin', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Principal rosavin contributing adaptogenic activity and serving as the primary analytical marker for authentic Rhodiola rosea.', 'Rhodiola rosea is one of the few medicinal herbs defined by two complementary marker systems. The rosavin complex (rosavin, rosarin, and rosin) is unique to R. rosea and distinguishes it from other Rhodiola species, while salidroside contributes substantially to the herb''s pharmacological activity but is not species-specific. Representing both groups produces a phytochemical fingerprint that is both chemically distinctive and pharmacologically meaningful.'),
  (16, 'Rhodiola', 'Rhodiola rosea', 'Rhizome & root', 'Rosarin', 'Glycoside', 'Phenolic glycoside', 'High', 'Major', 'Characteristic cinnamyl alcohol glycoside complementing rosavin and contributing adaptogenic activity.', NULL),
  (16, 'Rhodiola', 'Rhodiola rosea', 'Rhizome & root', 'Rosin', 'Glycoside', 'Phenolic glycoside', 'High', 'Major', 'Completes the characteristic rosavin complex responsible for the herb''s chemotaxonomic identity.', NULL),
  (16, 'Rhodiola', 'Rhodiola rosea', 'Rhizome & root', 'Salidroside', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Principal tyrosol glycoside contributing neuroprotective, adaptogenic, and antioxidant activity.', NULL),
  (16, 'Rhodiola', 'Rhodiola rosea', 'Rhizome & root', 'Tyrosol', 'Phenylpropanoid', 'Phenolic alcohol', 'Moderate', 'Major', 'Aglycone of salidroside contributing antioxidant and neuroprotective activity while complementing the glycoside fraction.', NULL),
  (16, 'Rhodiola', 'Rhodiola rosea', 'Rhizome & root', 'p-Tyrosol', 'Phenylpropanoid', 'Phenolic alcohol', 'Low–Moderate', 'Present', 'Characteristic phenolic alcohol complementing salidroside and contributing antioxidant and neuroprotective activity.', NULL),
  (NULL, 'Rose', 'Rosa spp.', 'Petal', 'Citronellol', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene alcohol contributing the characteristic floral aroma while supporting calming, antimicrobial, and anti-inflammatory activity.', 'Rose petals are defined by the combination of a citronellol-rich volatile oil and polyphenolic antioxidants. Unlike rose hips, which are dominated by carotenoids and vitamin C, the petals derive their medicinal identity primarily from aromatic monoterpenes together with flavonoids and ellagic acid.'),
  (NULL, 'Rose', 'Rosa spp.', 'Petal', 'Geraniol', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major monoterpene alcohol contributing antimicrobial activity and the characteristic fragrance profile.', NULL),
  (NULL, 'Rose', 'Rosa spp.', 'Petal', 'Nerol', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene alcohol complementing citronellol and geraniol in the aromatic profile.', NULL),
  (NULL, 'Rose', 'Rosa spp.', 'Petal', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Contributes antioxidant activity and complements the volatile oil constituents.', NULL),
  (NULL, 'Rose', 'Rosa spp.', 'Petal', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Supports antioxidant activity and complements the flavonoid profile.', NULL),
  (NULL, 'Rose', 'Rosa spp.', 'Petal', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Major', 'Characteristic phenolic contributing antioxidant and astringent activity while complementing the aromatic constituents.', NULL),
  (154, 'Rhubarb', 'Rheum palmatum', 'Root', 'Rhein', 'Anthraquinone', 'Anthraquinone', 'High', 'Marker', 'Principal anthraquinone contributing stimulant laxative activity following bacterial metabolism in the colon.', 'Medicinal rhubarb is unusual because its pharmacology reflects two complementary constituent groups: anthraquinones, responsible for stimulant laxative effects, and phenolic glycosides such as lindleyin, which contribute astringency and anti-inflammatory activity. Representing both groups better captures the traditional use of rhubarb than an anthraquinone-only profile and provides a more distinctive phytochemical fingerprint.'),
  (154, 'Rhubarb', 'Rheum palmatum', 'Root', 'Emodin', 'Anthraquinone', 'Anthraquinone', 'High', 'Major', 'Major anthraquinone contributing laxative, antimicrobial, and anti-inflammatory activity.', NULL),
  (154, 'Rhubarb', 'Rheum palmatum', 'Root', 'Aloe-emodin', 'Anthraquinone', 'Anthraquinone', 'Moderate', 'Major', 'Characteristic anthraquinone complementing the stimulant laxative activity of the root.', NULL),
  (154, 'Rhubarb', 'Rheum palmatum', 'Root', 'Physcion', 'Anthraquinone', 'Anthraquinone', 'Moderate', 'Major', 'Characteristic anthraquinone contributing antimicrobial activity and complementing the root''s laxative anthraquinone profile.', NULL),
  (154, 'Rhubarb', 'Rheum palmatum', 'Root', 'Chrysophanol', 'Anthraquinone', 'Anthraquinone', 'Moderate', 'Present', 'Characteristic anthraquinone contributing antimicrobial and anti-inflammatory activity.', NULL),
  (154, 'Rhubarb', 'Rheum palmatum', 'Root', 'Lindleyin', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Present', 'Characteristic phenolic glycoside contributing the root''s astringent and anti-inflammatory properties, balancing its anthraquinone fraction.', NULL),
  (109, 'Rosemary', 'Rosmarinus officinalis', 'Leaf', 'Carnosic acid', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Principal diterpenoid contributing antioxidant, neuroprotective, and anti-inflammatory activity.', 'Rosemary is chemically distinguished by the combination of phenolic diterpenes (carnosic acid and carnosol), rosmarinic acid, and a cineole-rich volatile oil. Together these constituent groups account for the herb''s antioxidant, cognitive, antimicrobial, and digestive actions, while providing a phytochemical fingerprint that clearly distinguishes rosemary from other aromatic members of the mint family.'),
  (109, 'Rosemary', 'Rosmarinus officinalis', 'Leaf', 'Carnosol', 'Terpenoid', 'Diterpenoid', 'High', 'Major', 'Major diterpenoid complementing carnosic acid and contributing antioxidant activity.', NULL),
  (109, 'Rosemary', 'Rosmarinus officinalis', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'High', 'Major', 'Principal phenolic contributing antioxidant, anti-inflammatory, and antiviral activity.', NULL),
  (109, 'Rosemary', 'Rosmarinus officinalis', 'Leaf', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Major volatile constituent contributing aromatic, antimicrobial, and respiratory-supporting activity.', NULL),
  (109, 'Rosemary', 'Rosmarinus officinalis', 'Leaf', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic monoterpene contributing circulatory, aromatic, and antimicrobial activity.', NULL),
  (109, 'Rosemary', 'Rosmarinus officinalis', 'Leaf', 'Borneol', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Characteristic oxygenated monoterpene complementing the volatile oil profile with antimicrobial activity.', NULL),
  (110, 'Rue', 'Ruta graveolens', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'High', 'Marker', 'Principal flavonoid contributing capillary-protective, antioxidant, and anti-inflammatory activity.', 'Rue is chemically distinguished by the combination of quinoline alkaloids, furoquinoline alkaloids, and furanocoumarins. While rutin gave the compound its name and remains an important constituent, the alkaloids and coumarins provide the most distinctive chemotaxonomic fingerprint and account for many of the herb''s characteristic pharmacological and toxicological properties.'),
  (110, 'Rue', 'Ruta graveolens', 'Aerial parts', 'Graveolinine', 'Alkaloid', 'Quinoline alkaloid', 'High', 'Major', 'Characteristic quinoline alkaloid serving as a chemotaxonomic marker for Ruta while contributing antimicrobial activity.', NULL),
  (110, 'Rue', 'Ruta graveolens', 'Aerial parts', 'Skimmianine', 'Alkaloid', 'Furoquinoline alkaloid', 'High', 'Major', 'Characteristic furoquinoline alkaloid contributing smooth muscle and antimicrobial activity.', NULL),
  (110, 'Rue', 'Ruta graveolens', 'Aerial parts', 'Bergapten', 'Coumarin', 'Furanocoumarin', 'Moderate', 'Major', 'Principal furanocoumarin responsible for the herb''s characteristic phototoxicity and contributing antimicrobial activity.', NULL),
  (110, 'Rue', 'Ruta graveolens', 'Aerial parts', 'Xanthotoxin (Methoxsalen)', 'Coumarin', 'Furanocoumarin', 'Moderate', 'Major', 'Characteristic furanocoumarin complementing bergapten and contributing phototoxic and antimicrobial activity.', NULL),
  (110, 'Rue', 'Ruta graveolens', 'Aerial parts', 'Arborinine', 'Alkaloid', 'Quinoline alkaloid', 'Moderate', 'Present', 'Characteristic quinoline alkaloid complementing the distinctive alkaloid profile of Ruta graveolens.', NULL),
  (56, 'Sage', 'Salvia officinalis', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'High', 'Marker', 'Principal phenolic contributing antioxidant, anti-inflammatory, antiviral, and cognitive-support activity.', 'Sage shares much of its chemistry with rosemary through its phenolic diterpenes and rosmarinic acid, but is distinguished by a thujone-rich volatile oil and a higher abundance of ursane triterpenoids. This profile captures the major constituent groups responsible for its antimicrobial, cognitive, antioxidant, and traditional digestive actions while providing a phytochemical fingerprint that clearly separates it from other members of the Lamiaceae.'),
  (56, 'Sage', 'Salvia officinalis', 'Leaf', 'Carnosic acid', 'Terpenoid', 'Diterpenoid', 'High', 'Major', 'Major phenolic diterpenoid contributing antioxidant and neuroprotective activity.', NULL),
  (56, 'Sage', 'Salvia officinalis', 'Leaf', 'Carnosol', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic diterpenoid complementing carnosic acid with antioxidant and anti-inflammatory activity.', NULL),
  (56, 'Sage', 'Salvia officinalis', 'Leaf', 'α-Thujone', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Principal ketonic monoterpene contributing antimicrobial activity and accounting for the herb''s characteristic neurotoxicity at high doses.', NULL),
  (56, 'Sage', 'Salvia officinalis', 'Leaf', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Major volatile constituent contributing aromatic, antimicrobial, and respiratory-supporting activity.', NULL),
  (56, 'Sage', 'Salvia officinalis', 'Leaf', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Moderate', 'Present', 'Characteristic triterpenoid contributing anti-inflammatory activity and complementing the phenolic diterpenes.', NULL),
  (5, 'Sakhalin Spikenard', 'Aralia schmidtii', 'Root', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Marker', 'Principal triterpenoid contributing adaptogenic, anti-inflammatory, and hepatoprotective activity.', 'Like other medicinal Aralia species, Sakhalin spikenard is defined primarily by its oleanane triterpenoid saponins. The aralosides constitute the characteristic phytochemical fingerprint of the root, while oleanolic acid and hederagenin represent the core aglycone chemistry underlying these glycosides. The inclusion of chlorogenic acid provides a representative non-saponin constituent without diluting the herb''s defining chemistry.'),
  (5, 'Sakhalin Spikenard', 'Aralia schmidtii', 'Root', 'Hederagenin', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal sapogenin serving as the aglycone of the characteristic aralosides and contributing anti-inflammatory activity.', NULL),
  (5, 'Sakhalin Spikenard', 'Aralia schmidtii', 'Root', 'Araloside A', 'Glycoside', 'Triterpenoid saponin', 'High', 'Major', 'Characteristic triterpenoid saponin contributing adaptogenic and immunomodulatory activity.', NULL),
  (5, 'Sakhalin Spikenard', 'Aralia schmidtii', 'Root', 'Araloside B', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Major companion saponin complementing araloside A and contributing adaptogenic activity.', NULL),
  (5, 'Sakhalin Spikenard', 'Aralia schmidtii', 'Root', 'Araloside C', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Present', 'Characteristic triterpenoid saponin expanding the representative araloside profile.', NULL),
  (5, 'Sakhalin Spikenard', 'Aralia schmidtii', 'Root', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Characteristic phenolic contributing antioxidant activity and complementing the saponin-rich chemistry.', NULL),
  (40, 'Sarsaparilla', 'Smilax spp.', 'Root', 'Sarsasaponin', 'Glycoside', 'Steroidal glycoside', 'High', 'Marker', 'Principal steroidal saponin contributing the herb''s traditional alterative, anti-inflammatory, and immunomodulatory activity.', 'Although sarsaparilla is best known for its steroidal saponins, modern phytochemical work has shown that phenylpropanoid esters such as smilaside A are also characteristic constituents of Smilax. Including one representative of this family produces a more distinctive phytochemical fingerprint while preserving the dominant steroidal chemistry that defines the herb.'),
  (40, 'Sarsaparilla', 'Smilax spp.', 'Root', 'Smilagenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Major', 'Major sapogenin serving as the aglycone of characteristic steroidal saponins.', NULL),
  (40, 'Sarsaparilla', 'Smilax spp.', 'Root', 'Sarsasapogenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Major', 'Characteristic steroidal sapogenin contributing anti-inflammatory activity and serving as a precursor to steroidal glycosides.', NULL),
  (40, 'Sarsaparilla', 'Smilax spp.', 'Root', 'Diosgenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Major', 'Characteristic sapogenin contributing anti-inflammatory activity and chemotaxonomic significance.', NULL),
  (40, 'Sarsaparilla', 'Smilax spp.', 'Root', 'Sitosterol', 'Sterol', 'Phytosterol', 'Low–Moderate', 'Present', 'Contributes anti-inflammatory activity and complements the steroidal constituents.', NULL),
  (40, 'Sarsaparilla', 'Smilax spp.', 'Root', 'Smilaside A', 'Phenylpropanoid', 'Phenylpropanoid ester', 'Moderate', 'Present', 'Characteristic phenylpropanoid ester contributing antioxidant and anti-inflammatory activity while distinguishing Smilax chemistry beyond its steroidal saponins.', NULL),
  (186, 'Saw Palmetto', 'Serenoa repens', 'Fruit', 'β-Sitosterol', 'Sterol', 'Phytosterol', 'High', 'Marker', 'Principal phytosterol contributing support for healthy prostate function and anti-inflammatory activity.', 'Saw palmetto is unusual among medicinal herbs because its activity is dominated by a lipid fraction rather than polyphenols or alkaloids. The combination of free fatty acids and phytosterols defines both its pharmacology and the standardized extracts used clinically. Representing both groups provides a phytochemical fingerprint that is faithful to the herb''s medicinal identity.'),
  (186, 'Saw Palmetto', 'Serenoa repens', 'Fruit', 'Lauric acid', 'Lipid', 'Saturated fatty acid', 'High', 'Major', 'Major medium-chain fatty acid contributing inhibition of 5α-reductase and supporting prostate health.', NULL),
  (186, 'Saw Palmetto', 'Serenoa repens', 'Fruit', 'Oleic acid', 'Lipid', 'Monounsaturated fatty acid', 'High', 'Major', 'Major fatty acid contributing anti-inflammatory activity and forming part of the characteristic lipid fraction.', NULL),
  (186, 'Saw Palmetto', 'Serenoa repens', 'Fruit', 'Myristic acid', 'Lipid', 'Saturated fatty acid', 'Moderate', 'Major', 'Characteristic fatty acid contributing to the biologically active lipid extract.', NULL),
  (186, 'Saw Palmetto', 'Serenoa repens', 'Fruit', 'Campesterol', 'Sterol', 'Phytosterol', 'Moderate', 'Present', 'Characteristic phytosterol complementing β-sitosterol in the sterol fraction.', NULL),
  (186, 'Saw Palmetto', 'Serenoa repens', 'Fruit', 'Linoleic acid', 'Lipid', 'Polyunsaturated fatty acid', 'Moderate', 'Major', 'Major unsaturated fatty acid contributing to inhibition of 5α-reductase and complementing the fruit''s characteristic lipid fraction.', NULL),
  (17, 'Schisandra', 'Schisandra chinensis', 'Fruit', 'Schisandrin', 'Lignan', 'Dibenzocyclooctadiene lignan', 'High', 'Marker', 'Principal lignan contributing hepatoprotective, adaptogenic, and antioxidant activity.', 'Schisandra chinensis is one of the clearest examples of a medicinal plant defined almost entirely by a single family of specialized metabolites. The dibenzocyclooctadiene lignans are both chemotaxonomically unique and pharmacologically dominant, making them a more representative fingerprint than the fruit''s common organic acids, sugars, or volatile constituents. This approach is analogous to profiling Milk Thistle by its flavonolignans rather than its ubiquitous phenolics.'),
  (17, 'Schisandra', 'Schisandra chinensis', 'Fruit', 'Schisandrin B', 'Lignan', 'Dibenzocyclooctadiene lignan', 'High', 'Major', 'Major lignan complementing schisandrin and contributing hepatoprotective activity.', NULL),
  (17, 'Schisandra', 'Schisandra chinensis', 'Fruit', 'Schisantherin A', 'Lignan', 'Dibenzocyclooctadiene lignan', 'Moderate', 'Major', 'Characteristic lignan contributing antioxidant and adaptogenic activity.', NULL),
  (17, 'Schisandra', 'Schisandra chinensis', 'Fruit', 'Gomisin A', 'Lignan', 'Dibenzocyclooctadiene lignan', 'Moderate', 'Major', 'Characteristic lignan supporting hepatoprotective and antioxidant activity.', NULL),
  (17, 'Schisandra', 'Schisandra chinensis', 'Fruit', 'Gomisin N', 'Lignan', 'Dibenzocyclooctadiene lignan', 'Moderate', 'Present', 'Characteristic lignan complementing the representative schizandra lignan profile.', NULL),
  (17, 'Schisandra', 'Schisandra chinensis', 'Fruit', 'Schisandrin C', 'Lignan', 'Dibenzocyclooctadiene lignan', 'Moderate', 'Present', 'Characteristic lignan contributing hepatoprotective and antioxidant activity while completing the representative schisandrin series.', NULL),
  (164, 'Scotch Broom', 'Cytisus scoparius', 'Aerial parts', 'Sparteine', 'Alkaloid', 'Quinolizidine alkaloid', 'High', 'Marker', 'Principal quinolizidine alkaloid contributing antiarrhythmic activity and serving as the defining chemotaxonomic marker of the herb.', 'Cytisus scoparius is chemically defined by its quinolizidine alkaloids, particularly sparteine, which historically accounted for many of its medicinal uses. The accompanying flavonoids, especially scoparin, provide a complementary phytochemical signature and distinguish Scotch broom from other quinolizidine-containing members of the Fabaceae.'),
  (164, 'Scotch Broom', 'Cytisus scoparius', 'Aerial parts', 'Isosparteine', 'Alkaloid', 'Quinolizidine alkaloid', 'High', 'Major', 'Major companion alkaloid complementing sparteine and contributing to the characteristic alkaloid profile.', NULL),
  (164, 'Scotch Broom', 'Cytisus scoparius', 'Aerial parts', 'Lupanine', 'Alkaloid', 'Quinolizidine alkaloid', 'Moderate', 'Major', 'Characteristic quinolizidine alkaloid contributing to the herb''s cardiovascular and chemotaxonomic profile.', NULL),
  (164, 'Scotch Broom', 'Cytisus scoparius', 'Aerial parts', 'Genistein', 'Flavonoid', 'Isoflavone', 'Moderate', 'Present', 'Characteristic isoflavone contributing antioxidant activity and complementing the alkaloid-rich chemistry.', NULL),
  (164, 'Scotch Broom', 'Cytisus scoparius', 'Aerial parts', 'Scoparin', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside contributing diuretic and vascular-supporting activity.', NULL),
  (164, 'Scotch Broom', 'Cytisus scoparius', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol contributing antioxidant activity and complementing the alkaloid and flavonoid profile.', NULL),
  (184, 'Sea Holly', 'Eryngium maritimum', 'Root', 'Eryngioside A', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal triterpenoid saponin contributing expectorant, diuretic, and anti-inflammatory activity.', 'Sea Holly is chemically characterized by oleanane triterpenoid saponins together with polyacetylenes, a phytochemical combination typical of medicinal members of the Apiaceae. The eryngiosides define the herb''s distinctive chemistry, while falcarinol and the caffeoylquinic acids provide complementary constituents that distinguish Eryngium from other saponin-rich medicinal roots.'),
  (184, 'Sea Holly', 'Eryngium maritimum', 'Root', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal triterpenoid sapogenin serving as the aglycone of characteristic saponins.', NULL),
  (184, 'Sea Holly', 'Eryngium maritimum', 'Root', 'R-Falcarinol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Characteristic polyacetylene contributing antimicrobial and anti-inflammatory activity typical of Apiaceae.', NULL),
  (184, 'Sea Holly', 'Eryngium maritimum', 'Root', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Characteristic phenolic contributing antioxidant activity and complementing the triterpenoid chemistry.', NULL),
  (184, 'Sea Holly', 'Eryngium maritimum', 'Root', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Low–Moderate', 'Present', 'Characteristic phenolic ester contributing antioxidant and anti-inflammatory activity while complementing the triterpenoid saponins.', NULL),
  (184, 'Sea Holly', 'Eryngium maritimum', 'Root', 'Eryngioside B', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Present', 'Characteristic companion saponin expanding the representative eryngioside profile.', NULL),
  (195, 'Seneca Snakeroot', 'Polygala senega', 'Root', 'Senegin II', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal triterpenoid saponin contributing the herb''s characteristic expectorant and secretolytic activity.', 'Polygala senega is defined overwhelmingly by its oleanane triterpenoid saponins, particularly the senegins, which account for its traditional expectorant activity. Including methyl salicylate (present here as salicylic acid methyl ester) captures the root''s distinctive aromatic chemistry without distracting from the dominant saponin profile.'),
  (195, 'Seneca Snakeroot', 'Polygala senega', 'Root', 'Senegin III', 'Glycoside', 'Triterpenoid saponin', 'High', 'Major', 'Major companion saponin complementing senegin II and contributing expectorant activity.', NULL),
  (195, 'Seneca Snakeroot', 'Polygala senega', 'Root', 'Presenegenin', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal sapogenin serving as the aglycone of the senegin saponins.', NULL),
  (195, 'Seneca Snakeroot', 'Polygala senega', 'Root', 'Polygalacic acid', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Major', 'Characteristic triterpenoid contributing to the distinctive saponin chemistry of the root.', NULL),
  (195, 'Seneca Snakeroot', 'Polygala senega', 'Root', 'Methyl salicylate', 'Phenylpropanoid', 'Benzoate ester', 'Low–Moderate', 'Present', 'Characteristic aromatic ester responsible for the root''s distinctive wintergreen-like aroma and complementing the dominant triterpenoid saponins.', NULL),
  (195, 'Seneca Snakeroot', 'Polygala senega', 'Root', 'Senegin IV', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Present', 'Characteristic triterpenoid saponin completing the representative senegin profile.', NULL),
  (216, 'Senna', 'Senna alexandrina', 'Leaf', 'Sennoside A', 'Anthraquinone', 'Anthraquinone glycoside', 'High', 'Marker', 'Principal dianthrone glycoside responsible for the stimulant laxative activity of senna leaves.', 'Senna is one of the clearest examples of a medicinal herb defined by a small group of anthraquinone glycosides. The sennosides account for nearly all of the herb''s medicinal activity, while the accompanying anthraquinones and flavonols provide a representative phytochemical fingerprint without distracting from the dominant laxative constituents.'),
  (216, 'Senna', 'Senna alexandrina', 'Leaf', 'Sennoside B', 'Anthraquinone', 'Anthraquinone glycoside', 'High', 'Major', 'Major companion glycoside complementing sennoside A in stimulant laxative activity.', NULL),
  (216, 'Senna', 'Senna alexandrina', 'Leaf', 'Rhein-8-O-glucoside', 'Anthraquinone', 'Anthraquinone glycoside', 'Moderate', 'Major', 'Characteristic anthraquinone glycoside complementing the sennosides and contributing to the leaf''s stimulant laxative activity.', NULL),
  (216, 'Senna', 'Senna alexandrina', 'Leaf', 'Aloe-emodin', 'Anthraquinone', 'Anthraquinone', 'Moderate', 'Present', 'Characteristic anthraquinone complementing the dianthrone glycosides.', NULL),
  (216, 'Senna', 'Senna alexandrina', 'Leaf', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol contributing antioxidant activity and complementing the anthraquinone chemistry.', NULL),
  (216, 'Senna', 'Senna alexandrina', 'Leaf', 'Isorhamnetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol contributing antioxidant activity and expanding the representative flavonoid profile.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Sinigrin', 'Glycoside', 'Glucosinolate', 'High', 'Marker', 'Principal glucosinolate contributing the herb''s characteristic pungency and supporting antimicrobial activity following enzymatic hydrolysis.', 'Shepherd''s Purse is chemically unusual because it combines glucosinolates, biogenic amines, and vascular flavonoids. This combination distinguishes it from most hemostatic herbs and reflects both its Brassicaceae ancestry and its traditional use as a uterine and vascular remedy.'),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Choline', 'Nitrogenous compound', 'Quaternary ammonium compound', 'Moderate', 'Major', 'Characteristic nitrogenous constituent traditionally associated with the herb''s vascular and uterine effects.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside contributing capillary-supporting, antioxidant, and vascular-protective activity.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Characteristic flavonol contributing antioxidant and anti-inflammatory activity.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Characteristic flavonol complementing the flavonoid profile and supporting vascular health.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Tyramine', 'Nitrogenous compound', 'Phenethylamine', 'Low–Moderate', 'Present', 'Characteristic biogenic amine contributing vasoactive properties traditionally associated with the herb.', NULL),
  (9, 'Siberian Ginseng', 'Eleutherococcus senticosus', 'Root', 'Eleutheroside B (Syringin)', 'Glycoside', 'Phenylpropanoid glycoside', 'High', 'Marker', 'Principal phenylpropanoid glycoside contributing adaptogenic activity and serving as an analytical marker of the root.', 'Unlike Panax species, Siberian Ginseng is not defined by ginsenosides. Instead, its chemistry is characterized by a combination of eleutherosides, lignans, and phenylpropanoid glycosides, which provide a distinctive chemotaxonomic fingerprint while accounting for many of the herb''s adaptogenic properties.'),
  (9, 'Siberian Ginseng', 'Eleutherococcus senticosus', 'Root', 'Eleutheroside E', 'Lignan', 'Lignan glycoside', 'High', 'Marker', 'Principal lignan glycoside contributing adaptogenic, immunomodulatory, and antioxidant activity.', NULL),
  (9, 'Siberian Ginseng', 'Eleutherococcus senticosus', 'Root', 'Syringaresinol', 'Lignan', 'Lignan', 'Moderate', 'Major', 'Characteristic lignan serving as the aglycone of eleutheroside E and contributing antioxidant activity.', NULL),
  (9, 'Siberian Ginseng', 'Eleutherococcus senticosus', 'Root', 'Eleutheroside D', 'Lignan', 'Lignan glycoside', 'Moderate', 'Present', 'Characteristic lignan glycoside complementing eleutheroside E and contributing adaptogenic and antioxidant activity.', NULL),
  (9, 'Siberian Ginseng', 'Eleutherococcus senticosus', 'Root', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Characteristic phenolic contributing antioxidant activity and complementing the glycoside-rich chemistry.', NULL),
  (9, 'Siberian Ginseng', 'Eleutherococcus senticosus', 'Root', 'Isofraxidin', 'Coumarin', 'Simple coumarin', 'Moderate', 'Present', 'Characteristic coumarin contributing antioxidant and anti-inflammatory activity while expanding the phytochemical fingerprint.', NULL),
  (2, 'Silk Tree', 'Albizia julibrissin', 'Stem bark', 'Julibroside C1', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal triterpenoid saponin contributing anxiolytic, neuroprotective, and anti-inflammatory activity.', 'The medicinal bark of Albizia julibrissin is defined primarily by its julibroside triterpenoid saponins, which account for much of its traditional calming and neuroprotective activity. The accompanying flavonoids provide a representative secondary phytochemical profile while preserving the dominant saponin chemistry that distinguishes the herb.'),
  (2, 'Silk Tree', 'Albizia julibrissin', 'Stem bark', 'Julibroside J8', 'Glycoside', 'Triterpenoid saponin', 'High', 'Major', 'Major companion saponin complementing julibroside C1 and contributing neuroprotective activity.', NULL),
  (2, 'Silk Tree', 'Albizia julibrissin', 'Stem bark', 'Acacic acid lactone', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal sapogenin serving as the aglycone of the characteristic julibrosides.', NULL),
  (2, 'Silk Tree', 'Albizia julibrissin', 'Stem bark', 'Quercitrin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Characteristic flavonoid glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (2, 'Silk Tree', 'Albizia julibrissin', 'Stem bark', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol complementing the bark''s antioxidant profile.', NULL),
  (2, 'Silk Tree', 'Albizia julibrissin', 'Stem bark', 'Julibroside J30', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Present', 'Characteristic triterpenoid saponin expanding the representative julibroside profile while complementing the bark''s anxiolytic and neuroprotective chemistry.', NULL),
  (142, 'Skullcap', 'Scutellaria lateriflora', 'Aerial parts', 'Scutellarin', 'Flavonoid', 'Flavone glycoside', 'High', 'Marker', 'Principal flavone glycoside contributing antioxidant, neuroprotective, and anxiolytic activity.', 'Unlike Chinese skullcap (Scutellaria baicalensis), whose chemistry is dominated by baicalin, baicalein, wogonin, and oroxylin A, American skullcap (S. lateriflora) is characterized primarily by scutellarin, scutellarein, and related flavones, together with smaller amounts of other flavonoids and phenylethanoid glycosides. Keeping these species separate follows the database''s editorial rule against inferring constituents from related species and produces a phytochemical fingerprint that more accurately reflects the medicinal chemistry of the North American herb.'),
  (142, 'Skullcap', 'Scutellaria lateriflora', 'Aerial parts', 'Scutellarein', 'Flavonoid', 'Flavone', 'High', 'Major', 'Major flavone aglycone complementing scutellarin and contributing anti-inflammatory and neuroprotective activity.', NULL),
  (142, 'Skullcap', 'Scutellaria lateriflora', 'Aerial parts', 'Lateriflorin', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavonoid serving as a chemotaxonomic marker for S. lateriflora and contributing to the herb''s calming profile.', NULL),
  (142, 'Skullcap', 'Scutellaria lateriflora', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Characteristic flavone contributing antioxidant and anti-inflammatory activity.', NULL),
  (142, 'Skullcap', 'Scutellaria lateriflora', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Characteristic flavone contributing mild anxiolytic and anti-inflammatory activity.', NULL),
  (142, 'Skullcap', 'Scutellaria lateriflora', 'Aerial parts', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'Low–Moderate', 'Present', 'Characteristic phenylethanoid glycoside contributing antioxidant and neuroprotective activity while complementing the flavonoid profile.', NULL),
  (143, 'Skunk Cabbage', 'Symplocarpus foetidus', 'Rhizome', 'Coniine', 'Alkaloid', 'Piperidine alkaloid', 'High', 'Marker', 'Characteristic piperidine alkaloid contributing antispasmodic and neuroactive activity.', 'The phytochemistry of Symplocarpus foetidus is considerably less well characterized than that of many herbs in your database. Following your conservative editorial rules, this profile emphasizes the well-documented piperidine alkaloids that distinguish the species while limiting the remaining constituents to those consistently reported across multiple references. This is an example where "less is better" is particularly appropriate.'),
  (143, 'Skunk Cabbage', 'Symplocarpus foetidus', 'Rhizome', 'γ-Coniceine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Major', 'Companion piperidine alkaloid contributing to the herb’s distinctive alkaloid profile.', NULL),
  (143, 'Skunk Cabbage', 'Symplocarpus foetidus', 'Rhizome', 'Ferulic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Low–Moderate', 'Present', 'Contributes antioxidant activity while complementing the alkaloid profile.', NULL),
  (143, 'Skunk Cabbage', 'Symplocarpus foetidus', 'Rhizome', 'β-Sitosterol', 'Sterol', 'Phytosterol', 'Low–Moderate', 'Present', 'Supports anti-inflammatory activity and complements the rhizome chemistry.', NULL),
  (143, 'Skunk Cabbage', 'Symplocarpus foetidus', 'Rhizome', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol complementing the antioxidant profile.', NULL),
  (92, 'Slippery Elm', 'Ulmus rubra', 'Inner bark', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'High', 'Marker', 'Principal mucilage polysaccharide responsible for the herb''s demulcent and mucosal-protective activity.', 'The medicinal activity of slippery elm is dominated by its mucilage polysaccharides, particularly arabinogalactans and pectic polysaccharides, which account for its classic demulcent action. The remaining constituents provide a representative fingerprint of the inner bark without detracting from the herb''s defining polysaccharide chemistry.'),
  (92, 'Slippery Elm', 'Ulmus rubra', 'Inner bark', 'Rhamnogalacturonan', 'Polysaccharide', 'Pectin', 'High', 'Major', 'Major pectic polysaccharide contributing hydration, viscosity, and soothing effects on irritated mucosa.', NULL),
  (92, 'Slippery Elm', 'Ulmus rubra', 'Inner bark', 'Oligomeric procyanidins', 'Tannin', 'Condensed tannin', 'Moderate', 'Major', 'Characteristic condensed tannins contributing mild astringency and antioxidant activity while complementing the demulcent polysaccharides.', NULL),
  (92, 'Slippery Elm', 'Ulmus rubra', 'Inner bark', '(+)-Catechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Characteristic flavan-3-ol contributing antioxidant activity and serving as a precursor to condensed tannins.', NULL),
  (92, 'Slippery Elm', 'Ulmus rubra', 'Inner bark', 'β-Sitosterol', 'Sterol', 'Phytosterol', 'Low–Moderate', 'Present', 'Characteristic phytosterol contributing anti-inflammatory activity while complementing the mucilage-rich chemistry.', NULL),
  (92, 'Slippery Elm', 'Ulmus rubra', 'Inner bark', 'Gallic acid', 'Polyphenol', 'Phenolic acid', 'Low–Moderate', 'Present', 'Characteristic phenolic contributing antioxidant activity and complementing the bark''s tannin fraction.', NULL),
  (96, 'Southernwood', 'Artemisia abrotanum', 'Aerial parts', 'Scopoletin', 'Coumarin', 'Simple coumarin', 'High', 'Marker', 'Characteristic coumarin contributing antioxidant and anti-inflammatory activity while serving as a chemotaxonomic marker for the aerial parts.', 'Unlike many other Artemisia species, Southernwood is not characterized by sesquiterpene lactones. Instead, its chemistry is dominated by a cineole/camphor-rich volatile oil together with characteristic coumarins, providing a phytochemical fingerprint that distinguishes it from wormwood and mugwort.'),
  (96, 'Southernwood', 'Artemisia abrotanum', 'Aerial parts', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Principal volatile constituent contributing aromatic, antimicrobial, and expectorant activity.', NULL),
  (96, 'Southernwood', 'Artemisia abrotanum', 'Aerial parts', 'Camphor', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic ketonic monoterpene contributing aromatic and antimicrobial activity.', NULL),
  (96, 'Southernwood', 'Artemisia abrotanum', 'Aerial parts', 'Borneol', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic oxygenated monoterpene complementing the volatile oil profile.', NULL),
  (96, 'Southernwood', 'Artemisia abrotanum', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Characteristic phenolic contributing antioxidant activity.', NULL),
  (96, 'Southernwood', 'Artemisia abrotanum', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Characteristic flavonoid contributing antioxidant activity and complementing the aromatic constituents.', NULL),
  (166, 'Squill', 'Urginea maritima', 'Bulb', 'Proscillaridin A', 'Steroid', 'Cardiac glycoside', 'High', 'Marker', 'Principal cardiac glycoside responsible for the bulb''s cardiotonic and expectorant activity.', 'The medicinal bulb of Urginea maritima is defined almost entirely by its bufadienolide cardiac glycosides. Unlike foxglove, whose glycosides are cardenolides, squill is characterized by bufadienolides, giving it a distinctive chemotaxonomic and pharmacological profile. Representing several members of this family best captures the herb''s defining chemistry.'),
  (166, 'Squill', 'Urginea maritima', 'Bulb', 'Scillaren A', 'Steroid', 'Cardiac glycoside', 'High', 'Major', 'Major bufadienolide cardiac glycoside complementing proscillaridin A.', NULL),
  (166, 'Squill', 'Urginea maritima', 'Bulb', 'Scilliroside', 'Steroid', 'Cardiac glycoside', 'Moderate', 'Major', 'Characteristic bufadienolide contributing cardiotonic activity and the bulb''s toxicity.', NULL),
  (166, 'Squill', 'Urginea maritima', 'Bulb', 'Scilliglaucoside', 'Steroid', 'Cardiac glycoside', 'Moderate', 'Present', 'Characteristic bufadienolide glycoside expanding the representative cardiac glycoside profile.', NULL),
  (166, 'Squill', 'Urginea maritima', 'Bulb', 'Scilliphaeoside', 'Steroid', 'Cardiac glycoside', 'Low–Moderate', 'Present', 'Characteristic bufadienolide glycoside complementing the bulb''s steroidal profile.', NULL),
  (166, 'Squill', 'Urginea maritima', 'Bulb', 'Scillarenin', 'Steroid', 'Bufadienolide', 'Moderate', 'Present', 'Characteristic bufadienolide aglycone serving as the steroid nucleus of several squill cardiac glycosides and contributing to the bulb''s distinctive chemistry.', NULL),
  (81, 'St. John''s Wort', 'Hypericum perforatum', 'Flowering tops', 'Hypericin', 'Polyphenol', 'Naphthodianthrone', 'High', 'Marker', 'Principal naphthodianthrone serving as an analytical marker and contributing photodynamic activity.', 'Hypericum perforatum is chemically defined by two highly distinctive constituent families: the hypericins (naphthodianthrones) and the hyperforins (prenylated phloroglucinols). Together they form one of the most recognizable phytochemical fingerprints in herbal medicine, while the flavonol glycosides provide complementary antioxidant activity without overshadowing the herb''s defining chemistry.'),
  (81, 'St. John''s Wort', 'Hypericum perforatum', 'Flowering tops', 'Pseudohypericin', 'Polyphenol', 'Naphthodianthrone', 'High', 'Major', 'Major companion naphthodianthrone complementing hypericin in the characteristic pigment profile.', NULL),
  (81, 'St. John''s Wort', 'Hypericum perforatum', 'Flowering tops', 'Hyperforin', 'Phloroglucinol', 'Prenylated phloroglucinol', 'High', 'Marker', 'Principal prenylated phloroglucinol contributing antidepressant, anxiolytic, and antimicrobial activity.', NULL),
  (81, 'St. John''s Wort', 'Hypericum perforatum', 'Flowering tops', 'Adhyperforin', 'Phloroglucinol', 'Prenylated phloroglucinol', 'Moderate', 'Major', 'Characteristic companion phloroglucinol complementing hyperforin in the lipophilic fraction.', NULL),
  (81, 'St. John''s Wort', 'Hypericum perforatum', 'Flowering tops', 'Quercitrin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Characteristic flavonol glycoside contributing antioxidant and anti-inflammatory activity while complementing the hypericins and hyperforins.', NULL),
  (81, 'St. John''s Wort', 'Hypericum perforatum', 'Flowering tops', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside contributing antioxidant activity while complementing the hypericins and hyperforins.', NULL),
  (182, 'Stoneroot', 'Collinsonia canadensis', 'Root', 'Stachydrine', 'Nitrogenous compound', 'Amino acid derivative', 'High', 'Marker', 'Characteristic betaine alkaloid associated with the herb''s traditional venotonic activity and serving as one of its best-documented characteristic constituents.', 'The phytochemistry of Collinsonia canadensis is relatively under-characterized compared with many medicinal herbs. Following your style guide, this profile emphasizes the well-established terpenoid fraction while limiting additional constituents to those consistently documented for the species. This conservative approach preserves the herb''s chemotaxonomic identity without over-interpreting sparse phytochemical data.'),
  (182, 'Stoneroot', 'Collinsonia canadensis', 'Root', 'β-Caryophyllene', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Major sesquiterpene contributing anti-inflammatory activity and forming part of the volatile oil fraction.', NULL),
  (182, 'Stoneroot', 'Collinsonia canadensis', 'Root', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic monoterpene contributing aromatic and antimicrobial activity.', NULL),
  (182, 'Stoneroot', 'Collinsonia canadensis', 'Root', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Moderate', 'Present', 'Characteristic phenolic contributing antioxidant and anti-inflammatory activity.', NULL),
  (182, 'Stoneroot', 'Collinsonia canadensis', 'Root', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'Low–Moderate', 'Present', 'Characteristic phenylethanoid glycoside contributing antioxidant activity and complementing the terpene chemistry.', NULL),
  (182, 'Stoneroot', 'Collinsonia canadensis', 'Root', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Low–Moderate', 'Present', 'Characteristic triterpenoid contributing anti-inflammatory activity and complementing the volatile constituents.', NULL),
  (126, 'Sundew', 'Drosera rotundifolia', 'Aerial parts', 'Plumbagin', 'Polyphenol', 'Naphthoquinone', 'High', 'Marker', 'Principal naphthoquinone contributing antimicrobial, antispasmodic, and expectorant activity.', 'Sundew is chemically defined by its naphthoquinones, particularly plumbagin and 7-methyljuglone, which account for much of its antimicrobial and traditional respiratory activity. The accompanying flavonoids and phenolic acids provide a representative secondary phytochemical profile while preserving the herb''s distinctive naphthoquinone fingerprint.'),
  (126, 'Sundew', 'Drosera rotundifolia', 'Aerial parts', '7-Methyljuglone', 'Polyphenol', 'Naphthoquinone', 'High', 'Major', 'Characteristic naphthoquinone complementing plumbagin and serving as a chemotaxonomic marker for the genus.', NULL),
  (126, 'Sundew', 'Drosera rotundifolia', 'Aerial parts', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (126, 'Sundew', 'Drosera rotundifolia', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Characteristic flavonol complementing the herb''s flavonoid profile.', NULL),
  (126, 'Sundew', 'Drosera rotundifolia', 'Aerial parts', 'Isoquercitrin', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Characteristic flavonol glycoside complementing hyperoside and contributing antioxidant and anti-inflammatory activity.', NULL),
  (126, 'Sundew', 'Drosera rotundifolia', 'Aerial parts', 'Gallic acid', 'Polyphenol', 'Phenolic acid', 'Low–Moderate', 'Present', 'Characteristic phenolic complementing the polyphenol profile and supporting antioxidant activity.', NULL),
  (198, 'Sweet Violet', 'Viola odorata', 'Aerial parts', 'Violanin', 'Flavonoid', 'Anthocyanin', 'High', 'Marker', 'Principal anthocyanin contributing the characteristic violet pigmentation and serving as a chemotaxonomic marker of Viola odorata.', 'Viola odorata is characterized by a combination of flavonoids, cyclotides, and volatile aromatic esters. The inclusion of cycloviolacin O2 distinguishes Sweet Violet from many other flavonoid-rich herbs by representing the unusually important cyclic peptides that have become a defining chemotaxonomic feature of the genus Viola.'),
  (198, 'Sweet Violet', 'Viola odorata', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Major flavonoid glycoside contributing vascular-supporting and antioxidant activity.', NULL)
INSERT INTO herbal.constituent_profiles
  (herb_id, common_name, latin_name, plant_part, constituent, class, subclass, importance, status, notes, editorial_note)
VALUES
  (198, 'Sweet Violet', 'Viola odorata', 'Aerial parts', 'Methyl salicylate', 'Phenylpropanoid', 'Benzoate ester', 'Moderate', 'Major', 'Characteristic aromatic ester contributing the herb''s fragrance and mild anti-inflammatory activity.', NULL),
  (198, 'Sweet Violet', 'Viola odorata', 'Aerial parts', 'Cycloviolacin O2', 'Protein', 'Peptide', 'Moderate', 'Major', 'Representative cyclotide contributing antimicrobial and cytoprotective activity while serving as a defining constituent of the genus.', NULL),
  (198, 'Sweet Violet', 'Viola odorata', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol contributing antioxidant activity.', NULL),
  (198, 'Sweet Violet', 'Viola odorata', 'Aerial parts', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol complementing the flavonoid profile.', NULL),
  (161, 'Tansy', 'Tanacetum vulgare', 'Aerial parts', 'β-Thujone', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene ketone contributing the herb''s characteristic aroma and neurotoxic activity at high doses.', 'Tansy is defined primarily by its thujone-rich volatile oil, supported by sesquiterpene lactones and flavonoids. While chemotypes vary considerably in essential oil composition, β-thujone remains the constituent most closely associated with the traditional medicinal and toxicological profile of the species.'),
  (161, 'Tansy', 'Tanacetum vulgare', 'Aerial parts', 'Camphor', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major volatile constituent contributing aromatic and antimicrobial activity.', NULL),
  (161, 'Tansy', 'Tanacetum vulgare', 'Aerial parts', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene contributing aromatic, antimicrobial, and expectorant activity.', NULL),
  (161, 'Tansy', 'Tanacetum vulgare', 'Aerial parts', 'Tanacetin', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Present', 'Characteristic sesquiterpene lactone contributing to the herb''s bitter and anti-inflammatory properties while representing the lactone fraction of Tanacetum vulgare.', NULL),
  (161, 'Tansy', 'Tanacetum vulgare', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Characteristic flavone contributing antioxidant and anti-inflammatory activity.', NULL),
  (161, 'Tansy', 'Tanacetum vulgare', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Characteristic phenolic contributing antioxidant activity and complementing the volatile oil profile.', NULL),
  (149, 'Tea', 'Camellia sinensis', 'Leaf', 'Epigallocatechin gallate (EGCG)', 'Flavonoid', 'Flavan-3-ol', 'High', 'Marker', 'Principal catechin contributing antioxidant activity and many of tea''s cardiometabolic effects.', 'Camellia sinensis is chemically distinguished by the combination of catechins, caffeine, and L-theanine. Because your database represents the species rather than a specific preparation (green, oolong, or black tea), including theaflavin captures the characteristic oxidation products found in fermented teas while retaining the defining catechin chemistry shared across the species.'),
  (149, 'Tea', 'Camellia sinensis', 'Leaf', 'Epicatechin gallate (ECG)', 'Flavonoid', 'Flavan-3-ol', 'High', 'Major', 'Major catechin complementing EGCG and contributing antioxidant activity.', NULL),
  (149, 'Tea', 'Camellia sinensis', 'Leaf', 'Epigallocatechin (EGC)', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Characteristic catechin contributing antioxidant activity and complementing the gallated catechins.', NULL),
  (149, 'Tea', 'Camellia sinensis', 'Leaf', 'Caffeine', 'Alkaloid', 'Purine alkaloid', 'High', 'Marker', 'Principal methylxanthine responsible for the stimulant effects of tea.', NULL),
  (149, 'Tea', 'Camellia sinensis', 'Leaf', 'L-Theanine', 'Nitrogenous compound', 'Amino acid derivative', 'High', 'Major', 'Characteristic amino acid derivative contributing relaxation and modulation of caffeine''s stimulant effects.', NULL),
  (149, 'Tea', 'Camellia sinensis', 'Leaf', 'Epicatechin (EC)', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Major catechin complementing EGCG, ECG, and EGC while contributing antioxidant activity across all tea types.', NULL),
  (201, 'Thuja', 'Thuja occidentalis', 'Leafy twigs', 'α-Thujone', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene ketone contributing the herb''s characteristic aroma and dose-dependent neurotoxicity.', 'Thuja occidentalis is defined primarily by its thujone-rich volatile oil, particularly α- and β-thujone, together with other oxygenated monoterpenes. Unlike many aromatic conifers, Thuja also contains well-characterized immunomodulating polysaccharides, making the combination of volatile terpenes and polysaccharides a more representative phytochemical fingerprint than the essential oil alone.'),
  (201, 'Thuja', 'Thuja occidentalis', 'Leafy twigs', 'β-Thujone', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major companion monoterpene complementing α-thujone in the characteristic volatile oil profile.', NULL),
  (201, 'Thuja', 'Thuja occidentalis', 'Leafy twigs', 'Fenchone', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic ketonic monoterpene contributing aromatic and antimicrobial activity.', NULL),
  (201, 'Thuja', 'Thuja occidentalis', 'Leafy twigs', 'Sabinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic bicyclic monoterpene contributing to the volatile oil profile and antimicrobial activity.', NULL),
  (201, 'Thuja', 'Thuja occidentalis', 'Leafy twigs', 'Borneol', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Characteristic oxygenated monoterpene complementing the essential oil chemistry with antimicrobial activity.', NULL),
  (201, 'Thuja', 'Thuja occidentalis', 'Leafy twigs', 'Deoxypodophyllotoxin', 'Lignan', 'Aryltetralin lignan', 'Moderate', 'Present', 'Characteristic lignan contributing cytotoxic and antiviral activity while complementing the monoterpene-rich chemistry of the leafy twigs.', NULL),
  (59, 'Thyme', 'Thymus vulgaris', 'Leaf', 'Thymol', 'Terpenoid', 'Monoterpenoid phenol', 'High', 'Marker', 'Principal phenolic monoterpene responsible for the herb''s characteristic antimicrobial and antiseptic activity.', 'Thymus vulgaris is chemically defined by its phenolic monoterpenes, particularly thymol and carvacrol, together with their biosynthetic precursors p-cymene and γ-terpinene. Rosmarinic acid provides the characteristic non-volatile phenolic component shared with many Lamiaceae, while luteolin represents the flavonoid fraction without overshadowing the herb''s defining volatile chemistry.'),
  (59, 'Thyme', 'Thymus vulgaris', 'Leaf', 'Carvacrol', 'Terpenoid', 'Monoterpenoid phenol', 'High', 'Major', 'Major phenolic monoterpene complementing thymol with potent antimicrobial activity.', NULL),
  (59, 'Thyme', 'Thymus vulgaris', 'Leaf', 'p-Cymene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Major monoterpene precursor contributing to the characteristic essential oil profile.', NULL),
  (59, 'Thyme', 'Thymus vulgaris', 'Leaf', 'γ-Terpinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene biosynthetic precursor to thymol and carvacrol.', NULL),
  (59, 'Thyme', 'Thymus vulgaris', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Moderate', 'Present', 'Characteristic phenolic contributing antioxidant and anti-inflammatory activity while complementing the volatile oil.', NULL),
  (59, 'Thyme', 'Thymus vulgaris', 'Leaf', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Characteristic flavone contributing antioxidant activity and complementing the phenolic profile.', NULL),
  (NULL, 'Thyme', 'Thymus spp.', 'Leaf', 'Thymol', 'Terpenoid', 'Monoterpenoid phenol', 'High', 'Marker', 'Characteristic phenolic monoterpene occurring across many medicinal Thymus species and contributing potent antimicrobial activity.', 'Unlike Thymus vulgaris, which is often characterized by a thymol chemotype, the genus Thymus encompasses multiple chemotypes, including thymol, carvacrol, linalool, and geraniol types. This profile therefore emphasizes constituents that represent the broader phytochemical diversity of the genus rather than any single species. This distinction follows your editorial rule of treating species and genus entries separately when both exist.'),
  (NULL, 'Thyme', 'Thymus spp.', 'Leaf', 'Carvacrol', 'Terpenoid', 'Monoterpenoid phenol', 'High', 'Major', 'Major phenolic monoterpene complementing thymol and contributing broad-spectrum antimicrobial activity.', NULL),
  (NULL, 'Thyme', 'Thymus spp.', 'Leaf', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene representing the linalool chemotype found in several medicinal Thymus species.', NULL),
  (NULL, 'Thyme', 'Thymus spp.', 'Leaf', 'Thymohydroquinone', 'Terpenoid', 'Monoterpenoid phenol', 'Moderate', 'Present', 'Characteristic phenolic monoterpene occurring across several Thymus species and complementing thymol with antimicrobial and antioxidant activity.', NULL),
  (NULL, 'Thyme', 'Thymus spp.', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Moderate', 'Present', 'Characteristic phenolic contributing antioxidant and anti-inflammatory activity across the genus.', NULL),
  (NULL, 'Thyme', 'Thymus spp.', 'Leaf', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Representative flavone contributing antioxidant activity and complementing the phenolic profile.', NULL),
  (194, 'Tolu Balsam', 'Myroxylon balsamum var. balsamum', 'Balsam', 'Benzyl benzoate', 'Phenylpropanoid', 'Aromatic ester', 'High', 'Marker', 'Principal aromatic ester contributing expectorant, antimicrobial, and preservative activity.', 'Tolu balsam is chemically distinguished by its high content of benzyl esters of cinnamic and benzoic acids, rather than by terpenes or polyphenols. The combination of benzyl benzoate, benzyl cinnamate, and their corresponding aromatic acids provides one of the clearest chemotaxonomic fingerprints among medicinal balsams, while vanillin and nerolidol round out the characteristic aromatic profile.'),
  (194, 'Tolu Balsam', 'Myroxylon balsamum var. balsamum', 'Balsam', 'Benzyl cinnamate', 'Phenylpropanoid', 'Aromatic ester', 'High', 'Major', 'Major aromatic ester contributing the balsam''s characteristic fragrance and antimicrobial activity.', NULL),
  (194, 'Tolu Balsam', 'Myroxylon balsamum var. balsamum', 'Balsam', 'Cinnamic acid', 'Phenylpropanoid', 'Aromatic acid', 'Moderate', 'Major', 'Characteristic aromatic acid contributing antimicrobial activity and serving as a precursor to the balsam esters.', NULL),
  (194, 'Tolu Balsam', 'Myroxylon balsamum var. balsamum', 'Balsam', 'Benzoic acid', 'Phenylpropanoid', 'Aromatic acid', 'Moderate', 'Major', 'Characteristic aromatic acid contributing preservative and antimicrobial activity.', NULL),
  (194, 'Tolu Balsam', 'Myroxylon balsamum var. balsamum', 'Balsam', 'Vanillin', 'Phenylpropanoid', 'Aromatic aldehyde', 'Low–Moderate', 'Present', 'Characteristic aromatic aldehyde contributing the balsam''s sweet vanilla-like aroma.', NULL),
  (194, 'Tolu Balsam', 'Myroxylon balsamum var. balsamum', 'Balsam', 'Benzyl alcohol', 'Phenylpropanoid', 'Aromatic alcohol', 'Moderate', 'Present', 'Characteristic aromatic alcohol serving as a precursor to the major benzyl esters and complementing the balsam''s characteristic fragrance profile.', NULL),
  (203, 'Turmeric', 'Curcuma longa', 'Rhizome', 'Curcumin', 'Polyphenol', 'Diarylheptanoid', 'High', 'Marker', 'Principal curcuminoid contributing anti-inflammatory, antioxidant, and hepatoprotective activity.', 'Curcuma longa is defined by two complementary constituent families: the curcuminoids (diarylheptanoids), which account for its characteristic yellow pigment and many anti-inflammatory properties, and the turmerones, which dominate the volatile oil and contribute important neuroprotective and anti-inflammatory activities. Representing both groups provides the clearest phytochemical fingerprint of the medicinal rhizome.'),
  (203, 'Turmeric', 'Curcuma longa', 'Rhizome', 'Demethoxycurcumin', 'Polyphenol', 'Diarylheptanoid', 'High', 'Major', 'Major companion curcuminoid complementing curcumin in the characteristic yellow pigment fraction.', NULL),
  (203, 'Turmeric', 'Curcuma longa', 'Rhizome', 'Bisdemethoxycurcumin', 'Polyphenol', 'Diarylheptanoid', 'Moderate', 'Major', 'Characteristic curcuminoid completing the representative curcuminoid profile.', NULL),
  (203, 'Turmeric', 'Curcuma longa', 'Rhizome', 'ar-Turmerone', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Principal sesquiterpene ketone contributing anti-inflammatory and neuroprotective activity.', NULL),
  (203, 'Turmeric', 'Curcuma longa', 'Rhizome', 'α-Turmerone', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Characteristic sesquiterpene complementing ar-turmerone in the volatile oil fraction.', NULL),
  (203, 'Turmeric', 'Curcuma longa', 'Rhizome', 'Curlone (β-Turmerone)', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Characteristic sesquiterpene completing the representative turmerone profile.', NULL),
  (46, 'Uva Ursi', 'Arctostaphylos uva-ursi', 'Leaf', 'Arbutin', 'Glycoside', 'Hydroquinone glycoside', 'High', 'Marker', 'Principal hydroquinone glycoside responsible for the herb''s urinary antiseptic activity following enzymatic hydrolysis to hydroquinone.', 'Arctostaphylos uva-ursi is chemically distinguished by its hydroquinone glycosides, particularly arbutin, which are responsible for its classic urinary antiseptic action. The accompanying hydrolyzable tannins provide astringency and anti-inflammatory effects, while ursolic acid and flavonoids round out the leaf''s representative phytochemical fingerprint.'),
  (46, 'Uva Ursi', 'Arctostaphylos uva-ursi', 'Leaf', 'Methylarbutin', 'Glycoside', 'Hydroquinone glycoside', 'High', 'Major', 'Major companion hydroquinone glycoside complementing arbutin and contributing urinary antiseptic activity.', NULL),
  (46, 'Uva Ursi', 'Arctostaphylos uva-ursi', 'Leaf', 'Gallotannins', 'Tannin', 'Hydrolyzable tannin', 'Moderate', 'Major', 'Characteristic hydrolyzable tannins contributing astringent and anti-inflammatory activity while complementing the hydroquinone glycosides.', NULL),
  (46, 'Uva Ursi', 'Arctostaphylos uva-ursi', 'Leaf', 'Corilagin', 'Tannin', 'Hydrolyzable tannin', 'Moderate', 'Present', 'Characteristic ellagitannin contributing astringent, antioxidant, and anti-inflammatory activity while complementing the hydroquinone glycosides.', NULL),
  (46, 'Uva Ursi', 'Arctostaphylos uva-ursi', 'Leaf', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'Moderate', 'Present', 'Characteristic triterpenoid contributing anti-inflammatory activity and complementing the tannin-rich chemistry.', NULL),
  (46, 'Uva Ursi', 'Arctostaphylos uva-ursi', 'Leaf', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol contributing antioxidant activity and complementing the phenolic profile.', NULL),
  (145, 'Valerian', 'Valeriana officinalis', 'Root', 'Valerenic acid', 'Terpenoid', 'Sesquiterpenoid acid', 'High', 'Marker', 'Principal sesquiterpenoid acid contributing modulation of GABA-A receptors and the herb''s characteristic sedative activity.', 'Valeriana officinalis is chemically distinguished by two complementary constituent families: the valerenic acids, which are primarily responsible for modulation of GABAergic signaling, and the valepotriates (iridoid esters), which contribute additional spasmolytic and sedative properties. Representing both groups captures the herb''s defining phytochemical fingerprint while avoiding overemphasis on ubiquitous minor constituents.'),
  (145, 'Valerian', 'Valeriana officinalis', 'Root', 'Acetoxyvalerenic acid', 'Terpenoid', 'Sesquiterpenoid acid', 'High', 'Major', 'Major companion sesquiterpenoid acid complementing valerenic acid and contributing to the characteristic sesquiterpene profile.', NULL),
  (145, 'Valerian', 'Valeriana officinalis', 'Root', 'Hydroxyvalerenic acid', 'Terpenoid', 'Sesquiterpenoid acid', 'Moderate', 'Major', 'Characteristic sesquiterpenoid acid completing the representative valerenic acid series.', NULL),
  (145, 'Valerian', 'Valeriana officinalis', 'Root', 'Valtrate', 'Terpenoid', 'Iridoid ester', 'Moderate', 'Major', 'Principal valepotriate contributing spasmolytic activity and complementing the sesquiterpenoid fraction.', NULL),
  (145, 'Valerian', 'Valeriana officinalis', 'Root', 'Didrovaltrate', 'Terpenoid', 'Iridoid ester', 'Moderate', 'Present', 'Characteristic valepotriate expanding the representative iridoid ester profile.', NULL),
  (145, 'Valerian', 'Valeriana officinalis', 'Root', 'Valerenoside', 'Terpenoid', 'Sesquiterpenoid glycoside', 'Low–Moderate', 'Present', 'Characteristic sesquiterpenoid glycoside complementing the valerenic acids and expanding the representative sesquiterpenoid profile of the root.', NULL),
  (146, 'Vervain', 'Verbena officinalis', 'Aerial parts', 'Verbenalin', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid glycoside contributing the herb''s bitter, nervine, and anti-inflammatory activity.', 'Verbena officinalis is chemically defined by its iridoid glycosides, particularly verbenalin and hastatoside, supported by verbascoside and flavones. This combination provides a distinctive phytochemical fingerprint while reflecting the herb''s traditional use as a bitter tonic, nervine, and anti-inflammatory remedy.'),
  (146, 'Vervain', 'Verbena officinalis', 'Aerial parts', 'Hastatoside', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Major companion iridoid glycoside complementing verbenalin and contributing to the characteristic bitter profile.', NULL),
  (146, 'Vervain', 'Verbena officinalis', 'Aerial parts', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Major', 'Principal phenylethanoid glycoside contributing antioxidant, anti-inflammatory, and neuroprotective activity while complementing the iridoid glycosides.', NULL),
  (146, 'Vervain', 'Verbena officinalis', 'Aerial parts', 'Verbascoside (Acteoside)', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Characteristic phenylethanoid glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (146, 'Vervain', 'Verbena officinalis', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Characteristic flavone contributing antioxidant and mild spasmolytic activity while complementing the iridoid and phenylethanoid fractions.', NULL),
  (146, 'Vervain', 'Verbena officinalis', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Characteristic flavone complementing the flavonoid profile with antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'White Oak', 'Quercus alba', 'Bark', 'Castalagin', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Principal ellagitannin contributing the bark''s characteristic astringent and anti-inflammatory activity.', 'The medicinal bark of Quercus alba is defined by its exceptionally high concentration of ellagitannins, particularly castalagin, vescalagin, and related roburins. These hydrolyzable tannins account for the bark''s pronounced astringency and traditional use as a topical and gastrointestinal remedy. The remaining constituents represent characteristic hydrolysis products and associated phenolics without overshadowing the dominant tannin chemistry.'),
  (NULL, 'White Oak', 'Quercus alba', 'Bark', 'Vescalagin', 'Tannin', 'Ellagitannin', 'High', 'Major', 'Major companion ellagitannin complementing castalagin and contributing potent astringency.', NULL),
  (NULL, 'White Oak', 'Quercus alba', 'Bark', 'Roburin A', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Characteristic ellagitannin contributing antioxidant and astringent activity.', NULL),
  (NULL, 'White Oak', 'Quercus alba', 'Bark', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Present', 'Characteristic phenolic derived from ellagitannins and contributing antioxidant activity.', NULL),
  (NULL, 'White Oak', 'Quercus alba', 'Bark', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Low–Moderate', 'Present', 'Characteristic flavan-3-ol contributing antioxidant activity and serving as a precursor to condensed tannins.', NULL),
  (NULL, 'White Oak', 'Quercus alba', 'Bark', 'Roburin E', 'Tannin', 'Ellagitannin', 'Moderate', 'Present', 'Characteristic ellagitannin complementing castalagin, vescalagin, and roburin A while expanding the representative hydrolyzable tannin profile of the bark.', NULL),
  (NULL, 'White Pond Lily', 'Nymphaea odorata', 'Rhizome', 'Corilagin', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Principal ellagitannin contributing the rhizome''s characteristic astringent and anti-inflammatory activity while serving as a defining chemotaxonomic marker.', 'Nymphaea odorata rhizome is characterized by a hydrolyzable tannin-rich chemistry, with tellimagrandins providing a more distinctive fingerprint than the ubiquitous simple phenolic acids alone. The combination of ellagitannins, gallic acid derivatives, and flavonols reflects the herb''s traditional use as a potent astringent while remaining faithful to the best-documented phytochemistry.'),
  (NULL, 'White Pond Lily', 'Nymphaea odorata', 'Rhizome', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'High', 'Major', 'Major phenolic complementing gallic acid and contributing antioxidant activity.', NULL),
  (NULL, 'White Pond Lily', 'Nymphaea odorata', 'Rhizome', 'Tellimagrandin I', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Characteristic ellagitannin contributing astringent activity and complementing the simple phenolics.', NULL),
  (NULL, 'White Pond Lily', 'Nymphaea odorata', 'Rhizome', 'Tellimagrandin II', 'Tannin', 'Ellagitannin', 'Moderate', 'Present', 'Characteristic ellagitannin expanding the representative tannin profile.', NULL),
  (NULL, 'White Pond Lily', 'Nymphaea odorata', 'Rhizome', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol contributing antioxidant activity.', NULL),
  (NULL, 'White Pond Lily', 'Nymphaea odorata', 'Rhizome', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol complementing the antioxidant profile.', NULL),
  (140, 'Wild Cherry', 'Prunus serotina', 'Bark', 'Prunasin', 'Glycoside', 'Cyanogenic glycoside', 'High', 'Marker', 'Principal cyanogenic glycoside responsible for the bark''s characteristic chemistry and contributing to its traditional antitussive activity after controlled hydrolysis.', 'The medicinal bark of Prunus serotina is defined by its cyanogenic glycosides, especially prunasin and amygdalin, which distinguish it from most medicinal barks. The accompanying coumarins and phenolics provide a representative secondary phytochemical profile while preserving the bark''s defining cyanogenic chemistry.'),
  (140, 'Wild Cherry', 'Prunus serotina', 'Bark', 'Amygdalin', 'Glycoside', 'Cyanogenic glycoside', 'High', 'Major', 'Major companion cyanogenic glycoside complementing prunasin and contributing to the bark''s characteristic phytochemical profile.', NULL),
  (140, 'Wild Cherry', 'Prunus serotina', 'Bark', 'Scopoletin', 'Coumarin', 'Simple coumarin', 'Moderate', 'Major', 'Characteristic coumarin contributing anti-inflammatory and antioxidant activity.', NULL),
  (140, 'Wild Cherry', 'Prunus serotina', 'Bark', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Characteristic flavan-3-ol contributing antioxidant activity and complementing the bark''s polyphenol fraction.', NULL),
  (140, 'Wild Cherry', 'Prunus serotina', 'Bark', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Characteristic phenolic contributing antioxidant activity while complementing the cyanogenic glycosides.', NULL),
  (140, 'Wild Cherry', 'Prunus serotina', 'Bark', 'Neochlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Characteristic caffeoylquinic acid complementing chlorogenic acid and contributing antioxidant activity while expanding the representative phenolic profile of the bark.', NULL),
  (23, 'Wild Indigo', 'Baptisia tinctoria', 'Root', 'Baptifoline', 'Alkaloid', 'Quinolizidine alkaloid', 'High', 'Marker', 'Characteristic quinolizidine alkaloid serving as a chemotaxonomic marker for Baptisia tinctoria while contributing to the root''s distinctive alkaloid profile.', 'Baptisia tinctoria is distinguished by a combination of quinolizidine alkaloids and isoflavones, a characteristic pattern seen in several medicinal members of the Fabaceae. The inclusion of baptisin provides an additional chemotaxonomic marker unique to the genus while preserving the dominant alkaloid chemistry of the medicinal root.'),
  (23, 'Wild Indigo', 'Baptisia tinctoria', 'Root', 'Cytisine', 'Alkaloid', 'Quinolizidine alkaloid', 'High', 'Major', 'Principal quinolizidine alkaloid contributing immunomodulatory activity and the characteristic alkaloid profile.', NULL),
  (23, 'Wild Indigo', 'Baptisia tinctoria', 'Root', 'Anagyrine', 'Alkaloid', 'Quinolizidine alkaloid', 'Moderate', 'Major', 'Characteristic quinolizidine alkaloid complementing cytisine in the root''s alkaloid fraction.', NULL),
  (23, 'Wild Indigo', 'Baptisia tinctoria', 'Root', 'Lupanine', 'Alkaloid', 'Quinolizidine alkaloid', 'Moderate', 'Present', 'Characteristic quinolizidine alkaloid contributing to the representative alkaloid profile.', NULL),
  (23, 'Wild Indigo', 'Baptisia tinctoria', 'Root', 'Genistein', 'Flavonoid', 'Isoflavone', 'Low–Moderate', 'Present', 'Characteristic isoflavone contributing antioxidant activity and complementing the alkaloid-rich chemistry.', NULL),
  (23, 'Wild Indigo', 'Baptisia tinctoria', 'Root', 'Formononetin', 'Flavonoid', 'Isoflavone', 'Low–Moderate', 'Present', 'Characteristic isoflavone complementing genistein and expanding the representative flavonoid profile.', NULL),
  (130, 'Wild Lettuce', 'Lactuca virosa', 'Latex', 'Lactucin', 'Terpenoid', 'Sesquiterpene lactone', 'High', 'Marker', 'Principal sesquiterpene lactone contributing the characteristic bitter, sedative, and analgesic activity of the latex.', 'Lactuca virosa is overwhelmingly defined by its sesquiterpene lactones, particularly lactucin and lactucopicrin, which are responsible for its characteristic bitter, sedative, and analgesic properties. The inclusion of chicoric acid provides a representative non-lactone constituent common to Lactuca species without diluting the herb''s defining chemistry.'),
  (130, 'Wild Lettuce', 'Lactuca virosa', 'Latex', 'Lactucopicrin', 'Terpenoid', 'Sesquiterpene lactone', 'High', 'Major', 'Major sesquiterpene lactone complementing lactucin and contributing sedative and analgesic activity.', NULL),
  (130, 'Wild Lettuce', 'Lactuca virosa', 'Latex', '11β,13-Dihydrolactucin', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Major', 'Characteristic sesquiterpene lactone expanding the representative bitter lactone profile.', NULL),
  (130, 'Wild Lettuce', 'Lactuca virosa', 'Latex', '11β,13-Dihydrolactucopicrin', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Present', 'Characteristic companion sesquiterpene lactone complementing lactucopicrin.', NULL),
  (130, 'Wild Lettuce', 'Lactuca virosa', 'Latex', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Characteristic flavone contributing antioxidant activity and complementing the bitter lactones.', NULL),
  (130, 'Wild Lettuce', 'Lactuca virosa', 'Latex', 'Lactucerin', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Present', 'Characteristic sesquiterpene lactone complementing lactucin and lactucopicrin while expanding the representative bitter lactone profile of the latex.', NULL),
  (74, 'Wild Yam', 'Dioscorea villosa', 'Rhizome', 'Diosgenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Marker', 'Principal steroidal sapogenin contributing anti-inflammatory activity and serving as the defining chemotaxonomic marker of the rhizome.', 'Dioscorea villosa is defined by its steroidal saponins, particularly dioscin, protodioscin, and their sapogenins diosgenin and yamogenin. These constituents provide one of the clearest steroidal phytochemical fingerprints among medicinal roots, while β-sitosterol and allantoin serve as representative secondary constituents without overshadowing the dominant steroidal chemistry.'),
  (74, 'Wild Yam', 'Dioscorea villosa', 'Rhizome', 'Dioscin', 'Glycoside', 'Steroidal glycoside', 'High', 'Major', 'Major steroidal saponin serving as the glycosidic precursor of diosgenin and contributing to the characteristic steroidal profile.', NULL),
  (74, 'Wild Yam', 'Dioscorea villosa', 'Rhizome', 'Protodioscin', 'Glycoside', 'Steroidal glycoside', 'Moderate', 'Major', 'Characteristic furostanol saponin complementing dioscin and contributing to the representative steroidal saponin profile.', NULL),
  (74, 'Wild Yam', 'Dioscorea villosa', 'Rhizome', 'Yamogenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Present', 'Characteristic steroidal sapogenin complementing diosgenin in the aglycone fraction.', NULL),
  (74, 'Wild Yam', 'Dioscorea villosa', 'Rhizome', 'β-Sitosterol', 'Sterol', 'Phytosterol', 'Low–Moderate', 'Present', 'Characteristic phytosterol contributing anti-inflammatory activity while complementing the steroidal saponins.', NULL),
  (74, 'Wild Yam', 'Dioscorea villosa', 'Rhizome', 'Gracillin', 'Glycoside', 'Steroidal glycoside', 'Moderate', 'Present', 'Characteristic steroidal saponin complementing dioscin and protodioscin while expanding the representative steroidal glycoside profile of the rhizome.', NULL),
  (79, 'Witch Hazel', 'Hamamelis virginiana', 'Leaf', 'Hamamelitannin', 'Tannin', 'Gallotannin', 'High', 'Marker', 'Principal gallotannin contributing the leaf''s characteristic astringent, antioxidant, and anti-inflammatory activity.', 'The medicinal leaves of Hamamelis virginiana are defined by their hydrolyzable tannins, particularly hamamelitannin, which account for the herb''s classic astringent activity. The accompanying phenolic acids and flavonoids provide a representative secondary phytochemical profile while preserving the dominant tannin chemistry that distinguishes witch hazel.'),
  (79, 'Witch Hazel', 'Hamamelis virginiana', 'Leaf', 'Hamamelose', 'Carbohydrate', 'Monosaccharide', 'Moderate', 'Major', 'Characteristic branched-chain ketohexose first isolated from Hamamelis virginiana, serving as a distinctive chemotaxonomic marker of the species while complementing the tannin-rich chemistry.', NULL),
  (79, 'Witch Hazel', 'Hamamelis virginiana', 'Leaf', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Major', 'Characteristic phenolic produced from ellagitannins and contributing antioxidant activity.', NULL),
  (79, 'Witch Hazel', 'Hamamelis virginiana', 'Leaf', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Characteristic flavonol contributing antioxidant and anti-inflammatory activity.', NULL),
  (79, 'Witch Hazel', 'Hamamelis virginiana', 'Leaf', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol complementing the flavonoid profile.', NULL),
  (79, 'Witch Hazel', 'Hamamelis virginiana', 'Leaf', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Low–Moderate', 'Present', 'Characteristic flavan-3-ol contributing antioxidant activity and complementing the tannin-rich chemistry.', NULL),
  (97, 'Wormwood', 'Artemisia absinthium', 'Aerial parts', 'Absinthin', 'Terpenoid', 'Sesquiterpene lactone', 'High', 'Marker', 'Principal bitter sesquiterpene lactone responsible for the herb''s characteristic intensely bitter taste and digestive stimulant activity.', 'Artemisia absinthium is chemically distinguished by the combination of sesquiterpene lactones, particularly absinthin, and a thujone-containing volatile oil. Representing both constituent families captures the herb''s defining bitter and aromatic chemistry while avoiding overemphasis on ubiquitous flavonoids or phenolic acids.'),
  (97, 'Wormwood', 'Artemisia absinthium', 'Aerial parts', 'Anabsinthin', 'Terpenoid', 'Sesquiterpene lactone', 'High', 'Major', 'Major companion sesquiterpene lactone complementing absinthin and contributing to the characteristic bitter profile.', NULL),
  (97, 'Wormwood', 'Artemisia absinthium', 'Aerial parts', 'α-Thujone', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Principal monoterpene ketone contributing to the volatile oil and dose-dependent neurotoxicity.', NULL),
  (97, 'Wormwood', 'Artemisia absinthium', 'Aerial parts', 'β-Thujone', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Companion monoterpene ketone complementing α-thujone in the essential oil profile.', NULL),
  (97, 'Wormwood', 'Artemisia absinthium', 'Aerial parts', 'Artemisetin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Characteristic polymethoxylated flavone contributing antioxidant and anti-inflammatory activity while complementing the sesquiterpene lactones and volatile oil.', NULL),
  (97, 'Wormwood', 'Artemisia absinthium', 'Aerial parts', 'Artabsin', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Present', 'Characteristic sesquiterpene lactone complementing the absinthin series and expanding the representative bitter lactone profile.', NULL),
  (44, 'Yarrow', 'Achillea millefolium', 'Aerial parts', 'Matricin', 'Terpenoid', 'Sesquiterpene lactone', 'High', 'Marker', 'Principal sesquiterpene lactone serving as the precursor of chamazulene and contributing anti-inflammatory activity.', 'Achillea millefolium is chemically defined by three major constituent families: sesquiterpene lactones, flavones, and a volatile monoterpene-rich essential oil. Using matricin rather than chamazulene follows the database''s rule of recording constituents actually present in the medicinal plant, since chamazulene is produced only during distillation. The resulting profile provides a stronger chemotaxonomic fingerprint while remaining faithful to the herb''s medicinal chemistry.'),
  (44, 'Yarrow', 'Achillea millefolium', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'High', 'Major', 'Principal flavone contributing anti-inflammatory, antioxidant, and spasmolytic activity.', NULL),
  (44, 'Yarrow', 'Achillea millefolium', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'High', 'Major', 'Major flavone complementing apigenin and contributing antioxidant and anti-inflammatory activity.', NULL),
  (44, 'Yarrow', 'Achillea millefolium', 'Aerial parts', 'Achillicin', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Present', 'Characteristic sesquiterpene lactone complementing matricin and contributing to the representative bitter lactone profile of the aerial parts.', NULL),
  (44, 'Yarrow', 'Achillea millefolium', 'Aerial parts', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic volatile monoterpene contributing aromatic, antimicrobial, and expectorant activity.', NULL),
  (44, 'Yarrow', 'Achillea millefolium', 'Aerial parts', 'Camphor', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic ketonic monoterpene complementing the volatile oil profile and contributing antimicrobial activity.', NULL),
  (37, 'Yellow Dock', 'Rumex crispus', 'Root', 'Chrysophanol', 'Anthraquinone', 'Anthraquinone', 'High', 'Marker', 'Principal anthraquinone contributing the root''s mild stimulant laxative activity.', 'The medicinal root of Rumex crispus is chemically distinguished by a combination of anthraquinones and naphthalene derivatives. While the anthraquinones account for the root''s traditional laxative action, nepodin provides an additional chemotaxonomic marker that distinguishes Rumex from other anthraquinone-containing medicinal plants.'),
  (37, 'Yellow Dock', 'Rumex crispus', 'Root', 'Emodin', 'Anthraquinone', 'Anthraquinone', 'High', 'Major', 'Major anthraquinone complementing chrysophanol and contributing laxative and antimicrobial activity.', NULL),
  (37, 'Yellow Dock', 'Rumex crispus', 'Root', 'Physcion', 'Anthraquinone', 'Anthraquinone', 'Moderate', 'Major', 'Characteristic anthraquinone contributing antimicrobial activity and expanding the representative anthraquinone profile.', NULL),
  (37, 'Yellow Dock', 'Rumex crispus', 'Root', 'Nepodin', 'Naphthalene derivative', 'Naphthalene derivative', 'Moderate', 'Present', 'Characteristic naphthalene derivative contributing antioxidant activity and serving as a chemotaxonomic marker for Rumex.', NULL),
  (37, 'Yellow Dock', 'Rumex crispus', 'Root', 'Chrysarobin', 'Anthraquinone', 'Anthrone', 'Moderate', 'Present', 'Characteristic reduced anthraquinone derivative complementing chrysophanol and emodin while expanding the representative anthraquinone profile of the root.', NULL),
  (37, 'Yellow Dock', 'Rumex crispus', 'Root', 'Procyanidins', 'Tannin', 'Condensed tannin', 'Low–Moderate', 'Present', 'Characteristic condensed tannins contributing mild astringency and complementing the anthraquinone fraction.', NULL),
  (309, 'Yerba Mansa', 'Anemopsis californica', 'Root', 'Methyleugenol', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Marker', 'Principal phenylpropene contributing the root''s characteristic aromatic, antimicrobial, and anti-inflammatory activity.', 'Anemopsis californica is chemically distinguished by a phenylpropene-rich volatile oil, unlike most medicinal roots. The combination of methyleugenol, elemicin, and safrole, together with monoterpenes such as thymol and 1,8-cineole, produces one of the most distinctive aromatic phytochemical fingerprints among North American medicinal herbs.'),
  (309, 'Yerba Mansa', 'Anemopsis californica', 'Root', 'Elemicin', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Major', 'Major aromatic phenylpropene complementing methyleugenol in the volatile oil fraction.', NULL),
  (309, 'Yerba Mansa', 'Anemopsis californica', 'Root', 'Anethole', 'Phenylpropanoid', 'Phenylpropene', 'Moderate', 'Major', 'Characteristic phenylpropene complementing methyleugenol and elemicin while contributing antimicrobial activity and expanding the representative aromatic profile of the root.', NULL),
  (309, 'Yerba Mansa', 'Anemopsis californica', 'Root', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic monoterpene contributing aromatic and expectorant activity.', NULL),
  (309, 'Yerba Mansa', 'Anemopsis californica', 'Root', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Characteristic monoterpene complementing the volatile oil profile.', NULL),
  (309, 'Yerba Mansa', 'Anemopsis californica', 'Root', 'Safrole', 'Phenylpropanoid', 'Phenylpropene', 'Low–Moderate', 'Present', 'Characteristic phenylpropene contributing to the distinctive aromatic profile of the root.', NULL),
  (NULL, 'Yohimbe', 'Pausinystalia johimbe', 'Bark', 'Yohimbine', 'Alkaloid', 'Indole alkaloid', 'High', 'Marker', 'Principal indole alkaloid responsible for the bark''s α₂-adrenergic antagonism and traditional stimulant activity.', 'Pausinystalia johimbe is one of the clearest examples of a medicinal plant defined almost entirely by a single constituent family. Its corynanthe-type indole alkaloids, particularly yohimbine, account for both its pharmacological activity and its chemotaxonomic identity, making additional non-alkaloid constituents unnecessary for a representative phytochemical profile.'),
  (NULL, 'Yohimbe', 'Pausinystalia johimbe', 'Bark', 'Corynanthine', 'Alkaloid', 'Indole alkaloid', 'High', 'Major', 'Major companion indole alkaloid complementing yohimbine and contributing to the characteristic alkaloid profile.', NULL),
  (NULL, 'Yohimbe', 'Pausinystalia johimbe', 'Bark', 'Ajmalicine (Raubasine)', 'Alkaloid', 'Indole alkaloid', 'Moderate', 'Major', 'Characteristic indole alkaloid contributing vasodilatory activity and expanding the representative alkaloid profile.', NULL),
  (NULL, 'Yohimbe', 'Pausinystalia johimbe', 'Bark', 'Yohimbenine', 'Alkaloid', 'Indole alkaloid', 'Moderate', 'Present', 'Characteristic indole alkaloid complementing the yohimbine alkaloid complex.', NULL),
  (NULL, 'Yohimbe', 'Pausinystalia johimbe', 'Bark', 'Alloyohimbine (Raubasine isomer)', 'Alkaloid', 'Indole alkaloid', 'Low–Moderate', 'Present', 'Characteristic corynanthe-type indole alkaloid complementing yohimbine and expanding the representative alkaloid profile of the bark.', NULL),
  (NULL, 'Yohimbe', 'Pausinystalia johimbe', 'Bark', 'Akuammigine', 'Alkaloid', 'Indole alkaloid', 'Low–Moderate', 'Present', 'Characteristic indole alkaloid expanding the representative corynanthe alkaloid profile.', NULL),
  (NULL, 'Yucca', 'Yucca spp.', 'Root', 'Sarsasapogenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Marker', 'Principal steroidal sapogenin contributing anti-inflammatory activity and serving as the defining chemotaxonomic marker of the root.', 'Yucca species are chemically defined by their steroidal saponins and sapogenins, which account for much of their anti-inflammatory and surfactant properties. The inclusion of resveratrol represents the lesser-known phenolic fraction while preserving the dominant steroidal chemistry that distinguishes the genus.'),
  (NULL, 'Yucca', 'Yucca spp.', 'Root', 'Smilagenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Major', 'Major companion sapogenin complementing sarsasapogenin in the characteristic steroidal profile.', NULL),
  (NULL, 'Yucca', 'Yucca spp.', 'Root', 'Yuccagenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Major', 'Characteristic steroidal sapogenin contributing to the representative yucca saponin profile.', NULL),
  (NULL, 'Yucca', 'Yucca spp.', 'Root', 'Yuccasaponin A', 'Glycoside', 'Steroidal glycoside', 'Moderate', 'Major', 'Characteristic steroidal saponin contributing anti-inflammatory activity while complementing the sapogenin fraction.', NULL),
  (NULL, 'Yucca', 'Yucca spp.', 'Root', 'Chlorogenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Present', 'Characteristic steroidal sapogenin expanding the representative steroidal profile.', NULL),
  (NULL, 'Yucca', 'Yucca spp.', 'Root', 'Tigogenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Present', 'Characteristic steroidal sapogenin complementing sarsasapogenin, smilagenin, and chlorogenin while expanding the representative steroidal profile of the root.', NULL),
  (NULL, 'Zedoary', 'Curcuma zedoaria', 'Rhizome', 'Curzerenone', 'Terpenoid', 'Sesquiterpene', 'High', 'Marker', 'Principal sesquiterpene contributing the rhizome''s characteristic anti-inflammatory and digestive activity.', 'Unlike turmeric (Curcuma longa), whose medicinal chemistry is dominated by curcuminoids, zedoary is characterized primarily by a sesquiterpene-rich volatile oil. Including only one curcuminoid while emphasizing the major sesquiterpenes provides a phytochemical fingerprint that clearly distinguishes the two species despite their close relationship.'),
  (NULL, 'Zedoary', 'Curcuma zedoaria', 'Rhizome', 'Curdione', 'Terpenoid', 'Sesquiterpene', 'High', 'Major', 'Major sesquiterpene complementing curzerenone and contributing anti-inflammatory activity.', NULL),
  (NULL, 'Zedoary', 'Curcuma zedoaria', 'Rhizome', 'Germacrone', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Characteristic sesquiterpene contributing anti-inflammatory and antiproliferative activity.', NULL),
  (NULL, 'Zedoary', 'Curcuma zedoaria', 'Rhizome', 'Curcumenol', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Characteristic oxygenated sesquiterpene complementing the volatile oil profile.', NULL),
  (NULL, 'Zedoary', 'Curcuma zedoaria', 'Rhizome', 'Curcumenone', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Characteristic sesquiterpene ketone expanding the representative zedoary volatile oil profile.', NULL),
  (NULL, 'Zedoary', 'Curcuma zedoaria', 'Rhizome', 'Curcumin', 'Polyphenol', 'Diarylheptanoid', 'Low–Moderate', 'Present', 'Minor curcuminoid complementing the sesquiterpene-rich chemistry without overshadowing the defining volatile oil constituents.', NULL),
  (885, 'Alfalfa', 'Medicago sativa', 'Aerial parts', 'Coumestrol', 'Polyphenol', 'Coumestan', 'Moderate', 'Marker', 'Phytoestrogenic constituent associated with alfalfa’s estrogenic activity.', 'Medicago sativa is best characterized by its isoflavones, coumestrol, and medicagenic acid saponins rather than any single dominant constituent. Numerous nutritional compounds and ubiquitous phenolics were intentionally omitted to keep the profile focused on constituents that best define the herb chemically and pharmacologically.'),
  (885, 'Alfalfa', 'Medicago sativa', 'Aerial parts', 'Formononetin', 'Flavonoid', 'Isoflavone', 'Moderate', 'Present', 'Isoflavone contributing to phytoestrogenic and antioxidant activity.', NULL),
  (885, 'Alfalfa', 'Medicago sativa', 'Aerial parts', 'Biochanin A', 'Flavonoid', 'Isoflavone', 'Moderate', 'Present', 'Isoflavone contributing to phytoestrogenic activity.', NULL),
  (885, 'Alfalfa', 'Medicago sativa', 'Aerial parts', 'Genistein', 'Flavonoid', 'Isoflavone', 'Low–Moderate', 'Present', 'Isoflavone associated with antioxidant and estrogen-receptor activity.', NULL),
  (885, 'Alfalfa', 'Medicago sativa', 'Aerial parts', 'Medicagenic acid 3-O-triglucoside', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Marker', 'Saponin constituent associated with membrane-active and hypolipidemic effects.', NULL),
  (885, 'Alfalfa', 'Medicago sativa', 'Aerial parts', 'L-Canavanine', 'Nitrogenous compound', 'Amino acid derivative', 'Low', 'Reported', 'Toxicologically significant non-protein amino acid; present in seeds and sprouts, but not consistently characteristic of the medicinal aerial herb.', NULL),
  (15, 'American Ginseng', 'Panax quinquefolius', 'Root', 'Ginsenoside Rb1', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal protopanaxadiol ginsenoside contributing to adaptogenic activity.', 'Panax quinquefolius is defined almost entirely by its dammarane-type ginsenosides. This profile focuses on the major ginsenosides and pseudoginsenoside F11, the constituent that most reliably distinguishes American ginseng from other Panax species, while omitting minor polyacetylenes and ubiquitous phytosterols that contribute little to its chemotaxonomic identity.'),
  (15, 'American Ginseng', 'Panax quinquefolius', 'Root', 'Ginsenoside Re', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Characteristic protopanaxatriol ginsenoside abundant in American ginseng.', NULL),
  (15, 'American Ginseng', 'Panax quinquefolius', 'Root', 'Ginsenoside Rc', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'One of the principal dammarane saponins contributing to the root''s characteristic profile.', NULL),
  (15, 'American Ginseng', 'Panax quinquefolius', 'Root', 'Ginsenoside Rd', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Major dammarane saponin contributing to immunomodulatory and neuroprotective activity.', NULL),
  (15, 'American Ginseng', 'Panax quinquefolius', 'Root', 'Pseudoginsenoside F11', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Chemotaxonomic marker that distinguishes American ginseng from Asian ginseng.', NULL),
  (15, 'American Ginseng', 'Panax quinquefolius', 'Root', 'Ginsenoside Rg1', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Present', 'Important protopanaxatriol ginsenoside present at lower levels than in Asian ginseng.', NULL),
  (NULL, 'Asian Devil''s Club', 'Oplopanax elatus', 'Root bark', 'Falcarinol', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Characteristic polyacetylene contributing to antimicrobial and cytotoxic activity.', 'Oplopanax elatus is chemically defined by its distinctive polyacetylenes, which account for much of its antimicrobial, antifungal, and cytotoxic activity. Unlike many members of the Araliaceae, its medicinal profile is not dominated by saponins, making the oplopanax-specific polyacetylenes the most representative constituents for this species.'),
  (NULL, 'Asian Devil''s Club', 'Oplopanax elatus', 'Root bark', 'Falcarindiol', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Major bioactive polyacetylene associated with antifungal and anti-inflammatory effects.', NULL),
  (NULL, 'Asian Devil''s Club', 'Oplopanax elatus', 'Root bark', 'Oplopantriol A', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Characteristic Oplopanax polyacetylene contributing to the genus'' distinctive chemistry.', NULL),
  (NULL, 'Asian Devil''s Club', 'Oplopanax elatus', 'Root bark', 'Oplopantriol B', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Present', 'Species-specific polyacetylene reported from root bark.', NULL),
  (NULL, 'Asian Devil''s Club', 'Oplopanax elatus', 'Root bark', 'Oplopanol', 'Polyacetylene', 'Polyacetylene', 'Low', 'Reported', 'Minor species-specific polyacetylene reported from root bark; not consistently recognized as a characteristic constituent.', NULL),
  (NULL, 'Asian Mint', 'Agastache rugosa', 'Aerial parts', 'Tilianin', 'Flavonoid', 'Flavone glycoside', 'High', 'Marker', 'Characteristic flavone glycoside associated with anti-inflammatory and vasoprotective activity.', 'Agastache rugosa is defined by a combination of flavones and aromatic constituents rather than by a single chemical family. Tilianin and acacetin account for much of its anti-inflammatory activity, while rosmarinic acid and the volatile chemotypes (notably estragole or pulegone, depending on origin) contribute to its traditional digestive and antimicrobial uses.'),
  (NULL, 'Asian Mint', 'Agastache rugosa', 'Aerial parts', 'Acacetin', 'Flavonoid', 'Flavone', 'High', 'Marker', 'Principal aglycone contributing to anti-inflammatory and antioxidant effects.', NULL),
  (NULL, 'Asian Mint', 'Agastache rugosa', 'Aerial parts', 'Rosmarinic acid', 'Polyphenol', 'Phenolic acid', 'High', 'Major', 'Major caffeic acid derivative contributing to antioxidant and antiviral activity.', NULL),
  (NULL, 'Asian Mint', 'Agastache rugosa', 'Aerial parts', 'Pulegone', 'Terpenoid', 'Monoterpenoid', 'Low', 'Reported', 'Present in some chemotypes but not consistently characteristic across the species.', NULL),
  (NULL, 'Asian Mint', 'Agastache rugosa', 'Aerial parts', 'Estragole', 'Phenylpropanoid', 'Phenylpropene', 'Moderate', 'Present', 'Aromatic constituent present in common essential oil chemotypes.', NULL),
  (NULL, 'Asian Mint', 'Agastache rugosa', 'Aerial parts', 'Acacetin 7-O-rutinoside', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Present', 'Important glycosylated flavone complementing the acacetin-rich profile.', NULL),
  (225, 'Astragalus', 'Astragalus membranaceus', 'Root', 'Astragaloside IV', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal cycloartane saponin associated with immunomodulatory and adaptogenic activity.', 'Astragalus membranaceus is defined by three complementary constituent groups: cycloartane saponins, isoflavones, and immunomodulatory polysaccharides. Astragaloside IV serves as the principal analytical marker, while the inclusion of astragalan reflects the herb''s well-established immune-supporting activity that cannot be explained by the saponins alone.'),
  (225, 'Astragalus', 'Astragalus membranaceus', 'Root', 'Astragaloside I', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Major cycloartane saponin contributing to the characteristic saponin profile.', NULL),
  (225, 'Astragalus', 'Astragalus membranaceus', 'Root', 'Calycosin', 'Flavonoid', 'Isoflavone', 'High', 'Marker', 'Characteristic isoflavone associated with antioxidant and vascular protective effects.', NULL),
  (225, 'Astragalus', 'Astragalus membranaceus', 'Root', 'Formononetin', 'Flavonoid', 'Isoflavone', 'Moderate', 'Major', 'Major isoflavone contributing to antioxidant and immunomodulatory activity.', NULL),
  (225, 'Astragalus', 'Astragalus membranaceus', 'Root', 'Calycosin-7-O-β-D-glucoside', 'Flavonoid', 'Isoflavone', 'Moderate', 'Present', 'Major glycosylated isoflavone serving as a quality marker in pharmacopoeias.', NULL),
  (225, 'Astragalus', 'Astragalus membranaceus', 'Root', 'Astragalan', 'Polysaccharide', 'Arabinogalactan', 'Moderate', 'Present', 'Immunomodulatory arabinogalactan-type polysaccharide contributing to macrophage and immune activity.', NULL),
  (420, 'Basil', 'Ocimum basilicum', 'Aerial parts', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal aroma constituent contributing to antimicrobial and calming activity in linalool chemotypes.', 'Ocimum basilicum is chemically diverse, with its medicinal properties arising from both volatile aromatic compounds and non-volatile phenolics. The volatile profile varies considerably among chemotypes, while rosmarinic acid provides a consistent anti-inflammatory component across many cultivated varieties.'),
  (420, 'Basil', 'Ocimum basilicum', 'Aerial parts', 'Methyl chavicol (Estragole)', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Marker', 'Major constituent in estragole chemotypes, contributing to the characteristic sweet aroma.', NULL),
  (420, 'Basil', 'Ocimum basilicum', 'Aerial parts', 'Eugenol', 'Phenylpropanoid', 'Phenylpropene', 'Moderate', 'Major', 'Phenylpropanoid associated with antimicrobial and analgesic properties.', NULL),
  (420, 'Basil', 'Ocimum basilicum', 'Aerial parts', 'Rosmarinic acid', 'Polyphenol', 'Phenolic acid', 'High', 'Major', 'Major phenolic constituent contributing to antioxidant and anti-inflammatory activity.', NULL),
  (420, 'Basil', 'Ocimum basilicum', 'Aerial parts', 'Caffeic acid', 'Polyphenol', 'Phenolic acid', 'Low', 'Reported', 'Common phenolic acid serving primarily as a biosynthetic precursor to rosmarinic acid rather than a characteristic constituent.', NULL),
  (420, 'Basil', 'Ocimum basilicum', 'Aerial parts', 'Vicenin-2', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Present', 'Characteristic flavone glycoside contributing to antioxidant activity and used as a quality marker.', NULL),
  (414, 'Benzoin', 'Styrax benzoin', 'Resin', 'Benzoic acid', 'Phenylpropanoid', 'Aromatic acid', 'High', 'Marker', 'Principal aromatic acid contributing to the resin''s preservative and antimicrobial properties.', 'Styrax benzoin is defined almost entirely by its aromatic acids and their esters, which account for its characteristic balsamic aroma, preservative properties, and mild antimicrobial activity. Rather than volatile terpenes, it is these benzoate and cinnamate derivatives that distinguish benzoin resin chemically and therapeutically.'),
  (414, 'Benzoin', 'Styrax benzoin', 'Resin', 'Coniferyl benzoate', 'Phenylpropanoid', 'Aromatic ester', 'High', 'Marker', 'Characteristic benzoate ester contributing to the balsamic aroma and defining the resin''s chemistry.', NULL),
  (414, 'Benzoin', 'Styrax benzoin', 'Resin', 'Cinnamic acid', 'Phenylpropanoid', 'Aromatic acid', 'Moderate', 'Major', 'Aromatic acid contributing to antimicrobial activity and fragrance.', NULL),
  (414, 'Benzoin', 'Styrax benzoin', 'Resin', 'Coniferyl cinnamate', 'Phenylpropanoid', 'Aromatic ester', 'Moderate', 'Major', 'Characteristic cinnamate ester contributing to the resin''s balsamic properties.', NULL),
  (414, 'Benzoin', 'Styrax benzoin', 'Resin', 'Vanillin', 'Phenylpropanoid', 'Aromatic aldehyde', 'Low', 'Reported', 'Minor aromatic aldehyde contributing to the characteristic vanilla-like aroma but not a defining constituent of the resin.', NULL),
  (407, 'Bergamot', 'Citrus × bergamia', 'Peel', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene contributing to the characteristic citrus aroma and digestive properties.', 'Bergamot is chemically distinguished from other citrus fruits by its unusually high content of linalyl acetate and the presence of furanocoumarins, particularly bergamottin and bergapten. Together these constituents explain its characteristic fragrance, calming effects, and clinically important drug-interaction and phototoxic properties.'),
  (407, 'Bergamot', 'Citrus × bergamia', 'Peel', 'Linalyl acetate', 'Terpenoid', 'Monoterpene ester', 'High', 'Marker', 'Defining aroma constituent contributing to the calming fragrance and distinguishing bergamot from most other citrus oils.', NULL),
  (407, 'Bergamot', 'Citrus × bergamia', 'Peel', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major oxygenated monoterpene contributing to anxiolytic, antimicrobial, and aromatic properties.', NULL),
  (407, 'Bergamot', 'Citrus × bergamia', 'Peel', 'Bergamottin', 'Coumarin', 'Furanocoumarin', 'High', 'Marker', 'Characteristic furanocoumarin responsible for CYP3A4 inhibition and phototoxic potential.', NULL),
  (407, 'Bergamot', 'Citrus × bergamia', 'Peel', 'Bergapten', 'Coumarin', 'Furanocoumarin', 'Moderate', 'Major', 'Major furanocoumarin contributing to photobiological activity and serving as an analytical marker.', NULL),
  (407, 'Bergamot', 'Citrus × bergamia', 'Peel', 'Naringin', 'Flavonoid', 'Flavanone glycoside', 'Low', 'Reported', 'Citrus flavanone glycoside reported in bergamot but not among the constituents that define its medicinal chemistry.', NULL),
  (1160, 'Bilberry', 'Vaccinium myrtillus', 'Fruit', 'Delphinidin-3-O-galactoside', 'Flavonoid', 'Anthocyanin', 'High', 'Marker', 'Major anthocyanin contributing to antioxidant activity and vascular protection.', 'Vaccinium myrtillus is defined by its exceptionally rich anthocyanin profile, which accounts for much of its antioxidant activity and traditional use for vascular and ocular health. Flavonols and chlorogenic acid complement this chemistry but are secondary to the anthocyanins that distinguish bilberry from most other medicinal fruits.'),
  (1160, 'Bilberry', 'Vaccinium myrtillus', 'Fruit', 'Cyanidin-3-O-galactoside', 'Flavonoid', 'Anthocyanin', 'High', 'Marker', 'Characteristic anthocyanin supporting capillary integrity and retinal microcirculation.', NULL),
  (1160, 'Bilberry', 'Vaccinium myrtillus', 'Fruit', 'Malvidin-3-O-glucoside', 'Flavonoid', 'Anthocyanin', 'Moderate', 'Major', 'One of the principal anthocyanins contributing to the fruit''s deep pigmentation and antioxidant capacity.', NULL),
  (1160, 'Bilberry', 'Vaccinium myrtillus', 'Fruit', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Flavonol contributing complementary antioxidant and anti-inflammatory activity.', NULL),
  (1160, 'Bilberry', 'Vaccinium myrtillus', 'Fruit', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Major phenolic acid contributing antioxidant activity and complementing the anthocyanin profile.', NULL),
  (1160, 'Bilberry', 'Vaccinium myrtillus', 'Fruit', 'Myricetin', 'Flavonoid', 'Flavonol', 'Low', 'Reported', 'Minor flavonol contributing to the overall antioxidant profile but not characteristic of the medicinal fruit.', NULL)
INSERT INTO herbal.constituent_profiles
  (herb_id, common_name, latin_name, plant_part, constituent, class, subclass, importance, status, notes, editorial_note)
VALUES
  (288, 'Black Walnut', 'Juglans nigra', 'Hull', 'Juglone', 'Polyphenol', 'Naphthoquinone', 'High', 'Marker', 'Characteristic naphthoquinone responsible for much of the herb''s antimicrobial and antifungal activity.', 'Juglans nigra is chemically defined by the combination of juglone and ellagitannins. Juglone explains much of the herb''s traditional antimicrobial use, while the tannins account for its pronounced astringency, making additional minor flavonoids unnecessary for a representative profile.'),
  (288, 'Black Walnut', 'Juglans nigra', 'Hull', 'Hydrojuglone glucoside', 'Glycoside', 'Naphthoquinone glycoside', 'High', 'Major', 'Principal storage form of juglone that is converted upon tissue damage or oxidation.', NULL),
  (288, 'Black Walnut', 'Juglans nigra', 'Hull', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Major', 'Phenolic constituent contributing antioxidant and astringent activity.', NULL),
  (288, 'Black Walnut', 'Juglans nigra', 'Hull', 'Pedunculagin', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Major hydrolyzable tannin contributing astringency and antioxidant effects.', NULL),
  (288, 'Black Walnut', 'Juglans nigra', 'Hull', 'Tellimagrandin I', 'Tannin', 'Ellagitannin', 'Moderate', 'Present', 'Characteristic ellagitannin supporting the hull''s astringent chemistry.', NULL),
  (288, 'Black Walnut', 'Juglans nigra', 'Hull', 'Gallic acid', 'Polyphenol', 'Phenolic acid', 'Low', 'Reported', 'Common phenolic acid associated with hydrolyzable tannins but not characteristic of J. nigra hulls.', NULL),
  (1124, 'Blessed Thistle', 'Cnicus benedictus', 'Aerial parts', 'Cnicin', 'Terpenoid', 'Sesquiterpene lactone', 'High', 'Marker', 'Principal bitter constituent responsible for the herb''s stomachic and bitter tonic activity.', 'Cnicus benedictus is defined primarily by cnicin, a sesquiterpene lactone that accounts for much of the herb''s intense bitterness and traditional use as a digestive bitter. Flavonoids and phenolic acids provide complementary antioxidant activity, but the sesquiterpene lactones remain the defining chemistry of the species.'),
  (1124, 'Blessed Thistle', 'Cnicus benedictus', 'Aerial parts', 'Arctiin', 'Glycoside', 'Lignan glycoside', 'Low', 'Reported', 'Lignan glycoside reported from the species but not consistently recognized as a characteristic constituent of the medicinal herb.', NULL),
  (1124, 'Blessed Thistle', 'Cnicus benedictus', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Flavone contributing antioxidant and anti-inflammatory effects.', NULL),
  (1124, 'Blessed Thistle', 'Cnicus benedictus', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Flavone supporting antioxidant activity and complementing the flavonoid profile.', NULL),
  (1124, 'Blessed Thistle', 'Cnicus benedictus', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Phenolic constituent contributing antioxidant activity and complementing the bitter chemistry.', NULL),
  (983, 'Blue Vervain', 'Verbena hastata', 'Aerial parts', 'Hastatoside', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Characteristic iridoid glycoside contributing to the herb''s bitter tonic and anti-inflammatory properties.', 'Verbena hastata is defined primarily by its iridoid glycosides, which account for much of its bitterness and traditional use as a relaxing nervine and hepatic bitter. Verbascoside provides a complementary phenolic component, while the flavones round out the profile without overshadowing the iridoid chemistry.'),
  (983, 'Blue Vervain', 'Verbena hastata', 'Aerial parts', 'Verbenin', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Principal iridoid glycoside contributing to the herb''s bitter tonic and mild nervine properties.', NULL),
  (983, 'Blue Vervain', 'Verbena hastata', 'Aerial parts', 'Verbascoside', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Major', 'Major phenolic glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (983, 'Blue Vervain', 'Verbena hastata', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Flavone contributing antioxidant and mild anti-inflammatory effects.', NULL),
  (983, 'Blue Vervain', 'Verbena hastata', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Flavone complementing the herb''s antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'Bupleurum', 'Bupleurum chinense', 'Root', 'Saikosaponin a', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal oleanane-type saponin contributing to immunomodulatory, anti-inflammatory, and hepatoprotective activity.', 'Bupleurum chinense is overwhelmingly defined by its saikosaponins, which account for much of the herb''s immunomodulatory, anti-inflammatory, and hepatoprotective activity. The inclusion of saikogenin A captures the characteristic triterpenoid backbone of these glycosides, while flavonoids play only a supporting role in the overall chemistry.'),
  (NULL, 'Bupleurum', 'Bupleurum chinense', 'Root', 'Saikosaponin d', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Major bioactive saikosaponin associated with immunomodulatory and hepatoprotective effects.', NULL),
  (NULL, 'Bupleurum', 'Bupleurum chinense', 'Root', 'Saikosaponin c', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Characteristic saikosaponin complementing the principal saponin profile.', NULL),
  (NULL, 'Bupleurum', 'Bupleurum chinense', 'Root', 'Saikogenin A', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Present', 'Aglycone of saikosaponins representing the characteristic triterpenoid skeleton of the genus.', NULL),
  (NULL, 'Bupleurum', 'Bupleurum chinense', 'Root', 'Saikosaponin b₂', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Bioactive saikosaponin formed during processing and naturally present in the root, complementing saikosaponins a, c, and d in the characteristic saponin profile.', NULL),
  (441, 'Butterwort', 'Pinguicula vulgaris', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Marker', 'Principal flavone contributing antioxidant and anti-inflammatory activity.', 'Pinguicula vulgaris is chemically characterized more by its phenylethanoid glycosides and flavones than by unusual carnivorous-plant metabolites. Although traditionally valued for respiratory conditions, its documented medicinal chemistry is relatively modest, and this profile emphasizes the best-supported constituents while avoiding speculative compounds reported from other Pinguicula species.'),
  (441, 'Butterwort', 'Pinguicula vulgaris', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Flavone complementing the anti-inflammatory flavonoid profile.', NULL),
  (441, 'Butterwort', 'Pinguicula vulgaris', 'Aerial parts', 'Verbascoside', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Marker', 'Characteristic phenylethanoid glycoside contributing antioxidant and antimicrobial activity.', NULL),
  (441, 'Butterwort', 'Pinguicula vulgaris', 'Aerial parts', 'Acteoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Major phenylethanoid glycoside complementing verbascoside and contributing antioxidant and antimicrobial activity.', NULL),
  (441, 'Butterwort', 'Pinguicula vulgaris', 'Aerial parts', 'Ursolic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Present', 'Pentacyclic triterpenoid contributing anti-inflammatory activity.', NULL),
  (579, 'California Spikenard', 'Aralia californica', 'Root', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Marker', 'Principal triterpenoid contributing to the root''s anti-inflammatory and adaptogenic properties.', 'Aralia californica has received far less phytochemical investigation than its Asian relatives. The available evidence indicates that its chemistry is centered on oleanane triterpenoids and their saponins, which likely underlie many of its traditional anti-inflammatory and restorative uses. This intentionally conservative profile avoids importing constituents from better-studied Aralia species such as A. elata or A. cordata.'),
  (579, 'California Spikenard', 'Aralia californica', 'Root', 'Hederagenin', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Major', 'Characteristic triterpenoid sapogenin forming the aglycone of several Aralia saponins.', NULL),
  (579, 'California Spikenard', 'Aralia californica', 'Root', 'Araloside A', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Present', 'Characteristic oleanane-type triterpenoid saponin reported from A. californica, representing the root''s saponin fraction more specifically than a generic glucoside.', NULL),
  (579, 'California Spikenard', 'Aralia californica', 'Root', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Phenolic constituent providing complementary antioxidant activity.', NULL),
  (6, 'Chickpea', 'Cicer arietinum', 'Seed', 'Biochanin A', 'Flavonoid', 'Isoflavone', 'High', 'Marker', 'Principal isoflavone contributing antioxidant and phytoestrogenic activity.', 'Cicer arietinum is unusual among food legumes in possessing a well-developed isoflavone profile, which accounts for much of its antioxidant and phytoestrogenic activity. The inclusion of cicerin preserves the genus'' distinctive flavonoid chemistry, while nutritional constituents such as proteins, carbohydrates, and lipids are intentionally omitted because they do not define the medicinal phytochemistry.'),
  (6, 'Chickpea', 'Cicer arietinum', 'Seed', 'Formononetin', 'Flavonoid', 'Isoflavone', 'Moderate', 'Major', 'Characteristic isoflavone complementing the seed''s phytoestrogenic profile.', NULL),
  (6, 'Chickpea', 'Cicer arietinum', 'Seed', 'Cicerin', 'Flavonoid', 'Flavone', 'Moderate', 'Marker', 'Characteristic flavone first isolated from Cicer species and useful as a chemotaxonomic marker.', NULL),
  (6, 'Chickpea', 'Cicer arietinum', 'Seed', 'Ciceritol', 'Carbohydrate', 'Sugar alcohol', 'Moderate', 'Marker', 'Characteristic methylated cyclitol that serves as a distinctive chemotaxonomic marker and contributes to seed osmoprotection.', NULL),
  (6, 'Chickpea', 'Cicer arietinum', 'Seed', 'Medicarpin', 'Flavonoid', 'Isoflavan', 'Low–Moderate', 'Present', 'Characteristic legume phytoalexin contributing antimicrobial defense chemistry.', NULL),
  (1083, 'Cinnamon', 'Cinnamomum cassia', 'Twig', 'Cinnamaldehyde', 'Phenylpropanoid', 'Aromatic aldehyde', 'High', 'Marker', 'Principal constituent responsible for the twig''s warming, circulatory, and antimicrobial properties.', 'Cinnamomum cassia twig is defined primarily by cinnamaldehyde and related phenylpropanoids, which account for its characteristic warming, circulatory, and antimicrobial actions. Compared with the bark, the twig contains a somewhat different balance of volatile constituents, while coumarin serves as an important species marker and safety consideration.'),
  (1083, 'Cinnamon', 'Cinnamomum cassia', 'Twig', 'Cinnamyl acetate', 'Phenylpropanoid', 'Aromatic ester', 'Moderate', 'Major', 'Aromatic ester contributing to the characteristic fragrance and warming profile.', NULL),
  (1083, 'Cinnamon', 'Cinnamomum cassia', 'Twig', 'trans-Cinnamic acid', 'Phenylpropanoid', 'Aromatic acid', 'Moderate', 'Major', 'Characteristic phenylpropanoid contributing antimicrobial and antioxidant activity.', NULL),
  (1083, 'Cinnamon', 'Cinnamomum cassia', 'Twig', 'Coumarin', 'Coumarin', 'Simple coumarin', 'Moderate', 'Present', 'Naturally occurring coumarin contributing to the species'' safety profile and analytical identification.', NULL),
  (1083, 'Cinnamon', 'Cinnamomum cassia', 'Twig', 'Cinnamyl alcohol', 'Phenylpropanoid', 'Aromatic alcohol', 'Moderate', 'Major', 'Characteristic phenylpropanoid that complements cinnamaldehyde and contributes to the twig''s aromatic and warming profile.', NULL),
  (1083, 'Cinnamon Bark', 'Cinnamomum cassia', 'Bark', 'trans-Cinnamaldehyde', 'Phenylpropanoid', 'Aromatic aldehyde', 'High', 'Marker', 'Principal constituent responsible for the bark''s warming, antimicrobial, and circulatory activity.', 'Cinnamomum cassia bark combines a phenylpropanoid-rich volatile fraction with a significant procyanidin fraction, explaining both its warming aromatic actions and many of its antioxidant and metabolic effects. Separating the bark from the twig preserves an important phytochemical distinction, as the bark contains a much more substantial flavan-3-ol component while retaining cinnamaldehyde as its defining constituent.'),
  (1083, 'Cinnamon Bark', 'Cinnamomum cassia', 'Bark', 'Coumarin', 'Coumarin', 'Simple coumarin', 'High', 'Marker', 'Characteristic constituent important for species identification and safety due to hepatotoxic potential at high intake.', NULL),
  (1083, 'Cinnamon Bark', 'Cinnamomum cassia', 'Bark', 'trans-Cinnamic acid', 'Phenylpropanoid', 'Aromatic acid', 'Moderate', 'Major', 'Characteristic phenylpropanoid contributing antimicrobial and antioxidant activity.', NULL),
  (1083, 'Cinnamon Bark', 'Cinnamomum cassia', 'Bark', 'Cinnamyl acetate', 'Phenylpropanoid', 'Aromatic ester', 'Moderate', 'Major', 'Aromatic ester contributing to the bark''s characteristic fragrance and volatile profile.', NULL),
  (1083, 'Cinnamon Bark', 'Cinnamomum cassia', 'Bark', 'Procyanidin B2', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Representative oligomeric procyanidin contributing antioxidant activity and metabolic effects.', NULL),
  (1083, 'Cinnamon Bark', 'Cinnamomum cassia', 'Bark', 'Procyanidin C1', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Representative oligomeric procyanidin contributing to the bark''s antioxidant and glucose-modulating activity.', NULL),
  (743, 'Clary Sage', 'Salvia sclarea', 'Flowering tops', 'Linalyl acetate', 'Terpenoid', 'Monoterpene ester', 'High', 'Marker', 'Principal constituent responsible for the herb''s characteristic aroma and relaxing properties.', 'Salvia sclarea is distinguished by the combination of linalyl acetate, linalool, and the diterpenoid sclareol, the latter serving as one of the genus'' most distinctive chemotaxonomic markers. While the volatile terpenoids account for much of the herb''s relaxing and aromatic properties, rosmarinic acid provides a characteristic non-volatile anti-inflammatory component shared with many members of the Lamiaceae.'),
  (743, 'Clary Sage', 'Salvia sclarea', 'Flowering tops', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Major oxygenated monoterpene contributing antimicrobial and calming activity.', NULL),
  (743, 'Clary Sage', 'Salvia sclarea', 'Flowering tops', 'Germacrene D', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Characteristic sesquiterpene contributing to the essential oil profile.', NULL),
  (743, 'Clary Sage', 'Salvia sclarea', 'Flowering tops', 'Sclareol', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Characteristic labdane diterpenoid unique to clary sage and important for chemotaxonomic identification.', NULL),
  (743, 'Clary Sage', 'Salvia sclarea', 'Flowering tops', 'Rosmarinic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Major', 'Principal non-volatile phenolic contributing antioxidant and anti-inflammatory activity.', NULL),
  (743, 'Clary Sage', 'Salvia sclarea', 'Flowering tops', 'Caryophyllene oxide', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Oxygenated sesquiterpene contributing to the herb''s antimicrobial activity and characteristic volatile profile.', NULL),
  (28, 'Cleavers', 'Galium aparine', 'Aerial parts', 'Asperuloside', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid glycoside contributing to the herb''s lymphatic and anti-inflammatory activity.', 'Galium aparine is defined primarily by its iridoid glycosides, particularly asperuloside, which account for much of its traditional lymphatic, diuretic, and anti-inflammatory use. Flavonoids and phenolic acids provide complementary antioxidant activity, but the iridoids remain the characteristic chemistry that distinguishes the species.'),
  (28, 'Cleavers', 'Galium aparine', 'Aerial parts', 'Monotropein', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Characteristic iridoid supporting anti-inflammatory and mild diuretic properties.', NULL),
  (28, 'Cleavers', 'Galium aparine', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Major phenolic constituent contributing antioxidant activity.', NULL),
  (28, 'Cleavers', 'Galium aparine', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Flavonol glycoside contributing antioxidant and capillary-supporting activity.', NULL),
  (28, 'Cleavers', 'Galium aparine', 'Aerial parts', 'Asperulosidic acid', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Characteristic iridoid glycoside contributing to the herb''s lymphatic and mild anti-inflammatory activity while complementing asperuloside.', NULL),
  (7, 'Codonopsis', 'Codonopsis pilosula', 'Root', 'Lobetyolin', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Principal polyacetylene glycoside used as a pharmacopoeial marker and associated with immunomodulatory activity.', 'Codonopsis pilosula is defined by three complementary constituent groups: polyacetylenes, immunomodulatory polysaccharides, and a smaller group of characteristic glycosides and alkaloids. Unlike ginseng, whose activity is dominated by triterpenoid saponins, codonopsis derives much of its tonic activity from its polysaccharides and distinctive polyacetylene chemistry, making it a chemically distinct adaptogenic herb.'),
  (7, 'Codonopsis', 'Codonopsis pilosula', 'Root', 'Lobetyol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Characteristic polyacetylene contributing to the root''s distinctive chemistry.', NULL),
  (7, 'Codonopsis', 'Codonopsis pilosula', 'Root', 'Tangshenoside I', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Major', 'Characteristic phenolic glycoside contributing to antioxidant and immunomodulatory activity.', NULL),
  (7, 'Codonopsis', 'Codonopsis pilosula', 'Root', 'Codonopyrrolidium A', 'Alkaloid', 'Pyrrolidine alkaloid', 'Moderate', 'Present', 'Characteristic pyrrolidine alkaloid contributing to the species'' unique alkaloid profile.', NULL),
  (7, 'Codonopsis', 'Codonopsis pilosula', 'Root', 'Syringin', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Major', 'Phenolic glycoside consistently reported from the root and contributing to immunomodulatory and adaptogenic activity.', NULL),
  (7, 'Codonopsis', 'Codonopsis pilosula', 'Root', 'Codonopsis polysaccharide (CPP-1)', 'Polysaccharide', 'Arabinogalactan', 'High', 'Major', 'Well-characterized immunomodulatory polysaccharide representative of the root''s polysaccharide fraction.', NULL),
  (217, 'Coffee', 'Coffea arabica', 'Seed', 'Caffeine', 'Alkaloid', 'Purine alkaloid', 'High', 'Marker', 'Principal methylxanthine responsible for the stimulant, cognitive, and bronchodilatory effects of coffee.', 'Coffea arabica is chemically defined by the combination of caffeine, chlorogenic acids, and its characteristic diterpenes. While caffeine explains the herb''s well-known stimulant effects, chlorogenic acids and diterpenes contribute substantially to its antioxidant, metabolic, and hepatoprotective properties, illustrating that coffee''s pharmacology extends well beyond a single alkaloid.'),
  (217, 'Coffee', 'Coffea arabica', 'Seed', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'High', 'Marker', 'Major phenolic constituent contributing antioxidant activity and influencing glucose metabolism.', NULL),
  (217, 'Coffee', 'Coffea arabica', 'Seed', 'Trigonelline', 'Alkaloid', 'Pyridine alkaloid', 'High', 'Major', 'Characteristic alkaloid that contributes to neuroprotective activity and forms aroma compounds during roasting.', NULL),
  (217, 'Coffee', 'Coffea arabica', 'Seed', 'Cafestol', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic diterpene associated with lipid metabolism and the biological activity of unfiltered coffee.', NULL),
  (217, 'Coffee', 'Coffea arabica', 'Seed', 'Kahweol', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Coffee-specific diterpene contributing antioxidant and hepatoprotective effects.', NULL),
  (217, 'Coffee', 'Coffea arabica', 'Seed', 'Caffeic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Present', 'Bioactive phenolic released from chlorogenic acids during metabolism and roasting, contributing complementary antioxidant activity.', NULL),
  (162, 'Coleus', 'Coleus forskohlii (Plectranthus barbatus)', 'Root', 'Forskolin', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Principal labdane diterpenoid responsible for adenylate cyclase activation and elevation of intracellular cAMP.', 'Coleus forskohlii is one of the clearest examples of a medicinal plant defined almost entirely by a single constituent family. Its labdane diterpenoids, particularly forskolin, account for virtually all of its recognized pharmacological activity through activation of adenylate cyclase and increased intracellular cAMP. Additional phenolics and flavonoids have been intentionally omitted because they contribute little to the herb''s chemotaxonomic or therapeutic identity.'),
  (162, 'Coleus', 'Coleus forskohlii (Plectranthus barbatus)', 'Root', '1-Deoxyforskolin', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Naturally occurring forskolin analogue contributing to the characteristic labdane diterpenoid profile.', NULL),
  (162, 'Coleus', 'Coleus forskohlii (Plectranthus barbatus)', 'Root', '9-Deoxyforskolin', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Major labdane diterpenoid accompanying forskolin in the medicinal root.', NULL),
  (162, 'Coleus', 'Coleus forskohlii (Plectranthus barbatus)', 'Root', '1,9-Dideoxyforskolin', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Present', 'Characteristic forskolin analogue supporting the species-specific diterpenoid chemistry.', NULL),
  (162, 'Coleus', 'Coleus forskohlii (Plectranthus barbatus)', 'Root', 'Coleonol', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Naturally occurring labdane diterpenoid (historically synonymous with forskolin) representing the characteristic diterpenoid chemistry of the root.', NULL),
  (187, 'Condurango', 'Marsdenia cundurango', 'Bark', 'Condurangin', 'Glycoside', 'Steroidal glycoside', 'High', 'Marker', 'Principal bitter steroidal glycoside responsible for the bark''s traditional stomachic and digestive bitter activity.', 'Marsdenia cundurango is defined almost entirely by its condurango steroidal glycosides, which account for its intense bitterness and traditional use as a gastric tonic. The steroidal aglycones are included because they illustrate the characteristic scaffold underlying this distinctive glycoside family, while unrelated phenolics and flavonoids contribute little to the medicinal identity of the bark.'),
  (187, 'Condurango', 'Marsdenia cundurango', 'Bark', 'Condurangogenin A', 'Steroid', 'Steroidal sapogenin', 'High', 'Major', 'Principal steroidal aglycone forming the backbone of the condurango glycosides.', NULL),
  (187, 'Condurango', 'Marsdenia cundurango', 'Bark', 'Condurangogenin C', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Major', 'Characteristic steroidal aglycone complementing the major glycoside fraction.', NULL),
  (187, 'Condurango', 'Marsdenia cundurango', 'Bark', 'Condurangoside A', 'Glycoside', 'Steroidal glycoside', 'Moderate', 'Major', 'Representative steroidal glycoside contributing to the bark''s bitter profile.', NULL),
  (187, 'Condurango', 'Marsdenia cundurango', 'Bark', 'Condurangoside B', 'Glycoside', 'Steroidal glycoside', 'Moderate', 'Major', 'Well-characterized steroidal glycoside representing the principal bitter glycoside complex of the bark.', NULL),
  (179, 'Couch Grass', 'Elymus repens (Elytrigia repens, Agropyron repens)', 'Rhizome', 'Triticin', 'Polysaccharide', 'Fructan', 'High', 'Marker', 'Principal storage fructan associated with the herb''s traditional demulcent and nutritive properties.', 'Couch grass is chemically unusual among medicinal rhizomes in being defined by the combination of triticin, a storage fructan, and agropyrene, a characteristic antimicrobial polyacetylene. The remaining phenolic constituents contribute supportive antioxidant activity, but the herb''s traditional demulcent and urinary actions are largely explained by its fructan-rich rhizome together with its distinctive polyacetylene chemistry.'),
  (179, 'Couch Grass', 'Elymus repens (Elytrigia repens, Agropyron repens)', 'Rhizome', 'Agropyrene', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Characteristic antimicrobial polyacetylene historically regarded as one of the defining constituents of the rhizome.', NULL),
  (179, 'Couch Grass', 'Elymus repens (Elytrigia repens, Agropyron repens)', 'Rhizome', 'p-Hydroxybenzaldehyde', 'Phenylpropanoid', 'Aromatic aldehyde', 'Moderate', 'Major', 'Characteristic aromatic aldehyde consistently reported from the rhizome and contributing to its aromatic profile.', NULL),
  (179, 'Couch Grass', 'Elymus repens (Elytrigia repens, Agropyron repens)', 'Rhizome', 'p-Hydroxybenzoic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Present', 'Phenolic acid contributing complementary antioxidant activity.', NULL),
  (179, 'Couch Grass', 'Elymus repens (Elytrigia repens, Agropyron repens)', 'Rhizome', 'Ferulic acid', 'Polyphenol', 'Hydroxycinnamic acid', 'Moderate', 'Present', 'Hydroxycinnamic acid contributing antioxidant activity and characteristic grass phenolic chemistry.', NULL),
  (197, 'Cowslip', 'Primula veris', 'Flowers', 'Primverin', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Characteristic phenolic glycoside contributing to the mild expectorant activity and serving as a quality marker.', 'Primula veris flowers are defined by the characteristic primverin/primulaverin glycosides, which distinguish the genus and contribute to its traditional expectorant use. Flavonols provide complementary antioxidant activity, while the triterpenoid saponins that dominate the medicinal root are intentionally omitted because this profile represents the flowers, whose chemistry differs substantially.'),
  (197, 'Cowslip', 'Primula veris', 'Flowers', 'Primulaverin', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Companion phenolic glycoside characteristic of Primula flowers and roots.', NULL),
  (197, 'Cowslip', 'Primula veris', 'Flowers', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Major flavonoid contributing antioxidant and capillary-supporting activity.', NULL),
  (197, 'Cowslip', 'Primula veris', 'Flowers', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Characteristic flavonol complementing the flower''s antioxidant profile.', NULL),
  (197, 'Cowslip', 'Primula veris', 'Flowers', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Major flavonol glycoside contributing antioxidant activity and characteristic of the flower flavonoid fraction.', NULL),
  (1212, 'Cranberry', 'Vaccinium macrocarpon', 'Fruit', 'Procyanidin A2', 'Flavonoid', 'Flavan-3-ol', 'High', 'Marker', 'Characteristic A-type proanthocyanidin responsible for anti-adhesion activity against uropathogenic E. coli.', 'Cranberry is chemically distinguished by its A-type proanthocyanidins, particularly procyanidin A2, which account for its well-established anti-adhesion effects in urinary tract health. Anthocyanins and ursolic acid contribute antioxidant and anti-inflammatory activity, but the unique A-type proanthocyanidins remain the defining chemistry that separates cranberry from most other Vaccinium fruits.'),
  (1212, 'Cranberry', 'Vaccinium macrocarpon', 'Fruit', 'Cyanidin-3-O-galactoside', 'Flavonoid', 'Anthocyanin', 'High', 'Major', 'Principal anthocyanin contributing antioxidant activity and the fruit''s characteristic pigmentation.', NULL),
  (1212, 'Cranberry', 'Vaccinium macrocarpon', 'Fruit', 'Peonidin-3-O-galactoside', 'Flavonoid', 'Anthocyanin', 'Moderate', 'Major', 'Major anthocyanin complementing the characteristic anthocyanin profile.', NULL),
  (1212, 'Cranberry', 'Vaccinium macrocarpon', 'Fruit', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Flavonol contributing complementary antioxidant and anti-inflammatory activity.', NULL),
  (1212, 'Cranberry', 'Vaccinium macrocarpon', 'Fruit', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Characteristic phenolic acid supporting the fruit''s antioxidant profile.', NULL),
  (1212, 'Cranberry', 'Vaccinium macrocarpon', 'Fruit', 'Ursolic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Major', 'Major triterpenoid concentrated in the fruit skin, contributing anti-inflammatory and antimicrobial activity.', NULL),
  (570, 'Cypress', 'Cupressus sempervirens', 'Leaf', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene contributing to the herb''s astringent, antimicrobial, and respiratory actions.', 'Cupressus sempervirens is unusual in combining a monoterpene-rich volatile fraction with a distinctive group of biflavonoids. The monoterpenes account for much of the herb''s traditional venotonic, astringent, and respiratory activity, while the biflavonoids provide chemotaxonomic distinction within the Cupressaceae and contribute complementary antioxidant effects.'),
  (570, 'Cypress', 'Cupressus sempervirens', 'Leaf', 'δ-3-Carene', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Characteristic monoterpene contributing to the distinctive aroma and antimicrobial activity.', NULL),
  (570, 'Cypress', 'Cupressus sempervirens', 'Leaf', 'Sabinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene contributing to the herb''s aromatic, antimicrobial, and circulatory properties.', NULL),
  (570, 'Cypress', 'Cupressus sempervirens', 'Leaf', 'Cupressuflavone', 'Flavonoid', 'Biflavonoid', 'High', 'Marker', 'Characteristic biflavonoid serving as an important chemotaxonomic marker and contributing antioxidant activity.', NULL),
  (570, 'Cypress', 'Cupressus sempervirens', 'Leaf', 'Amentoflavone', 'Flavonoid', 'Biflavonoid', 'Moderate', 'Major', 'Biflavonoid contributing anti-inflammatory and antioxidant activity.', NULL),
  (570, 'Cypress', 'Cupressus sempervirens', 'Leaf', 'Hinokiflavone', 'Flavonoid', 'Biflavonoid', 'Moderate', 'Present', 'Characteristic Cupressaceae biflavonoid complementing the species'' phenolic profile.', NULL),
  (122, 'Dandelion Root', 'Taraxacum officinale', 'Root', 'Taraxasterol', 'Terpenoid', 'Pentacyclic triterpenoid', 'High', 'Marker', 'Principal triterpenoid contributing to anti-inflammatory activity and serving as a characteristic marker of the root.', 'Taraxacum officinale root is defined by the interplay of sesquiterpene lactones, triterpenoids, and fructans. While the sesquiterpene lactones account for much of the herb''s traditional bitter tonic activity, the abundant inulin and characteristic triterpenoids distinguish the root chemically from the leaf and contribute to its digestive and metabolic actions.'),
  (122, 'Dandelion Root', 'Taraxacum officinale', 'Root', 'Taraxerol', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Major', 'Characteristic triterpenoid complementing the root''s anti-inflammatory profile.', NULL),
  (122, 'Dandelion Root', 'Taraxacum officinale', 'Root', 'Chicoric acid', 'Polyphenol', 'Phenylpropanoid ester', 'High', 'Major', 'Major caffeic acid derivative contributing antioxidant and immunomodulatory activity.', NULL),
  (122, 'Dandelion Root', 'Taraxacum officinale', 'Root', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Principal hydroxycinnamate contributing antioxidant and hepatoprotective activity.', NULL),
  (122, 'Dandelion Root', 'Taraxacum officinale', 'Root', 'Inulin', 'Polysaccharide', 'Fructan', 'High', 'Marker', 'Major storage polysaccharide supporting prebiotic activity and digestive function.', NULL),
  (122, 'Dandelion Root', 'Taraxacum officinale', 'Root', 'Taraxinic acid β-D-glucopyranosyl ester', 'Glycoside', 'Sesquiterpenoid glycoside', 'High', 'Marker', 'Principal bitter sesquiterpene glycoside responsible for much of the root''s digestive bitter activity and widely used as an analytical marker.', NULL),
  (7, 'Dang Shen', 'Codonopsis pilosula', 'Root', 'Lobetyolin', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Principal polyacetylene glycoside and pharmacopoeial marker contributing to immunomodulatory activity.', 'Codonopsis pilosula derives its tonic activity from a distinctive combination of polyacetylenes, polysaccharides, and phenolic glycosides, rather than the triterpenoid saponins that define true ginseng (Panax spp.). This chemistry explains why Dang Shen occupies a similar therapeutic niche while remaining phytochemically distinct.'),
  (7, 'Dang Shen', 'Codonopsis pilosula', 'Root', 'Lobetyol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Characteristic polyacetylene contributing to the root''s distinctive chemistry.', NULL),
  (7, 'Dang Shen', 'Codonopsis pilosula', 'Root', 'Syringin', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Major', 'Phenolic glycoside contributing adaptogenic and immunomodulatory activity.', NULL),
  (7, 'Dang Shen', 'Codonopsis pilosula', 'Root', 'Tangshenoside I', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Major', 'Characteristic phenolic glycoside supporting antioxidant and tonic effects.', NULL),
  (7, 'Dang Shen', 'Codonopsis pilosula', 'Root', 'Codonopyrrolidium A', 'Alkaloid', 'Pyrrolidine alkaloid', 'Moderate', 'Present', 'Characteristic pyrrolidine alkaloid contributing to the distinctive alkaloid profile of Codonopsis.', NULL),
  (7, 'Dang Shen', 'Codonopsis pilosula', 'Root', 'Codonopsis polysaccharide (CPP-1)', 'Polysaccharide', 'Arabinogalactan', 'High', 'Major', 'Well-characterized polysaccharide contributing to the herb''s immunomodulatory and tonic activity.', NULL),
  (80, 'Devil''s Claw', 'Harpagophytum procumbens', 'Secondary root', 'Harpagoside', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid glycoside responsible for the herb''s anti-inflammatory activity and primary pharmacopoeial marker.', 'Harpagophytum procumbens is defined primarily by its iridoid glycosides, especially harpagoside, which account for much of its anti-inflammatory and analgesic activity. The accompanying phenylethanoid glycosides broaden the herb''s antioxidant profile, but the iridoids remain the defining chemistry and the basis for pharmacopoeial standardization.'),
  (80, 'Devil''s Claw', 'Harpagophytum procumbens', 'Secondary root', 'Harpagide', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Characteristic iridoid glycoside complementing harpagoside in the anti-inflammatory profile.', NULL),
  (80, 'Devil''s Claw', 'Harpagophytum procumbens', 'Secondary root', 'Procumbide', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Characteristic iridoid glycoside contributing to the species'' distinctive chemistry.', NULL),
  (80, 'Devil''s Claw', 'Harpagophytum procumbens', 'Secondary root', 'Acteoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Major phenylethanoid glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (80, 'Devil''s Claw', 'Harpagophytum procumbens', 'Secondary root', 'Isoacteoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Present', 'Phenylethanoid glycoside complementing acteoside within the phenolic fraction.', NULL),
  (80, 'Devil''s Claw', 'Harpagophytum procumbens', 'Secondary root', '8-p-Coumaroylharpagide', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Acylated iridoid glycoside characteristic of Devil''s Claw that complements the principal harpagosides and contributes to the herb''s bitter chemistry.', NULL),
  (591, 'Devil''s Club', 'Oplopanax horridus', 'Root bark', 'Falcarinol', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Principal polyacetylene contributing antimicrobial, antifungal, and cytotoxic activity.', 'Oplopanax horridus is one of the few medicinal members of the Araliaceae whose chemistry is defined by polyacetylenes rather than triterpenoid saponins. These compounds account for much of the herb''s traditional antimicrobial, adaptogenic, and immunomodulatory activity, making Devil''s Club chemically distinct from Asian ginseng and other tonic members of the family.'),
  (591, 'Devil''s Club', 'Oplopanax horridus', 'Root bark', 'Falcarindiol', 'Polyacetylene', 'Polyacetylene', 'High', 'Marker', 'Major bioactive polyacetylene associated with antimicrobial and anti-inflammatory effects.', NULL),
  (591, 'Devil''s Club', 'Oplopanax horridus', 'Root bark', 'Oplopantriol A', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Characteristic Oplopanax polyacetylene contributing to the species'' distinctive chemistry.', NULL),
  (591, 'Devil''s Club', 'Oplopanax horridus', 'Root bark', 'Oplopantriol B', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Companion polyacetylene characteristic of Oplopanax horridus.', NULL),
  (591, 'Devil''s Club', 'Oplopanax horridus', 'Root bark', 'Oplopandiol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Present', 'Species-specific polyacetylene supporting the characteristic polyacetylene profile.', NULL),
  (64, 'Dill', 'Anethum graveolens', 'Seed', 'Carvone', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene responsible for the seed''s characteristic aroma and carminative activity.', 'Anethum graveolens seed is defined by a carvone-rich volatile profile, which accounts for its well-established carminative, antispasmodic, and digestive actions. Phenylpropenes and minor coumarins complement the monoterpenes, but carvone and limonene remain the principal constituents distinguishing dill seed from most other aromatic Apiaceae.'),
  (64, 'Dill', 'Anethum graveolens', 'Seed', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major monoterpene complementing carvone and contributing digestive and antimicrobial activity.', NULL),
  (64, 'Dill', 'Anethum graveolens', 'Seed', 'Dillapiole', 'Phenylpropanoid', 'Phenylpropene', 'Moderate', 'Major', 'Characteristic phenylpropanoid contributing to the seed''s distinctive aromatic profile.', NULL),
  (64, 'Dill', 'Anethum graveolens', 'Seed', 'Apiol', 'Phenylpropanoid', 'Phenylpropene', 'Moderate', 'Present', 'Aromatic phenylpropanoid contributing to the seed''s carminative and antimicrobial properties.', NULL),
  (64, 'Dill', 'Anethum graveolens', 'Seed', 'α-Phellandrene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene contributing to the seed''s aromatic, carminative, and antimicrobial properties.', NULL),
  (64, 'Dill', 'Anethum graveolens', 'Seed', 'Umbelliferone', 'Coumarin', 'Simple coumarin', 'Moderate', 'Present', 'Characteristic coumarin contributing antioxidant activity and reflecting Apiaceae chemistry.', NULL),
  (412, 'Dwarf Pine', 'Pinus mugo', 'Needle', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene contributing to the characteristic respiratory, antimicrobial, and balsamic properties.', 'Pinus mugo is defined primarily by its monoterpene-rich volatile chemistry, particularly α-pinene, β-pinene, and bornyl acetate, which explain its traditional respiratory, antimicrobial, and balsamic uses. Although the needles contain polyphenols, they play a secondary role compared with the characteristic terpene profile that distinguishes dwarf pine.'),
  (412, 'Dwarf Pine', 'Pinus mugo', 'Needle', 'β-Pinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major monoterpene complementing α-pinene in the characteristic volatile profile.', NULL),
  (412, 'Dwarf Pine', 'Pinus mugo', 'Needle', 'δ-3-Carene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene contributing to the resinous aroma and antimicrobial activity.', NULL),
  (412, 'Dwarf Pine', 'Pinus mugo', 'Needle', 'Bornyl acetate', 'Terpenoid', 'Monoterpene ester', 'Moderate', 'Major', 'Oxygenated monoterpene contributing to the balsamic aroma and mild anti-inflammatory activity.', NULL),
  (412, 'Dwarf Pine', 'Pinus mugo', 'Needle', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Monoterpene contributing complementary antimicrobial and aromatic properties.', NULL),
  (412, 'Dwarf Pine', 'Pinus mugo', 'Needle', 'β-Phellandrene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene contributing to the fresh conifer aroma and antimicrobial properties of the needles.', NULL),
  (57, 'Elderflower', 'Sambucus nigra', 'Flower', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'High', 'Marker', 'Principal flavonoid contributing antioxidant activity and capillary support.', 'Sambucus nigra flowers are chemically distinct from the berries, being defined primarily by flavonol glycosides and phenolic acids rather than anthocyanins. These constituents account for much of elderflower''s traditional diaphoretic and upper respiratory use, while the berries derive their medicinal activity largely from a different anthocyanin-rich chemistry.'),
  (57, 'Elderflower', 'Sambucus nigra', 'Flower', 'Isoquercitrin', 'Flavonoid', 'Flavonol glycoside', 'High', 'Major', 'Major flavonol glycoside contributing anti-inflammatory and antioxidant activity.', NULL),
  (57, 'Elderflower', 'Sambucus nigra', 'Flower', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Principal phenolic acid contributing antioxidant activity.', NULL),
  (57, 'Elderflower', 'Sambucus nigra', 'Flower', 'Caffeic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Present', 'Hydroxycinnamic acid complementing the flower''s antioxidant profile.', NULL),
  (57, 'Elderflower', 'Sambucus nigra', 'Flower', 'Ursolic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Present', 'Pentacyclic triterpenoid contributing anti-inflammatory activity.', NULL),
  (57, 'Elderflower', 'Sambucus nigra', 'Flower', 'Isochlorogenic acid A', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Dicaffeoylquinic acid contributing antioxidant activity and complementing the characteristic phenolic acid profile.', NULL),
  (191, 'English Daisy', 'Bellis perennis', 'Flowering aerial parts', 'Bellissaponin BA1', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal oleanane-type saponin contributing to the herb''s anti-inflammatory and vulnerary activity.', 'Bellis perennis is chemically defined by its oleanane triterpenoid saponins, which account for much of its traditional vulnerary and anti-inflammatory use. Flavones and caffeoylquinic acids provide complementary antioxidant activity, but the bellissaponins remain the most distinctive constituents of the species.'),
  (191, 'English Daisy', 'Bellis perennis', 'Flowering aerial parts', 'Bellissaponin BS2', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Characteristic oleanane-type triterpenoid saponin complementing bellissaponin BA1 within the species-specific saponin profile.', NULL),
  (191, 'English Daisy', 'Bellis perennis', 'Flowering aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Flavone contributing antioxidant and anti-inflammatory activity.', NULL),
  (191, 'English Daisy', 'Bellis perennis', 'Flowering aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Characteristic flavone supporting antioxidant and wound-healing activity.', NULL),
  (191, 'English Daisy', 'Bellis perennis', 'Flowering aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Phenolic constituent contributing antioxidant activity.', NULL),
  (191, 'English Daisy', 'Bellis perennis', 'Flowering aerial parts', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Present', 'Triterpenoid aglycone representing the characteristic saponin scaffold of the species.', NULL),
  (1139, 'Evening Primrose', 'Oenothera biennis', 'Seed', 'γ-Linolenic acid (GLA)', 'Lipid', 'Polyunsaturated fatty acid', 'High', 'Marker', 'Characteristic omega-6 fatty acid associated with anti-inflammatory and skin-supportive activity.', 'Oenothera biennis is unusual in combining a polyunsaturated fatty acid-rich seed oil with the characteristic ellagitannin oenothein B. While the fatty acids explain the herb''s widespread use for inflammatory skin conditions, oenothein B contributes a distinct immunomodulatory component that differentiates evening primrose from most medicinal seed oils.'),
  (1139, 'Evening Primrose', 'Oenothera biennis', 'Seed', 'Linoleic acid', 'Lipid', 'Polyunsaturated fatty acid', 'High', 'Major', 'Principal fatty acid of the seed oil serving as the biosynthetic precursor of GLA.', NULL),
  (1139, 'Evening Primrose', 'Oenothera biennis', 'Seed', 'Oenothein B', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Characteristic macrocyclic ellagitannin contributing antioxidant and immunomodulatory activity.', NULL),
  (1139, 'Evening Primrose', 'Oenothera biennis', 'Seed', 'β-Sitosterol', 'Sterol', 'Phytosterol', 'Moderate', 'Major', 'Principal phytosterol contributing complementary anti-inflammatory activity.', NULL),
  (1139, 'Evening Primrose', 'Oenothera biennis', 'Seed', 'Campesterol', 'Sterol', 'Phytosterol', 'Moderate', 'Present', 'Characteristic phytosterol supporting the seed''s sterol profile.', NULL),
  (1139, 'Evening Primrose', 'Oenothera biennis', 'Seed', 'Oleic acid', 'Lipid', 'Fatty acid', 'Moderate', 'Major', 'Monounsaturated fatty acid that complements the characteristic polyunsaturated fatty acid profile and contributes to the seed oil''s stability.', NULL),
  (121, 'Feverfew', 'Tanacetum parthenium', 'Leaf & flowering tops', 'Parthenolide', 'Terpenoid', 'Sesquiterpene lactone', 'High', 'Marker', 'Principal sesquiterpene lactone responsible for much of the herb''s antimigraine and anti-inflammatory activity and the primary pharmacopoeial marker.', 'Tanacetum parthenium is one of the clearest examples of a medicinal herb defined by its sesquiterpene lactones, particularly parthenolide, which account for much of its antimigraine, anti-inflammatory, and NF-κB-modulating activity. The accompanying flavonoids complement the herb''s antioxidant profile, but the sesquiterpene lactones remain the defining chemistry that distinguishes feverfew from most other members of the Asteraceae.'),
  (121, 'Feverfew', 'Tanacetum parthenium', 'Leaf & flowering tops', 'Santamarine', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Major', 'Characteristic sesquiterpene lactone complementing the parthenolide-rich profile.', NULL),
  (121, 'Feverfew', 'Tanacetum parthenium', 'Leaf & flowering tops', 'Artecanin', 'Terpenoid', 'Sesquiterpene lactone', 'Moderate', 'Major', 'Germacranolide sesquiterpene lactone characteristic of Tanacetum species.', NULL),
  (121, 'Feverfew', 'Tanacetum parthenium', 'Leaf & flowering tops', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Flavone contributing complementary antioxidant and anti-inflammatory activity.', NULL),
  (121, 'Feverfew', 'Tanacetum parthenium', 'Leaf & flowering tops', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Flavone supporting antioxidant activity and complementing the sesquiterpene lactone fraction.', NULL),
  (121, 'Feverfew', 'Tanacetum parthenium', 'Leaf & flowering tops', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Phenolic constituent providing complementary antioxidant activity.', NULL),
  (24, 'Fringetree', 'Chionanthus virginicus', 'Root bark', 'Oleuropein', 'Glycoside', 'Secoiridoid glycoside', 'High', 'Marker', 'Principal secoiridoid glycoside contributing bitter, cholagogue, and hepatobiliary activity.', 'Chionanthus virginicus root bark is best represented by secoiridoid glycosides and lignan glycosides, rather than the older, poorly defined term “chionanthin.” The secoiridoids help explain its traditional bitter, cholagogue, and liver-gallbladder uses, while the lignans provide a complementary anti-inflammatory and antioxidant fraction.'),
  (24, 'Fringetree', 'Chionanthus virginicus', 'Root bark', 'Ligustroside', 'Glycoside', 'Secoiridoid glycoside', 'High', 'Major', 'Characteristic secoiridoid glycoside supporting the bitter and hepatobiliary profile.', NULL),
  (24, 'Fringetree', 'Chionanthus virginicus', 'Root bark', 'Excelside B', 'Glycoside', 'Secoiridoid glycoside', 'Moderate', 'Major', 'Secoiridoid glycoside contributing to the species-specific quality-control profile.', NULL),
  (24, 'Fringetree', 'Chionanthus virginicus', 'Root bark', 'Phillyrin', 'Glycoside', 'Lignan glycoside', 'Moderate', 'Major', 'Lignan glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (24, 'Fringetree', 'Chionanthus virginicus', 'Root bark', 'Demethyloleuropein', 'Glycoside', 'Secoiridoid glycoside', 'Moderate', 'Major', 'Characteristic secoiridoid complementing oleuropein and contributing to the root bark''s bitter cholagogue chemistry.', NULL),
  (27, 'Fumitory', 'Fumaria officinalis', 'Aerial parts', 'Protopine', 'Alkaloid', 'Protopine alkaloid', 'High', 'Marker', 'Principal isoquinoline alkaloid contributing to the herb''s antispasmodic and hepatobiliary activity.', 'Fumaria officinalis is defined overwhelmingly by its isoquinoline alkaloids, particularly protopine, which account for much of its traditional hepatobiliary, antispasmodic, and smooth muscle-modulating activity. Flavonoids are present but play a distinctly secondary role, making the alkaloid profile the defining feature of the species.'),
  (27, 'Fumitory', 'Fumaria officinalis', 'Aerial parts', 'Fumaritine', 'Alkaloid', 'Protopine alkaloid', 'Moderate', 'Major', 'Characteristic isoquinoline alkaloid contributing to the species'' antispasmodic and hepatobiliary activity.', NULL),
  (27, 'Fumitory', 'Fumaria officinalis', 'Aerial parts', 'Stylopine', 'Alkaloid', 'Protopine alkaloid', 'Moderate', 'Major', 'Characteristic protoberberine-related alkaloid contributing to the species'' distinctive alkaloid chemistry.', NULL),
  (27, 'Fumitory', 'Fumaria officinalis', 'Aerial parts', 'Fumariline', 'Alkaloid', 'Benzylisoquinoline alkaloid', 'Moderate', 'Major', 'Species-characteristic isoquinoline alkaloid contributing to the chemotaxonomic profile of Fumaria.', NULL),
  (27, 'Fumitory', 'Fumaria officinalis', 'Aerial parts', 'Fumaricine', 'Alkaloid', 'Protopine alkaloid', 'Moderate', 'Present', 'Characteristic alkaloid complementing the dominant protopine fraction.', NULL),
  (27, 'Fumitory', 'Fumaria officinalis', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Flavonoid providing complementary antioxidant activity to the alkaloid-dominated profile.', NULL),
  (1122, 'Goat''s Rue', 'Galega officinalis', 'Aerial parts', 'Galegine', 'Alkaloid', 'Guanidine alkaloid', 'High', 'Marker', 'Principal guanidine alkaloid responsible for the herb''s antihyperglycemic activity and the historical lead compound for biguanide drug development.', 'Galega officinalis is chemically defined by its guanidine alkaloids, particularly galegine, which explain its historical use for glycemic regulation and ultimately inspired the development of the biguanide class of antidiabetic drugs. Flavonoids provide complementary antioxidant activity, but the guanidine alkaloids remain the defining constituents of the species.'),
  (1122, 'Goat''s Rue', 'Galega officinalis', 'Aerial parts', 'Hydroxygalegine', 'Alkaloid', 'Guanidine alkaloid', 'Moderate', 'Major', 'Characteristic guanidine alkaloid complementing galegine within the species'' hypoglycemic alkaloid profile.', NULL),
  (1122, 'Goat''s Rue', 'Galega officinalis', 'Aerial parts', 'Galuteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Characteristic flavone contributing antioxidant and anti-inflammatory activity.', NULL),
  (1122, 'Goat''s Rue', 'Galega officinalis', 'Aerial parts', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Flavonol contributing complementary antioxidant activity.', NULL),
  (1122, 'Goat''s Rue', 'Galega officinalis', 'Aerial parts', '4-Hydroxygalegine', 'Alkaloid', 'Guanidine alkaloid', 'Moderate', 'Major', 'Naturally occurring guanidine alkaloid complementing galegine and contributing to the species'' characteristic hypoglycemic chemistry.', NULL),
  (1122, 'Goat''s Rue', 'Galega officinalis', 'Aerial parts', 'Galegoside', 'Glycoside', 'Flavone glycoside', 'Moderate', 'Present', 'Characteristic flavonoid glycoside contributing to the aerial parts'' antioxidant chemistry.', NULL),
  (58, 'Goldenrod', 'Solidago virgaurea', 'Aerial parts', 'Leiocarposide', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Principal phenolic glycoside and pharmacopoeial marker associated with diuretic and anti-inflammatory activity.', 'Solidago virgaurea is defined primarily by its flavonoids and phenolic glycosides, particularly leiocarposide, which has become an important analytical marker for the species. Together these constituents explain much of goldenrod''s traditional diuretic, urinary tract, and anti-inflammatory activity, while avoiding reliance on volatile constituents that are comparatively minor.'),
  (58, 'Goldenrod', 'Solidago virgaurea', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'High', 'Major', 'Major flavonol contributing antioxidant, anti-inflammatory, and capillary-protective activity.', NULL),
  (58, 'Goldenrod', 'Solidago virgaurea', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonol glycoside complementing the herb''s vascular and antioxidant profile.', NULL),
  (58, 'Goldenrod', 'Solidago virgaurea', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Principal hydroxycinnamate contributing antioxidant and urinary tract activity.', NULL),
  (58, 'Goldenrod', 'Solidago virgaurea', 'Aerial parts', 'Virgaureoside A', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Present', 'Characteristic phenolic glycoside supporting the species-specific phenolic profile.', NULL),
  (58, 'Goldenrod', 'Solidago virgaurea', 'Aerial parts', 'Virgaureoside B', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Major', 'Characteristic phenolic glycoside complementing leiocarposide and contributing to the herb''s urinary tract and anti-inflammatory activity.', NULL),
  (NULL, 'Grindelia', 'Grindelia squarrosa', 'Flowering tops', 'Grindelic acid', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Principal diterpenoid acid contributing to the herb''s expectorant, anti-inflammatory, and antimicrobial activity.', 'Grindelia squarrosa is chemically defined by its grindelic acid diterpenes, which account for much of the herb''s traditional use as an expectorant and respiratory anti-inflammatory. Flavonoids provide complementary antioxidant activity, but the resinous diterpenoid acids distinguish Grindelia from most other medicinal members of the Asteraceae.'),
  (NULL, 'Grindelia', 'Grindelia squarrosa', 'Flowering tops', '6-O-Benzoylgrindelic acid', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic grindelic acid derivative supporting the species-specific diterpenoid profile.', NULL),
  (NULL, 'Grindelia', 'Grindelia squarrosa', 'Flowering tops', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Major', 'Major flavonol contributing antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'Grindelia', 'Grindelia squarrosa', 'Flowering tops', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Flavone complementing the herb''s anti-inflammatory profile.', NULL),
  (NULL, 'Grindelia', 'Grindelia squarrosa', 'Flowering tops', '6-O-Acetylgrindelic acid', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic grindelic acid derivative contributing to the resin acid fraction that defines the species.', NULL),
  (NULL, 'Grindelia', 'Grindelia squarrosa', 'Flowering tops', 'Methyl grindelate', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Present', 'Characteristic grindelic acid derivative contributing to the distinctive resin acid chemistry.', NULL),
  (218, 'Guarana', 'Paullinia cupana', 'Seed', 'Caffeine', 'Alkaloid', 'Purine alkaloid', 'High', 'Marker', 'Principal methylxanthine responsible for the stimulant, cognitive, and ergogenic effects of the seed.', 'Paullinia cupana is defined by the combination of methylxanthine alkaloids and condensed tannins. While caffeine explains the herb''s well-known stimulant and cognitive effects, the abundant catechins and procyanidins likely modify absorption and contribute antioxidant activity, making guarana chemically more complex than a simple source of caffeine.'),
  (218, 'Guarana', 'Paullinia cupana', 'Seed', 'Theobromine', 'Alkaloid', 'Purine alkaloid', 'Moderate', 'Major', 'Methylxanthine complementing caffeine and contributing cardiovascular and stimulant activity.', NULL),
  (218, 'Guarana', 'Paullinia cupana', 'Seed', 'Theophylline', 'Alkaloid', 'Purine alkaloid', 'Low–Moderate', 'Present', 'Minor methylxanthine contributing bronchodilatory and stimulant activity.', NULL),
  (218, 'Guarana', 'Paullinia cupana', 'Seed', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Principal flavan-3-ol contributing antioxidant activity and forming part of the condensed tannin fraction.', NULL),
  (218, 'Guarana', 'Paullinia cupana', 'Seed', 'Epicatechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Flavan-3-ol complementing catechin within the seed''s polyphenol profile.', NULL),
  (218, 'Guarana', 'Paullinia cupana', 'Seed', 'Procyanidin B2', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Oligomeric procyanidin contributing antioxidant activity and complementing the catechin-rich tannin fraction.', NULL),
  (18, 'Guduchi', 'Tinospora cordifolia', 'Stem', 'Tinosporaside', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Principal phenolic glycoside and pharmacopoeial marker contributing antioxidant and immunomodulatory activity.', 'Tinospora cordifolia is chemically distinguished by the combination of clerodane diterpenoids, phenolic glycosides, and isoquinoline alkaloids. Unlike many Ayurvedic rasāyana herbs that are dominated by a single constituent family, Guduchi derives its broad immunomodulatory and hepatoprotective activity from the interaction of these complementary phytochemical groups.'),
  (18, 'Guduchi', 'Tinospora cordifolia', 'Stem', 'Cordifolioside A', 'Glycoside', 'Phenolic glycoside', 'High', 'Major', 'Characteristic glycoside contributing immunomodulatory and adaptogenic activity.', NULL),
  (18, 'Guduchi', 'Tinospora cordifolia', 'Stem', 'Columbin', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Clerodane diterpenoid contributing bitter tonic, hepatoprotective, and anti-inflammatory activity.', NULL),
  (18, 'Guduchi', 'Tinospora cordifolia', 'Stem', 'Magnoflorine', 'Alkaloid', 'Aporphine alkaloid', 'Moderate', 'Major', 'Major alkaloid contributing immunomodulatory and antioxidant activity.', NULL),
  (18, 'Guduchi', 'Tinospora cordifolia', 'Stem', 'Berberine', 'Alkaloid', 'Protoberberine alkaloid', 'Moderate', 'Present', 'Isoquinoline alkaloid reported from the stem that contributes complementary antimicrobial activity.', NULL)
INSERT INTO herbal.constituent_profiles
  (herb_id, common_name, latin_name, plant_part, constituent, class, subclass, importance, status, notes, editorial_note)
VALUES
  (18, 'Guduchi', 'Tinospora cordifolia', 'Stem', 'Tinosporide', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic clerodane diterpenoid complementing columbin and contributing to the stem''s bitter, hepatoprotective, and immunomodulatory activity.', NULL),
  (877, 'Guggul', 'Commiphora mukul', 'Oleo-gum-resin', '(Z)-Guggulsterone', 'Steroid', 'Steroidal sapogenin', 'High', 'Marker', 'Principal bioactive sterol associated with hypolipidemic, anti-inflammatory, and thyroid-modulating activity.', 'Commiphora mukul is defined by an unusual combination of guggulsterones and bioactive triterpenoids, distinguishing it from most medicinal resins. While the guggulsterones account for much of the herb''s well-known metabolic and lipid-regulating activity, the triterpenoid fraction contributes substantially to its anti-inflammatory effects, making both constituent families essential to a representative profile.'),
  (877, 'Guggul', 'Commiphora mukul', 'Oleo-gum-resin', '(E)-Guggulsterone', 'Steroid', 'Steroidal sapogenin', 'High', 'Marker', 'Geometric isomer of guggulsterone and an official analytical marker for guggul resin.', NULL),
  (877, 'Guggul', 'Commiphora mukul', 'Oleo-gum-resin', 'Mukulol', 'Terpenoid', 'Sesquiterpene alcohol', 'Moderate', 'Major', 'Characteristic sesquiterpene alcohol contributing to the resin''s anti-inflammatory and antimicrobial properties.', NULL),
  (877, 'Guggul', 'Commiphora mukul', 'Oleo-gum-resin', 'Myrrhanone A', 'Terpenoid', 'Ursane triterpenoid', 'Moderate', 'Major', 'Oxidized triterpenoid complementing myrrhanol A within the resin fraction.', NULL),
  (877, 'Guggul', 'Commiphora mukul', 'Oleo-gum-resin', 'Commipheric acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Major', 'Characteristic resin acid contributing anti-inflammatory and chemotaxonomic significance.', NULL),
  (877, 'Guggul', 'Commiphora mukul', 'Oleo-gum-resin', 'Guggulsterol I', 'Sterol', 'Phytosterol', 'Moderate', 'Present', 'Naturally occurring phytosterol contributing to the characteristic sterol fraction accompanying the guggulsterones.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'High', 'Marker', 'Principal flavonol glycoside and pharmacopoeial marker associated with cardiotonic and vascular activity.', 'Crataegus monogyna leaf and flower are defined by a complementary combination of flavonoids and oligomeric procyanidins, both of which contribute to the herb''s well-established cardiotonic and endothelial-supportive activity. Unlike many cardiovascular herbs, no single constituent dominates; instead, its clinical effects arise from the interaction of these two characteristic phytochemical families.'),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Vitexin-2''''-O-rhamnoside', 'Flavonoid', 'Flavone C-glycoside', 'High', 'Marker', 'Official quality marker contributing antioxidant and cardioprotective activity.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonoid supporting vascular integrity and antioxidant effects.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Vitexin', 'Flavonoid', 'Flavone C-glycoside', 'Moderate', 'Major', 'Characteristic flavone C-glycoside complementing vitexin-2''''-O-rhamnoside and contributing cardioprotective and antioxidant activity.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Procyanidin B2', 'Flavonoid', 'Flavan-3-ol', 'High', 'Major', 'Representative oligomeric procyanidin contributing positive inotropic and endothelial effects.', NULL),
  (NULL, 'Hawthorn', 'Crataegus monogyna', 'Leaf & flower', 'Epicatechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Monomeric flavan-3-ol complementing the oligomeric procyanidin fraction and contributing antioxidant activity.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Strobile', 'Humulone', 'Terpenoid', 'Prenylated phloroglucinol', 'High', 'Marker', 'Principal α-acid contributing bitter, sedative, and anti-inflammatory activity.', 'Humulus lupulus is defined by two distinctive constituent families: the bitter acids (humulones and lupulones) and the prenylated flavonoids, particularly xanthohumol. Together these explain the herb''s sedative, bitter tonic, antimicrobial, and phytoestrogenic activities, making hops one of the most chemically distinctive medicinal plants.'),
  (129, 'Hops', 'Humulus lupulus', 'Strobile', 'Lupulone', 'Terpenoid', 'Prenylated phloroglucinol', 'High', 'Marker', 'Principal β-acid contributing antimicrobial and bitter activity.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Strobile', 'Xanthohumol', 'Flavonoid', 'Prenylated chalcone', 'High', 'Marker', 'Characteristic prenylated chalcone contributing antioxidant, chemopreventive, and anti-inflammatory activity.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Strobile', '8-Prenylnaringenin', 'Flavonoid', 'Prenylated flavanone', 'Moderate', 'Major', 'Potent phytoestrogen formed naturally and during processing from hop prenylflavonoids.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Strobile', 'Desmethylxanthohumol', 'Flavonoid', 'Prenylated chalcone', 'Moderate', 'Major', 'Biosynthetic precursor of 8-prenylnaringenin and an important member of the hop prenylflavonoid fraction.', NULL),
  (129, 'Hops', 'Humulus lupulus', 'Strobile', 'Isoxanthohumol', 'Flavonoid', 'Prenylated flavanone', 'Moderate', 'Major', 'Prenylated flavanone formed naturally and during processing that complements xanthohumol and serves as a precursor to 8-prenylnaringenin.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Marrubiin', 'Terpenoid', 'Labdane diterpenoid', 'High', 'Marker', 'Principal bitter diterpene responsible for the herb''s characteristic expectorant and bitter tonic activity.', 'Marrubium vulgare is defined by its labdane diterpenes, particularly marrubiin, which account for its traditional use as a bitter expectorant and respiratory tonic. The flavones and phenylethanoid glycosides broaden the anti-inflammatory and antioxidant profile, but the bitter diterpenes remain the chemotaxonomic signature of the species.'),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Premarrubiin', 'Terpenoid', 'Labdane diterpenoid', 'Moderate', 'Major', 'Biosynthetic precursor of marrubiin contributing to the herb''s bitter diterpene profile.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Marrubenol', 'Terpenoid', 'Labdane diterpenoid', 'Moderate', 'Major', 'Characteristic labdane diterpenoid contributing to the species-specific diterpene fraction.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Flavone contributing antioxidant and anti-inflammatory activity.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Marrubiinic acid', 'Terpenoid', 'Labdane diterpenoid', 'Moderate', 'Major', 'Labdane diterpenoid related to marrubiin that contributes to the characteristic bitter diterpene profile of the aerial parts.', NULL),
  (160, 'Horehound', 'Marrubium vulgare', 'Aerial parts', 'Verbascoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Phenylethanoid glycoside contributing antioxidant activity and complementing the diterpene chemistry.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Aescin', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal triterpenoid saponin complex responsible for venotonic, anti-edematous, and vascular-protective activity.', 'Aesculus hippocastanum is defined by its aescin triterpenoid saponins, which account for its well-established venotonic and anti-edematous effects. Coumarin glycosides provide a distinctive secondary constituent family, while the flavonoids contribute complementary vascular and antioxidant activity without overshadowing the dominant saponin chemistry.'),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Protoaescigenin', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal triterpenoid sapogenin forming the aglycone of the aescin saponins.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Esculin', 'Coumarin', 'Coumarin glycoside', 'Moderate', 'Major', 'Coumarin glycoside contributing antioxidant activity and serving as a characteristic constituent of the species.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Fraxin', 'Coumarin', 'Coumarin glycoside', 'Moderate', 'Present', 'Coumarin glycoside complementing the characteristic hydroxycoumarin profile.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Flavonol contributing complementary antioxidant and vascular-supportive activity.', NULL),
  (62, 'Horse Chestnut', 'Aesculus hippocastanum', 'Seed', 'Cryptoaescin I', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Major triterpenoid saponin within the aescin complex that contributes to the seed''s venotonic and anti-edematous activity.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Equisetonin', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Characteristic saponin associated with the herb''s traditional diuretic and connective tissue-supporting activity.', 'Equisetum arvense is unusual among medicinal herbs in combining bioavailable silica, flavonoids, and the characteristic saponin equisetonin. While silica has historically received the most attention, the flavonoids and saponins likely contribute substantially to the herb''s diuretic and antioxidant activities, making horsetail chemically distinctive among vascular plants.'),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Isoquercitrin', 'Flavonoid', 'Flavonol glycoside', 'High', 'Major', 'Principal flavonoid contributing antioxidant and capillary-supportive activity.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Kaempferol-3-O-sophoroside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonol glycoside representative of the species'' distinctive flavonoid profile.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Dimethylsulfone (MSM)', 'Organosulfur compound', 'Sulfone', 'Moderate', 'Present', 'Naturally occurring organosulfur compound contributing to the herb''s connective tissue-supporting chemistry.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Nicotine', 'Alkaloid', 'Pyridine alkaloid', 'Low–Moderate', 'Present', 'Minor alkaloid consistently reported from the sterile stems and contributing to the species'' distinctive chemistry.', NULL),
  (151, 'Horsetail', 'Equisetum arvense', 'Sterile aerial stems', 'Silicic acid', 'Mineral', 'Silicon compound', 'High', 'Marker', 'Bioavailable silicon compound contributing to the herb''s traditional use for connective tissue, bone, hair, and nails.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Flowering tops', 'Pinocamphone', 'Terpenoid', 'Monoterpene ketone', 'High', 'Marker', 'Principal monoterpene ketone responsible for the herb''s characteristic aroma and much of its respiratory activity.', 'Hyssopus officinalis is characterized by a pinocamphone-rich volatile oil balanced by the non-volatile rosmarinic acid fraction typical of many Lamiaceae herbs. Unlike horehound, whose medicinal chemistry is dominated by labdane diterpenes, hyssop''s traditional respiratory actions are driven primarily by its distinctive monoterpene ketones.'),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Flowering tops', 'Isopinocamphone', 'Terpenoid', 'Monoterpene ketone', 'High', 'Major', 'Characteristic monoterpene ketone complementing pinocamphone within the essential oil profile.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Flowering tops', 'β-Pinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Major monoterpene contributing antimicrobial and expectorant activity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Flowering tops', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene complementing the pinocamphone-rich volatile fraction and contributing antimicrobial activity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Flowering tops', 'Rosmarinic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Major', 'Principal non-volatile phenolic contributing antioxidant and anti-inflammatory activity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Flowering tops', 'Hesperidin', 'Flavonoid', 'Flavanone glycoside', 'Moderate', 'Present', 'Flavanone glycoside reported from the aerial parts, complementing the herb''s non-volatile polyphenol profile.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Lichenin', 'Polysaccharide', 'β-Glucan', 'High', 'Marker', 'Principal water-soluble β-glucan contributing the lichen''s demulcent and immunomodulatory properties.', 'Cetraria islandica is chemically defined by the combination of mucilaginous polysaccharides and lichen acids. The polysaccharides explain its traditional demulcent use for irritated mucous membranes, while the bitter depsidones and related lichen metabolites contribute antimicrobial activity and distinguish Iceland moss from vascular medicinal plants.'),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Isolichenin', 'Polysaccharide', 'α-Glucan', 'High', 'Major', 'Characteristic storage polysaccharide complementing lichenin in the mucilaginous fraction.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Cetraric acid', 'Phenolic', 'Depsidone', 'High', 'Marker', 'Principal bitter lichen acid responsible for tonic bitterness and contributing antimicrobial activity.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Fumarprotocetraric acid', 'Phenolic', 'Depsidone', 'Moderate', 'Major', 'Characteristic depsidone contributing bitterness and antimicrobial activity.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Protocetraric acid', 'Phenolic', 'Depsidone', 'Moderate', 'Present', 'Lichen-specific depsidone complementing the characteristic bitter acid profile.', NULL),
  (48, 'Iceland Moss', 'Cetraria islandica', 'Thallus', 'Protolichesterinic acid', 'Lipid', 'Fatty acid', 'Moderate', 'Major', 'Characteristic lichen fatty acid contributing antimicrobial activity and representing a distinctive secondary metabolite of the thallus.', NULL),
  (132, 'Indian Tobacco', 'Lobelia inflata', 'Aerial parts', 'Lobeline', 'Alkaloid', 'Piperidine alkaloid', 'High', 'Marker', 'Principal alkaloid responsible for the herb''s respiratory stimulant and antispasmodic activity.', 'Lobelia inflata is one of the clearest examples of a medicinal herb defined almost entirely by a single constituent family. Its piperidine alkaloids, especially lobeline, account for nearly all of its respiratory, autonomic, and neuromodulatory activity, making additional non-alkaloid constituents unnecessary for a representative phytochemical profile.'),
  (132, 'Indian Tobacco', 'Lobelia inflata', 'Aerial parts', 'Lobelanidine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Major', 'Characteristic alkaloid complementing lobeline within the species'' distinctive alkaloid profile.', NULL),
  (132, 'Indian Tobacco', 'Lobelia inflata', 'Aerial parts', 'Norlobelanine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Major', 'Naturally occurring piperidine alkaloid contributing to the characteristic lobelia alkaloid fraction.', NULL),
  (132, 'Indian Tobacco', 'Lobelia inflata', 'Aerial parts', 'Lobelanine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Major', 'Characteristic piperidine alkaloid supporting the species-specific alkaloid profile.', NULL),
  (132, 'Indian Tobacco', 'Lobelia inflata', 'Aerial parts', 'Lobinine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Present', 'Characteristic piperidine alkaloid complementing lobeline and contributing to the species'' distinctive alkaloid profile.', NULL),
  (132, 'Indian Tobacco', 'Lobelia inflata', 'Aerial parts', 'Lobinaline', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Present', 'Piperidine alkaloid associated with complementary neuropharmacological activity.', NULL),
  (49, 'Irish Moss', 'Chondrus crispus', 'Thallus', 'κ-Carrageenan', 'Polysaccharide', 'Sulfated galactan', 'High', 'Marker', 'Principal sulfated polysaccharide responsible for the demulcent, gelling, and immunomodulatory properties of the thallus.', 'Chondrus crispus is overwhelmingly defined by its sulfated galactans, particularly the carrageenans that account for its demulcent, gelling, and mucosal-supportive properties. The remaining constituents primarily reflect its identity as a red alga, with floridosides and phycobiliproteins providing characteristic supporting chemistry rather than driving its traditional medicinal use.'),
  (49, 'Irish Moss', 'Chondrus crispus', 'Thallus', 'λ-Carrageenan', 'Polysaccharide', 'Sulfated galactan', 'High', 'Major', 'Sulfated galactan complementing κ-carrageenan and contributing to the characteristic mucilaginous profile.', NULL),
  (49, 'Irish Moss', 'Chondrus crispus', 'Thallus', 'ι-Carrageenan', 'Polysaccharide', 'Sulfated galactan', 'Moderate', 'Major', 'Characteristic sulfated galactan contributing to the rheological and demulcent properties of the thallus.', NULL),
  (49, 'Irish Moss', 'Chondrus crispus', 'Thallus', 'Floridoside', 'Carbohydrate', 'Glycerol glycoside', 'Moderate', 'Major', 'Characteristic red algal osmolyte contributing to the species'' carbohydrate chemistry.', NULL),
  (49, 'Irish Moss', 'Chondrus crispus', 'Thallus', 'Isofloridoside', 'Carbohydrate', 'Glycerol glycoside', 'Moderate', 'Present', 'Companion glycerol glycoside characteristic of red algae and complementing floridoside.', NULL),
  (49, 'Irish Moss', 'Chondrus crispus', 'Thallus', 'Citrulline', 'Amino acid', 'Non-proteinogenic amino acid', 'Moderate', 'Present', 'Characteristic free amino acid contributing to the distinctive nitrogen metabolism of the red alga.', NULL),
  (139, 'Jamaican Dogwood', 'Piscidia piscipula', 'Root bark', 'Rotenone', 'Terpenoid', 'Rotenoid', 'High', 'Marker', 'Characteristic rotenoid contributing to the bark''s analgesic, sedative, and piscicidal activity.', 'Piscidia piscipula is chemically distinguished by its rotenoids and related isoflavonoids, which account for its traditional use as an analgesic, sedative, and fish poison. Unlike most medicinal Fabaceae, Jamaican dogwood emphasizes rotenoid chemistry over triterpenoid saponins, giving it a distinctive pharmacological profile.'),
  (139, 'Jamaican Dogwood', 'Piscidia piscipula', 'Root bark', 'Piscidin', 'Polyphenol', 'Isoflavonoid', 'High', 'Major', 'Characteristic isoflavonoid associated with the bark''s traditional analgesic and antispasmodic activity.', NULL),
  (139, 'Jamaican Dogwood', 'Piscidia piscipula', 'Root bark', 'Piscerythrol', 'Polyphenol', 'Isoflavonoid', 'Moderate', 'Major', 'Characteristic rotenoid-related isoflavonoid complementing the bark''s distinctive chemistry.', NULL),
  (139, 'Jamaican Dogwood', 'Piscidia piscipula', 'Root bark', 'Maackiain', 'Polyphenol', 'Pterocarpan', 'Moderate', 'Major', 'Pterocarpan phytoalexin contributing antioxidant and antimicrobial activity.', NULL),
  (139, 'Jamaican Dogwood', 'Piscidia piscipula', 'Root bark', 'Piscidone', 'Polyphenol', 'Isoflavanone', 'Moderate', 'Major', 'Characteristic isoflavanone contributing to the species-specific rotenoid and isoflavonoid chemistry.', NULL),
  (139, 'Jamaican Dogwood', 'Piscidia piscipula', 'Root bark', 'Medicarpin', 'Polyphenol', 'Pterocarpan', 'Moderate', 'Present', 'Characteristic pterocarpan contributing to the species'' legume phenolic profile.', NULL),
  (NULL, 'Japanese Honeysuckle', 'Lonicera japonica', 'Flower bud', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'High', 'Marker', 'Principal phenolic constituent and pharmacopoeial marker contributing antioxidant, antiviral, and anti-inflammatory activity.', 'Lonicera japonica flower buds are defined by the interplay of caffeoylquinic acids, flavone glycosides, and iridoid glycosides. Unlike many medicinal flowers that rely primarily on flavonoids, Japanese honeysuckle derives its broad antimicrobial and antiviral activity from the combined action of these three complementary phytochemical families.'),
  (NULL, 'Japanese Honeysuckle', 'Lonicera japonica', 'Flower bud', 'Luteoloside', 'Flavonoid', 'Flavone glycoside', 'High', 'Marker', 'Principal flavonoid glycoside used for quality control and contributing anti-inflammatory activity.', NULL),
  (NULL, 'Japanese Honeysuckle', 'Lonicera japonica', 'Flower bud', 'Sweroside', 'Glycoside', 'Secoiridoid glycoside', 'High', 'Major', 'Characteristic secoiridoid glycoside contributing to the flower bud''s anti-inflammatory and antiviral activity.', NULL),
  (NULL, 'Japanese Honeysuckle', 'Lonicera japonica', 'Flower bud', 'Lonicerin', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavone glycoside complementing the flower bud flavonoid profile.', NULL),
  (NULL, 'Japanese Honeysuckle', 'Lonicera japonica', 'Flower bud', 'Loganin', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Characteristic iridoid glycoside contributing to the herb''s anti-inflammatory and antiviral activity.', NULL),
  (NULL, 'Japanese Honeysuckle', 'Lonicera japonica', 'Flower bud', '3,5-Dicaffeoylquinic acid', 'Polyphenol', 'Dicaffeoylquinic acid', 'Moderate', 'Present', 'Major dicaffeoylquinic acid complementing chlorogenic acid within the characteristic caffeoylquinic acid fraction.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene contributing to the berry''s diuretic, antimicrobial, and warming actions.', 'Juniperus communis berries are defined primarily by their monoterpene-rich volatile fraction, which explains their traditional diuretic, urinary antiseptic, and digestive actions. The inclusion of juniperic acid and amentoflavone captures the distinctive non-volatile chemistry without detracting from the terpene profile that defines the species.'),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Sabinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Characteristic monoterpene contributing to the distinctive aroma and urinary antiseptic activity.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Myrcene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Monoterpene complementing the volatile profile and contributing anti-inflammatory activity.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Terpinen-4-ol', 'Terpenoid', 'Monoterpene alcohol', 'Moderate', 'Major', 'Oxygenated monoterpene contributing diuretic and antimicrobial activity.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Juniperic acid', 'Lipid', 'Dicarboxylic acid', 'Moderate', 'Marker', 'Characteristic long-chain dicarboxylic acid serving as a chemotaxonomic marker of Juniperus species.', NULL),
  (103, 'Juniper', 'Juniperus communis', 'Berry (galbulus)', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene complementing α-pinene and sabinene within the berry''s volatile profile and contributing digestive and antimicrobial activity.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Kavain', 'Lactone', 'Kavalactone', 'High', 'Marker', 'Principal kavalactone contributing anxiolytic, muscle-relaxant, and calming activity.', 'Piper methysticum is one of the clearest examples of a medicinal plant defined almost entirely by a single constituent family. Its six major kavalactones form the basis of chemotype classification and account for nearly all of the herb''s anxiolytic, muscle-relaxant, and psychoactive properties, making additional non-kavalactone constituents unnecessary for a representative phytochemical profile.'),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Dihydrokavain', 'Lactone', 'Kavalactone', 'High', 'Major', 'Major kavalactone complementing kavain and contributing anxiolytic activity.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Methysticin', 'Lactone', 'Kavalactone', 'High', 'Major', 'Characteristic kavalactone contributing anxiolytic activity and modulation of GABAergic signaling.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Dihydromethysticin', 'Lactone', 'Kavalactone', 'Moderate', 'Major', 'Major kavalactone contributing to the characteristic psychoactive profile of kava.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Yangonin', 'Lactone', 'Kavalactone', 'Moderate', 'Major', 'Distinctive kavalactone with affinity for the cannabinoid CB₁ receptor, complementing the anxiolytic chemistry.', NULL),
  (138, 'Kava', 'Piper methysticum', 'Root & rhizome', 'Desmethoxyyangonin', 'Lactone', 'Kavalactone', 'Moderate', 'Major', 'Characteristic kavalactone completing the six principal kavalactones recognized in chemotype classification.', NULL),
  (NULL, 'Kelp', 'Saccharina latissima', 'Blade', 'Fucoidan', 'Polysaccharide', 'Sulfated fucan', 'High', 'Marker', 'Principal sulfated polysaccharide contributing immunomodulatory, anticoagulant, and anti-inflammatory activity.', 'Saccharina latissima is defined by a combination of structural and storage polysaccharides, particularly fucoidan, alginate, and laminarin, together with the characteristic brown algal carotenoid fucoxanthin. Unlike terrestrial medicinal plants, kelp''s medicinal chemistry is dominated by polysaccharides and marine-specific metabolites, with iodine serving as an important nutritional and chemotaxonomic marker.'),
  (NULL, 'Kelp', 'Saccharina latissima', 'Blade', 'Alginic acid', 'Polysaccharide', 'Alginate', 'High', 'Marker', 'Major structural polysaccharide responsible for demulcent, metal-binding, and gel-forming properties.', NULL),
  (NULL, 'Kelp', 'Saccharina latissima', 'Blade', 'Laminarin', 'Polysaccharide', 'β-Glucan', 'High', 'Major', 'Storage β-glucan contributing prebiotic and immunomodulatory activity.', NULL),
  (NULL, 'Kelp', 'Saccharina latissima', 'Blade', 'Fucoxanthin', 'Carotenoid', 'Xanthophyll', 'High', 'Major', 'Characteristic brown algal carotenoid contributing antioxidant and metabolic activity.', NULL),
  (NULL, 'Kelp', 'Saccharina latissima', 'Blade', 'Mannitol', 'Carbohydrate', 'Sugar alcohol', 'Moderate', 'Major', 'Major photosynthetic storage product contributing osmotic regulation and representing characteristic brown algal chemistry.', NULL),
  (NULL, 'Kelp', 'Saccharina latissima', 'Blade', 'Phloroglucinol', 'Polyphenol', 'Phlorotannin precursor', 'Moderate', 'Major', 'Fundamental phenolic building block of the characteristic brown algal phlorotannins, contributing antioxidant activity and representing the species'' distinctive phenolic chemistry.', NULL),
  (1014, 'Lady''s Mantle', 'Alchemilla vulgaris agg.', 'Aerial parts', 'Agrimoniin', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Principal ellagitannin responsible for the herb''s pronounced astringent and antioxidant activity.', 'Alchemilla vulgaris is defined by its ellagitannins, particularly agrimoniin, which account for much of the herb''s traditional astringent, wound-healing, and gynecological use. Flavonoids provide complementary antioxidant activity, but the hydrolyzable tannins remain the dominant and distinguishing chemistry of the genus.'),
  (1014, 'Lady''s Mantle', 'Alchemilla vulgaris agg.', 'Aerial parts', 'Pedunculagin', 'Tannin', 'Ellagitannin', 'High', 'Major', 'Characteristic ellagitannin complementing agrimoniin within the herb''s astringent tannin fraction.', NULL),
  (1014, 'Lady''s Mantle', 'Alchemilla vulgaris agg.', 'Aerial parts', 'Tellimagrandin I', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Hydrolyzable tannin contributing antioxidant and anti-inflammatory activity.', NULL),
  (1014, 'Lady''s Mantle', 'Alchemilla vulgaris agg.', 'Aerial parts', 'Tellimagrandin II', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Characteristic ellagitannin complementing agrimoniin and pedunculagin within the herb''s hydrolyzable tannin profile.', NULL),
  (1014, 'Lady''s Mantle', 'Alchemilla vulgaris agg.', 'Aerial parts', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Major flavonol glycoside supporting the herb''s vascular and antioxidant profile.', NULL),
  (1014, 'Lady''s Mantle', 'Alchemilla vulgaris agg.', 'Aerial parts', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Present', 'Phenolic constituent derived from ellagitannins that complements the characteristic tannin chemistry.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Linalool', 'Terpenoid', 'Monoterpene alcohol', 'High', 'Marker', 'Principal monoterpene alcohol contributing anxiolytic, antimicrobial, and spasmolytic activity.', 'Lavandula angustifolia is defined by the balance of linalool and linalyl acetate, a volatile profile that distinguishes true lavender from other Lavandula species and underlies its calming, antispasmodic, and antimicrobial properties. Rosmarinic acid provides a characteristic Lamiaceae phenolic component, but the monoterpenes remain the herb''s defining chemistry.'),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Linalyl acetate', 'Terpenoid', 'Monoterpene ester', 'High', 'Marker', 'Major ester responsible for the characteristic aroma and synergistic calming effects of lavender oil.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Lavandulol', 'Terpenoid', 'Monoterpene alcohol', 'Moderate', 'Major', 'Characteristic lavender monoterpene contributing to the distinctive floral aroma and antimicrobial activity.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Lavandulyl acetate', 'Terpenoid', 'Monoterpene ester', 'Moderate', 'Major', 'Characteristic ester complementing linalyl acetate within the authentic lavender essential oil profile.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Terpinen-4-ol', 'Terpenoid', 'Monoterpene alcohol', 'Moderate', 'Major', 'Characteristic oxygenated monoterpene contributing antimicrobial activity and complementing the linalool-rich essential oil profile.', NULL),
  (82, 'Lavender', 'Lavandula angustifolia', 'Flower', 'Rosmarinic acid', 'Polyphenol', 'Rosmarinic acid derivative', 'Moderate', 'Major', 'Principal non-volatile phenolic contributing antioxidant and anti-inflammatory activity.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Rosmarinic acid derivative', 'High', 'Marker', 'Principal phenolic constituent contributing antiviral, antioxidant, and anxiolytic activity.', 'Melissa officinalis derives its medicinal activity from the complementary actions of rosmarinic acid and its citral-rich volatile oil. Unlike many aromatic Lamiaceae herbs that are dominated by monoterpenes, lemon balm combines substantial phenolic and volatile fractions, helping explain its broad antiviral, anxiolytic, and cognitive-supportive effects.'),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Citral', 'Terpenoid', 'Monoterpene aldehyde', 'High', 'Marker', 'Characteristic mixture of geranial and neral responsible for the herb''s distinctive lemon aroma and much of its antimicrobial activity.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Citronellal', 'Terpenoid', 'Monoterpene aldehyde', 'Moderate', 'Major', 'Major volatile constituent contributing calming, antimicrobial, and insect-repellent activity.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Geraniol', 'Terpenoid', 'Monoterpene alcohol', 'Moderate', 'Major', 'Monoterpene alcohol complementing the citral-rich volatile profile.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Salvianolic acid A', 'Polyphenol', 'Depside', 'Moderate', 'Major', 'Characteristic caffeic acid oligomer complementing rosmarinic acid and contributing antioxidant and antiviral activity.', NULL),
  (134, 'Lemon Balm', 'Melissa officinalis', 'Leaf', 'Luteolin-7-O-glucoside', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavone glycoside contributing antioxidant and anti-inflammatory activity.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Glycyrrhizin', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal triterpenoid saponin responsible for the characteristic sweet taste and much of the herb''s anti-inflammatory, antiviral, and adrenal-modulating activity.', 'Glycyrrhiza glabra derives its medicinal activity from the complementary actions of triterpenoid saponins and a remarkably diverse flavonoid fraction. While glycyrrhizin defines the herb pharmacologically and analytically, the chalcones and isoflavans contribute substantially to its anti-inflammatory, antioxidant, antimicrobial, and mucosal-protective effects, making licorice one of the most chemically diverse medicinal roots.'),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Glycyrrhetinic acid', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Major', 'Principal sapogenin of glycyrrhizin contributing anti-inflammatory and mineralocorticoid activity.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Liquiritin', 'Flavonoid', 'Flavanone glycoside', 'High', 'Marker', 'Major flavonoid glycoside and pharmacopoeial marker contributing antioxidant and anti-inflammatory activity.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Isoliquiritigenin', 'Flavonoid', 'Chalcone', 'Moderate', 'Major', 'Characteristic chalcone contributing antioxidant, estrogenic, and anti-inflammatory activity.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Glabridin', 'Flavonoid', 'Isoflavan', 'Moderate', 'Major', 'Characteristic prenylated isoflavan contributing antioxidant, antimicrobial, and skin-protective activity.', NULL),
  (78, 'Licorice', 'Glycyrrhiza glabra', 'Root', 'Liquiritigenin', 'Flavonoid', 'Flavanone', 'Moderate', 'Major', 'Characteristic flavanone aglycone complementing liquiritin and contributing anti-inflammatory, antioxidant, and phytoestrogenic activity.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower & bract', 'Tiliroside', 'Flavonoid', 'Flavonol glycoside', 'High', 'Marker', 'Characteristic kaempferol glycoside contributing anti-inflammatory, antioxidant, and anxiolytic activity.', 'Tilia cordata flowers are characterized primarily by their flavonol glycosides, especially tiliroside, which distinguish the genus from many other relaxing herbs. The flavonoid-rich chemistry is complemented by a modest volatile fraction, helping explain linden''s traditional use as a gentle calming, diaphoretic, and soothing herb.'),
  (NULL, 'Linden', 'Tilia cordata', 'Flower & bract', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Major', 'Principal flavonol contributing antioxidant and capillary-supportive activity.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower & bract', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonol glycoside supporting vascular and antioxidant effects.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower & bract', 'Astragalin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Kaempferol glycoside complementing tiliroside within the characteristic flavonoid profile.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower & bract', 'Procyanidin B2', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Oligomeric procyanidin contributing antioxidant activity and complementing the characteristic flavonoid profile.', NULL),
  (NULL, 'Linden', 'Tilia cordata', 'Flower & bract', 'Farnesol', 'Terpenoid', 'Sesquiterpene alcohol', 'Moderate', 'Present', 'Volatile sesquiterpene alcohol contributing to the flower''s aroma and mild calming activity.', NULL),
  (132, 'Lobelia', 'Lobelia inflata', 'Aerial parts', 'Lobeline', 'Alkaloid', 'Piperidine alkaloid', 'High', 'Marker', 'Principal piperidine alkaloid responsible for the herb''s respiratory stimulant and antispasmodic activity.', 'Lobelia inflata is almost entirely defined by its piperidine alkaloids, with lobeline serving as both its pharmacological and chemotaxonomic hallmark. Because these alkaloids account for nearly all of the herb''s distinctive respiratory and neuromodulatory activity, additional constituent classes add little to a representative profile.'),
  (132, 'Lobelia', 'Lobelia inflata', 'Aerial parts', 'Lobelanidine', 'Alkaloid', 'Piperidine alkaloid', 'High', 'Major', 'Major piperidine alkaloid complementing lobeline within the characteristic alkaloid profile.', NULL),
  (132, 'Lobelia', 'Lobelia inflata', 'Aerial parts', 'Lobelanine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Major', 'Characteristic piperidine alkaloid contributing to the species-specific alkaloid chemistry.', NULL),
  (132, 'Lobelia', 'Lobelia inflata', 'Aerial parts', 'Lobinaline', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Major', 'Bioactive piperidine alkaloid contributing nicotinic receptor modulation and neuroprotective activity.', NULL),
  (132, 'Lobelia', 'Lobelia inflata', 'Aerial parts', 'Lobinine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Present', 'Characteristic minor alkaloid complementing the lobeline family.', NULL),
  (132, 'Lobelia', 'Lobelia inflata', 'Aerial parts', 'Norlobelanine', 'Alkaloid', 'Piperidine alkaloid', 'Moderate', 'Present', 'Naturally occurring piperidine alkaloid completing the representative lobeline alkaloid profile.', NULL),
  (NULL, 'Lovage', 'Levisticum officinale', 'Root', 'Ligustilide', 'Terpenoid', 'Phthalide', 'High', 'Marker', 'Principal phthalide contributing the characteristic aroma, spasmolytic activity, and digestive effects.', 'Levisticum officinale root is defined by its phthalides, particularly ligustilide, which account for much of its characteristic aroma and spasmolytic activity. Polyacetylenes and furanocoumarins broaden the profile, but the phthalides remain the distinguishing chemistry shared with a small group of medicinal Apiaceae.'),
  (NULL, 'Lovage', 'Levisticum officinale', 'Root', 'Butylidenephthalide', 'Terpenoid', 'Phthalide', 'High', 'Major', 'Characteristic phthalide complementing ligustilide and contributing smooth muscle-relaxing activity.', NULL),
  (NULL, 'Lovage', 'Levisticum officinale', 'Root', 'Senkyunolide A', 'Terpenoid', 'Phthalide', 'Moderate', 'Major', 'Characteristic phthalide contributing to the root''s distinctive Apiaceae chemistry.', NULL),
  (NULL, 'Lovage', 'Levisticum officinale', 'Root', 'Falcarinol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Characteristic polyacetylene contributing antimicrobial and anti-inflammatory activity.', NULL),
  (NULL, 'Lovage', 'Levisticum officinale', 'Root', 'Falcarindiol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Major', 'Polyacetylene complementing falcarinol within the characteristic root chemistry.', NULL),
  (NULL, 'Lovage', 'Levisticum officinale', 'Root', 'Sedanolide', 'Terpenoid', 'Phthalide', 'Moderate', 'Major', 'Characteristic phthalide complementing ligustilide and reinforcing the root''s distinctive aromatic and spasmolytic chemistry.', NULL),
  (200, 'Lungwort', 'Pulmonaria officinalis', 'Aerial parts', 'Rosmarinic acid', 'Polyphenol', 'Depside', 'High', 'Marker', 'Principal phenolic constituent contributing antioxidant, anti-inflammatory, and mucosal-protective activity.', 'Pulmonaria officinalis derives much of its medicinal chemistry from caffeic acid derivatives, particularly rosmarinic and lithospermic acids, rather than from the mucilage historically emphasized in herbal texts. These phenolics, together with allantoin and flavonoids, provide a modern phytochemical basis for the herb''s traditional respiratory and tissue-soothing applications.'),
  (200, 'Lungwort', 'Pulmonaria officinalis', 'Aerial parts', 'Lithospermic acid', 'Polyphenol', 'Depside', 'Moderate', 'Major', 'Characteristic caffeic acid oligomer complementing rosmarinic acid within the Boraginaceae phenolic profile.', NULL),
  (200, 'Lungwort', 'Pulmonaria officinalis', 'Aerial parts', 'Allantoin', 'Nitrogenous compound', 'Ureide', 'Moderate', 'Major', 'Characteristic wound-healing constituent contributing to epithelial repair and mucosal support.', NULL),
  (200, 'Lungwort', 'Pulmonaria officinalis', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Major flavonoid contributing antioxidant and capillary-supportive activity.', NULL),
  (200, 'Lungwort', 'Pulmonaria officinalis', 'Aerial parts', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Flavonol glycoside complementing the herb''s antioxidant profile.', NULL),
  (200, 'Lungwort', 'Pulmonaria officinalis', 'Aerial parts', 'Salvianolic acid B', 'Polyphenol', 'Depside', 'Moderate', 'Major', 'Caffeic acid oligomer complementing rosmarinic and lithospermic acids within the characteristic Boraginaceae phenolic profile.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Macamide B', 'Lipid', 'Fatty acid amide', 'High', 'Marker', 'Representative macamide contributing to the characteristic neuroactive and adaptogenic chemistry unique to maca.', 'Maca is chemically distinguished by a unique combination of macamides, maca alkaloids, and benzyl glucosinolates. While it belongs to the Brassicaceae, its characteristic fatty acid amides are largely unique within the family and help explain why maca occupies a distinct place among adaptogenic medicinal plants.'),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'N-Benzylhexadecanamide', 'Lipid', 'Fatty acid amide', 'High', 'Major', 'Principal macamide contributing to the species'' distinctive fatty acid amide profile.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Macaridine', 'Alkaloid', 'Pyridine alkaloid', 'High', 'Marker', 'Characteristic alkaloid unique to maca and widely used as a chemotaxonomic marker.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Benzyl glucosinolate', 'Glycoside', 'Glucosinolate', 'High', 'Major', 'Principal glucosinolate contributing to the pungent chemistry typical of the Brassicaceae.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'm-Methoxybenzyl glucosinolate', 'Glycoside', 'Glucosinolate', 'Moderate', 'Major', 'Characteristic aromatic glucosinolate complementing the primary glucosinolate profile.', NULL),
  (851, 'Maca', 'Lepidium meyenii', 'Hypocotyl', 'Macaene', 'Lipid', 'Polyunsaturated fatty acid', 'Moderate', 'Major', 'Characteristic unsaturated fatty acid associated with the macamide fraction and contributing to the distinctive lipid chemistry of maca.', NULL),
  (NULL, 'Madder', 'Rubia tinctorum', 'Root', 'Alizarin', 'Quinone', 'Anthraquinone', 'High', 'Marker', 'Principal anthraquinone pigment responsible for the root''s characteristic red color and chemotaxonomic identity.', 'Rubia tinctorum is defined almost entirely by its anthraquinone pigments, particularly alizarin and purpurin, which account for both its historical importance as a dye plant and much of its medicinal chemistry. The accompanying anthraquinone glycosides and naphthohydroquinones broaden the profile while preserving the pigment chemistry that distinguishes the genus.'),
  (NULL, 'Madder', 'Rubia tinctorum', 'Root', 'Purpurin', 'Quinone', 'Anthraquinone', 'High', 'Major', 'Major anthraquinone contributing to the characteristic pigment profile and antioxidant activity.', NULL),
  (NULL, 'Madder', 'Rubia tinctorum', 'Root', 'Rubiadin', 'Quinone', 'Anthraquinone', 'Moderate', 'Major', 'Characteristic anthraquinone complementing alizarin and purpurin within the root pigment fraction.', NULL),
  (NULL, 'Madder', 'Rubia tinctorum', 'Root', 'Pseudopurpurin', 'Quinone', 'Anthraquinone', 'Moderate', 'Major', 'Characteristic anthraquinone pigment complementing alizarin and purpurin and contributing to the root''s distinctive dye chemistry.', NULL),
  (NULL, 'Madder', 'Rubia tinctorum', 'Root', 'Mollugin', 'Quinone', 'Naphthohydroquinone', 'Moderate', 'Major', 'Characteristic naphthohydroquinone contributing anti-inflammatory and antimicrobial activity.', NULL),
  (NULL, 'Madder', 'Rubia tinctorum', 'Root', 'Lucidin primeveroside', 'Glycoside', 'Anthraquinone glycoside', 'Moderate', 'Present', 'Glycosylated anthraquinone serving as a natural storage form of lucidin within the root.', NULL),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Rhamnogalacturonan I', 'Polysaccharide', 'Pectic polysaccharide', 'High', 'Marker', 'Principal mucilaginous polysaccharide contributing the root''s demulcent, soothing, and mucosal-protective activity.', 'Althaea officinalis root is defined overwhelmingly by its acidic mucilaginous polysaccharides, which account for its classic demulcent and mucosal-protective actions. The remaining constituents are present in much smaller amounts and primarily serve to complement, rather than define, the polysaccharide-rich chemistry that distinguishes marshmallow root.'),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'High', 'Major', 'Branched polysaccharide contributing immunomodulatory and demulcent activity within the mucilage fraction.', NULL),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Glucuronoarabinoxylan', 'Polysaccharide', 'Hemicellulose', 'Moderate', 'Major', 'Characteristic acidic polysaccharide contributing viscosity and mucosal adhesion.', NULL),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Galacturonic acid', 'Carbohydrate', 'Uronic acid', 'Moderate', 'Major', 'Principal uronic acid residue forming the backbone of the root''s acidic mucilage polysaccharides and contributing to their viscosity and demulcent properties.', NULL),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Scopoletin', 'Coumarin', 'Simple coumarin', 'Moderate', 'Present', 'Coumarin contributing complementary anti-inflammatory activity within the root.', NULL),
  (45, 'Marshmallow', 'Althaea officinalis', 'Root', 'Glucuronic acid', 'Carbohydrate', 'Uronic acid', 'Moderate', 'Major', 'Characteristic uronic acid residue contributing to the acidic pectic polysaccharides responsible for the root''s mucosal adhesion.', NULL),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Spiraein', 'Phenylpropanoid', 'Salicylate glycoside', 'High', 'Marker', 'Characteristic salicylate glycoside contributing anti-inflammatory, analgesic, and antipyretic activity.', 'Filipendula ulmaria is unusual in combining salicylate glycosides with a substantial ellagitannin fraction. While the salicylates explain the herb''s traditional analgesic and anti-inflammatory use, the tannins and flavonoids help distinguish meadowsweet from willow by contributing mucosal protection and antioxidant activity.'),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Monotropitin', 'Phenylpropanoid', 'Salicylate glycoside', 'High', 'Major', 'Major salicylate glycoside complementing spiraein within the herb''s characteristic salicylate profile.', NULL),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Methyl salicylate', 'Phenylpropanoid', 'Salicylate ester', 'Moderate', 'Major', 'Volatile salicylate contributing the characteristic aroma and complementing the glycoside fraction.', NULL),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Rugosin D', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Major ellagitannin contributing antioxidant and astringent activity.', NULL),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Tellimagrandin II', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Characteristic ellagitannin complementing rugosin D within the hydrolyzable tannin fraction.', NULL),
  (75, 'Meadowsweet', 'Filipendula ulmaria', 'Flowering tops', 'Kaempferol-4′-O-glucoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonol glycoside complementing the salicylate and ellagitannin fractions while contributing antioxidant activity.', NULL),
  (657, 'Gumweed', 'Grindelia spp.', 'Flowering tops', 'Grindelic acid', 'Terpenoid', 'Labdane diterpene resin acid', 'High', 'Marker', 'Principal resin acid defining the sticky resinous exudate and contributing expectorant, antispasmodic, and anti-inflammatory activity.', 'Grindelia species are chemically distinguished by their labdane diterpene resin acids, particularly grindelic acid and its derivatives, which account for the sticky resin and much of the herb''s expectorant and antispasmodic activity. Flavonoids provide complementary anti-inflammatory effects, but the resin acids remain the defining chemistry of the genus.'),
  (657, 'Gumweed', 'Grindelia spp.', 'Flowering tops', '6-O-Benzoylgrindelic acid', 'Terpenoid', 'Labdane diterpene resin acid', 'High', 'Major', 'Characteristic acylated grindelic acid derivative representing the distinctive resin acid fraction.', NULL),
  (657, 'Gumweed', 'Grindelia spp.', 'Flowering tops', 'Grindelol', 'Terpenoid', 'Labdane diterpene', 'Moderate', 'Major', 'Characteristic labdane diterpene contributing to the resin chemistry of the flowering tops.', NULL),
  (657, 'Gumweed', 'Grindelia spp.', 'Flowering tops', 'Grindelol acetate', 'Terpenoid', 'Labdane diterpene', 'Moderate', 'Major', 'Characteristic acetylated labdane diterpene complementing grindelol within the resin fraction.', NULL),
  (657, 'Gumweed', 'Grindelia spp.', 'Flowering tops', 'Luteolin-7-O-glucoside', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside complementing the diterpene resin fraction with antioxidant and anti-inflammatory activity.', NULL),
  (657, 'Gumweed', 'Grindelia spp.', 'Flowering tops', 'Quercetin-3-O-glucoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonol glycoside representing the principal flavonoid fraction of the flowering tops.', NULL),
  (10, 'Hardy Rubber Tree', 'Eucommia ulmoides', 'Bark', 'Pinoresinol diglucoside', 'Lignan', 'Lignan glycoside', 'High', 'Marker', 'Principal lignan glycoside contributing connective tissue-supportive, antihypertensive, and antioxidant activity.', 'Eucommia ulmoides possesses a distinctive combination of iridoid glycosides, lignan glycosides, and the unique natural polymer gutta-percha. While the iridoids and lignans account for most of the herb''s connective tissue, bone, and cardiovascular actions, the presence of trans-polyisoprene provides an unusual chemotaxonomic feature that distinguishes Eucommia from virtually all other medicinal trees.'),
  (10, 'Hardy Rubber Tree', 'Eucommia ulmoides', 'Bark', 'Geniposidic acid', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Characteristic iridoid glycoside contributing anti-inflammatory activity and supporting connective tissue metabolism.', NULL),
  (10, 'Hardy Rubber Tree', 'Eucommia ulmoides', 'Bark', 'Aucubin', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Major iridoid glycoside complementing geniposidic acid within the bark''s characteristic iridoid profile.', NULL),
  (10, 'Hardy Rubber Tree', 'Eucommia ulmoides', 'Bark', '(+)-Medioresinol', 'Lignan', 'Furofuran lignan', 'Moderate', 'Major', 'Characteristic lignan reinforcing the antioxidant and connective tissue-supportive chemistry of the bark.', NULL),
  (10, 'Hardy Rubber Tree', 'Eucommia ulmoides', 'Bark', 'Syringaresinol diglucoside', 'Lignan', 'Lignan glycoside', 'Moderate', 'Major', 'Characteristic lignan glycoside complementing pinoresinol diglucoside and contributing antioxidant and connective tissue-supportive activity.', NULL),
  (10, 'Hardy Rubber Tree', 'Eucommia ulmoides', 'Bark', 'Geniposide', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Characteristic iridoid glycoside reinforcing the bark''s distinctive iridoid chemistry and complementing geniposidic acid.', NULL),
  (1240, 'Heartsease', 'Viola tricolor', 'Aerial parts', 'Violanthin', 'Flavonoid', 'Flavone glycoside', 'High', 'Marker', 'Characteristic flavone glycoside contributing anti-inflammatory and antioxidant activity.', 'Viola tricolor combines a rich flavonoid profile with the distinctive cyclotides found throughout the genus Viola. These unusually stable cyclic peptides set heartsease apart from most medicinal herbs, while the flavonoids account for much of its traditional use in inflammatory skin and respiratory conditions.'),
  (1240, 'Heartsease', 'Viola tricolor', 'Aerial parts', 'Violutoside', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside reported from Viola tricolor, complementing violanthin within the herb''s anti-inflammatory flavonoid profile.', NULL),
  (1240, 'Heartsease', 'Viola tricolor', 'Aerial parts', 'Violanin', 'Anthocyanin', 'Anthocyanin glycoside', 'Moderate', 'Major', 'Characteristic anthocyanin contributing antioxidant activity and the distinctive floral pigmentation.', NULL),
  (1240, 'Heartsease', 'Viola tricolor', 'Aerial parts', 'Cycloviolacin O2', 'Peptide', 'Cyclotide', 'High', 'Marker', 'Representative cyclotide contributing to the species'' unique cyclic peptide chemistry and antimicrobial activity.', NULL),
  (1240, 'Heartsease', 'Viola tricolor', 'Aerial parts', 'Violanthin A', 'Peptide', 'Cyclotide', 'Moderate', 'Major', 'Representative cyclotide complementing cycloviolacin O2 and reinforcing the characteristic cyclic peptide chemistry of Viola.', NULL),
  (1240, 'Heartsease', 'Viola tricolor', 'Aerial parts', 'Vicenin-2', 'Flavonoid', 'Flavone C-glycoside', 'Moderate', 'Major', 'Characteristic C-glycosyl flavone complementing the principal flavonoid profile.', NULL),
  (831, 'Helichrysum', 'Helichrysum italicum', 'Flowering tops', 'Arzanol', 'Polyphenol', 'Phloroglucinol α-pyrone', 'High', 'Marker', 'Principal anti-inflammatory constituent and one of the defining chemotaxonomic markers of H. italicum.', 'Helichrysum italicum is chemically distinctive for combining anti-inflammatory phloroglucinols with an unusually complex essential oil rich in neryl acetate and diketones. This uncommon combination helps explain why the herb is valued both internally and topically, particularly for tissue repair, inflammation, and aromatic applications.'),
  (831, 'Helichrysum', 'Helichrysum italicum', 'Flowering tops', 'Neryl acetate', 'Terpenoid', 'Monoterpene ester', 'High', 'Marker', 'Major volatile constituent responsible for the characteristic aroma and an important contributor to antimicrobial activity.', NULL),
  (831, 'Helichrysum', 'Helichrysum italicum', 'Flowering tops', 'Italidione I', 'Terpenoid', 'Diketone sesquiterpene', 'High', 'Major', 'Characteristic diketone contributing to tissue-regenerative and anti-inflammatory properties of the essential oil.', NULL),
  (831, 'Helichrysum', 'Helichrysum italicum', 'Flowering tops', 'Italidione II', 'Terpenoid', 'Diketone sesquiterpene', 'Moderate', 'Major', 'Characteristic diketone complementing italidione I within the distinctive essential oil profile of H. italicum.', NULL),
  (831, 'Helichrysum', 'Helichrysum italicum', 'Flowering tops', 'γ-Curcumene', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Characteristic sesquiterpene complementing neryl acetate and the italidiones within the essential oil fraction.', NULL),
  (831, 'Helichrysum', 'Helichrysum italicum', 'Flowering tops', 'Gnaphaliin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Characteristic flavone complementing the volatile and phloroglucinol fractions with antioxidant activity.', NULL),
  (296, 'Hydrangea', 'Hydrangea arborescens', 'Root', 'Hydrangenol', 'Polyphenol', 'Dihydroisocoumarin', 'High', 'Marker', 'Principal dihydroisocoumarin contributing to the characteristic chemistry of hydrangea root and its traditional urinary tract applications.', 'Hydrangea arborescens is chemically distinguished by its dihydroisocoumarins, particularly hydrangenol and related thunberginols, which define the root''s medicinal chemistry. Although coumarins contribute supporting activity, the dihydroisocoumarin family provides the clearest chemotaxonomic identity and distinguishes hydrangea from most urinary tract herbs.'),
  (296, 'Hydrangea', 'Hydrangea arborescens', 'Root', 'Phyllodulcin', 'Polyphenol', 'Dihydroisocoumarin', 'High', 'Major', 'Characteristic dihydroisocoumarin complementing hydrangenol within the root''s distinctive phenolic profile.', NULL),
  (296, 'Hydrangea', 'Hydrangea arborescens', 'Root', 'Thunberginol A', 'Polyphenol', 'Dihydroisocoumarin', 'Moderate', 'Major', 'Bioactive dihydroisocoumarin contributing anti-inflammatory and antioxidant activity.', NULL),
  (296, 'Hydrangea', 'Hydrangea arborescens', 'Root', 'Thunberginol G', 'Polyphenol', 'Dihydroisocoumarin', 'Moderate', 'Major', 'Characteristic dihydroisocoumarin reinforcing the root''s species-specific phenolic chemistry.', NULL),
  (296, 'Hydrangea', 'Hydrangea arborescens', 'Root', 'Hydrangeic acid', 'Polyphenol', 'Dihydroisocoumarin derivative', 'Moderate', 'Major', 'Characteristic phenolic constituent complementing hydrangenol and reinforcing the species'' distinctive dihydroisocoumarin chemistry.', NULL),
  (296, 'Hydrangea', 'Hydrangea arborescens', 'Root', 'Hydrangenoside C', 'Glycoside', 'Dihydroisocoumarin glycoside', 'Moderate', 'Major', 'Characteristic glycosylated dihydroisocoumarin representing the native storage forms of the root''s principal phenolic constituents.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Pinocamphone', 'Terpenoid', 'Monoterpene ketone', 'High', 'Marker', 'Principal monoterpene ketone contributing to the herb''s characteristic aroma and expectorant activity.', 'Hyssopus officinalis is defined primarily by its volatile monoterpenes, especially pinocamphone and isopinocamphone, which distinguish it from most other Lamiaceae herbs. While flavonoids provide complementary antioxidant effects, the essential oil remains the dominant contributor to the herb''s traditional respiratory and antimicrobial applications.'),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Isopinocamphone', 'Terpenoid', 'Monoterpene ketone', 'High', 'Major', 'Characteristic monoterpene ketone complementing pinocamphone within the essential oil profile.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'β-Pinene', 'Terpenoid', 'Monoterpene', 'Moderate', 'Major', 'Major monoterpene contributing antimicrobial activity and the fresh resinous aroma of the volatile oil.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', '1,8-Cineole', 'Terpenoid', 'Monoterpene oxide', 'Moderate', 'Major', 'Oxygenated monoterpene contributing expectorant, antimicrobial, and respiratory-supportive activity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Marrubiin', 'Terpenoid', 'Labdane diterpene lactone', 'Moderate', 'Present', 'Bitter diterpene reported from hyssop, complementing the volatile oil with expectorant activity.', NULL),
  (53, 'Hyssop', 'Hyssopus officinalis', 'Aerial parts', 'Diosmin', 'Flavonoid', 'Flavone glycoside', 'Moderate', 'Major', 'Characteristic flavonoid glycoside contributing antioxidant and vascular-supportive activity.', NULL),
  (882, 'Indian Gooseberry', 'Phyllanthus emblica', 'Fruit', '1-O-Galloyl-β-D-glucose', 'Polyphenol', 'Gallotannin precursor', 'High', 'Major', 'Principal galloyl glucose and precursor to the characteristic hydrolyzable tannins of amla fruit.', 'Phyllanthus emblica is defined by its exceptionally rich hydrolyzable tannin chemistry, particularly the emblicanins, which account for much of its antioxidant and rejuvenative reputation. Although amla is widely known for its vitamin C content, its tannin fraction is far more distinctive chemotaxonomically and remains the dominant phytochemical feature.')
INSERT INTO herbal.constituent_profiles
  (herb_id, common_name, latin_name, plant_part, constituent, class, subclass, importance, status, notes, editorial_note)
VALUES
  (882, 'Indian Gooseberry', 'Phyllanthus emblica', 'Fruit', 'Emblicanin A', 'Tannin', 'Hydrolyzable tannin', 'High', 'Marker', 'Characteristic hydrolyzable tannin contributing antioxidant activity and one of the defining constituents of amla fruit.', NULL),
  (882, 'Indian Gooseberry', 'Phyllanthus emblica', 'Fruit', 'Emblicanin B', 'Tannin', 'Hydrolyzable tannin', 'High', 'Major', 'Companion hydrolyzable tannin complementing emblicanin A within the characteristic tannin fraction.', NULL),
  (882, 'Indian Gooseberry', 'Phyllanthus emblica', 'Fruit', 'Punigluconin', 'Tannin', 'Hydrolyzable tannin', 'Moderate', 'Major', 'Characteristic ellagitannin contributing antioxidant activity and reinforcing the fruit''s tannin chemistry.', NULL),
  (882, 'Indian Gooseberry', 'Phyllanthus emblica', 'Fruit', 'Pedunculagin', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Major ellagitannin complementing the emblicanins within the hydrolyzable tannin profile.', NULL),
  (882, 'Indian Gooseberry', 'Phyllanthus emblica', 'Fruit', 'Chebulagic acid', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Characteristic hydrolyzable tannin complementing the emblicanins and contributing to the fruit''s distinctive antioxidant chemistry.', NULL),
  (192, 'Ipecac', 'Carapichea ipecacuanha', 'Root', 'Emetine', 'Alkaloid', 'Isoquinoline alkaloid', 'High', 'Marker', 'Principal alkaloid responsible for the root''s emetic, amoebicidal, and expectorant activity.', 'Carapichea ipecacuanha is defined almost entirely by its emetine alkaloids, particularly emetine and cephaeline, which account for both its historical medicinal use and its toxicity. Few medicinal roots exhibit such a dominant single alkaloid family, making additional constituent classes of only secondary importance.'),
  (192, 'Ipecac', 'Carapichea ipecacuanha', 'Root', 'Cephaeline', 'Alkaloid', 'Isoquinoline alkaloid', 'High', 'Major', 'Major alkaloid complementing emetine and contributing strongly to the emetic activity of the root.', NULL),
  (192, 'Ipecac', 'Carapichea ipecacuanha', 'Root', 'Psychotrine', 'Alkaloid', 'Isoquinoline alkaloid', 'Moderate', 'Major', 'Biosynthetically related alkaloid contributing to the characteristic alkaloid profile of ipecac root.', NULL),
  (192, 'Ipecac', 'Carapichea ipecacuanha', 'Root', 'O-Methylpsychotrine', 'Alkaloid', 'Isoquinoline alkaloid', 'Moderate', 'Major', 'Characteristic minor alkaloid reinforcing the emetine alkaloid family.', NULL),
  (192, 'Ipecac', 'Carapichea ipecacuanha', 'Root', 'Ipecoside', 'Glycoside', 'Monoterpene glycoside', 'Low–Moderate', 'Present', 'Characteristic glycoside reported from the root, complementing the dominant alkaloid chemistry.', NULL),
  (192, 'Ipecac', 'Carapichea ipecacuanha', 'Root', '7''-O-Demethylemetine', 'Alkaloid', 'Isoquinoline alkaloid', 'Low–Moderate', 'Present', 'Naturally occurring minor alkaloid contributing to the diversity of the emetine alkaloid profile.', NULL),
  (956, 'Dan Shen', 'Salvia miltiorrhiza', 'Root and rhizome', 'Salvianolic acid B', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'High', 'Marker', 'Principal water-soluble phenolic marker associated with antioxidant and vascular effects.', 'Salvia miltiorrhiza is defined by its complementary tanshinones and salvianolic acids, which together contribute much of its anti-inflammatory, antioxidant, and cardiovascular activity. Unlike most medicinal sages, both the lipophilic and hydrophilic fractions are central to the herb''s characteristic chemistry.'),
  (956, 'Dan Shen', 'Salvia miltiorrhiza', 'Root and rhizome', 'Tanshinone IIA', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Major lipophilic tanshinone used as a quality-control marker for the root.', NULL),
  (956, 'Dan Shen', 'Salvia miltiorrhiza', 'Root and rhizome', 'Cryptotanshinone', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic tanshinone contributing to anti-inflammatory and cardiometabolic activity.', NULL),
