  (956, 'Dan Shen', 'Salvia miltiorrhiza', 'Root and rhizome', 'Dihydrotanshinone I', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Present', 'Potent tanshinone constituent contributing to antimicrobial and anti-inflammatory activity.', NULL),
  (956, 'Dan Shen', 'Salvia miltiorrhiza', 'Root and rhizome', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Low–Moderate', 'Present', 'Supporting phenolic acid contributing antioxidant activity within the hydrophilic fraction.', NULL),
  (593, 'False Solomon''s Seal', 'Maianthemum racemosum', 'Rhizome', 'Convallarin', 'Glycoside', 'Steroidal glycoside', 'High', 'Marker', 'Characteristic steroidal glycoside contributing to the rhizome''s traditional use and serving as a diagnostic constituent.', 'Maianthemum racemosum is defined primarily by its steroidal glycosides and sapogenins, which account for much of its traditional use as a connective tissue and musculoskeletal restorative. Because phytochemical studies of this species remain limited, the profile emphasizes its well-documented steroidal constituents rather than introducing less characteristic compound classes.'),
  (593, 'False Solomon''s Seal', 'Maianthemum racemosum', 'Rhizome', 'Diosgenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Major', 'Principal sapogenin released from steroidal glycosides and representative of the herb''s steroidal chemistry.', NULL),
