  (593, 'False Solomon''s Seal', 'Maianthemum racemosum', 'Rhizome', 'Ruscogenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Present', 'Steroidal sapogenin associated with the rhizome''s anti-inflammatory and connective tissue-supporting properties.', NULL),
  (14, 'Ginseng', 'Panax ginseng', 'Root', 'Ginsenoside Rb1', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal protopanaxadiol ginsenoside contributing to adaptogenic and immunomodulatory activity.', 'Panax ginseng is defined almost entirely by its ginsenosides, which account for much of its adaptogenic, immunomodulatory, neuroprotective, and metabolic activity. Because these triterpenoid saponins overwhelmingly distinguish the genus, the profile is composed exclusively of representative major ginsenosides rather than secondary constituent classes.'),
  (14, 'Ginseng', 'Panax ginseng', 'Root', 'Ginsenoside Rg1', 'Glycoside', 'Triterpenoid saponin', 'High', 'Marker', 'Principal protopanaxatriol ginsenoside associated with cognitive and neurophysiological effects.', NULL),
