  (1058, 'Life Root', 'Senecio aureus', 'Aerial parts', 'Senecionine', 'Alkaloid', 'Pyrrolizidine alkaloid', 'High', 'Marker', 'Principal hepatotoxic pyrrolizidine alkaloid that defines the herb''s chemistry and safety profile.', 'Senecio aureus is defined almost entirely by its pyrrolizidine alkaloids, which account for both its historical medicinal use and its well-established hepatotoxicity. Because this alkaloid family overwhelmingly distinguishes the species, additional constituent classes are of only secondary importance.'),
  (1058, 'Life Root', 'Senecio aureus', 'Aerial parts', 'Seneciphylline', 'Alkaloid', 'Pyrrolizidine alkaloid', 'High', 'Major', 'Characteristic pyrrolizidine alkaloid contributing to the herb''s toxicological significance.', NULL),
