  (1058, 'Life Root', 'Senecio aureus', 'Aerial parts', 'Senkirkine', 'Alkaloid', 'Pyrrolizidine alkaloid', 'Moderate', 'Present', 'Macrocyclic pyrrolizidine alkaloid contributing to the herb''s characteristic toxicological profile.', NULL),
  (163, 'Lily Of The Valley', 'Convallaria majalis', 'Aerial parts', 'Convallatoxin', 'Steroid', 'Cardiac glycoside', 'High', 'Marker', 'Principal cardiac glycoside responsible for much of the herb''s cardiotonic activity and toxicity.', 'Convallaria majalis is defined almost entirely by its cardiac glycosides, particularly convallatoxin, which account for both its cardiotonic activity and its narrow therapeutic margin. Few medicinal plants possess such a dominant cardenolide profile, making additional constituent classes of only secondary importance.'),
  (163, 'Lily Of The Valley', 'Convallaria majalis', 'Aerial parts', 'Convalloside', 'Steroid', 'Cardiac glycoside', 'High', 'Major', 'Characteristic cardiac glycoside contributing to the herb''s therapeutic and toxic effects.', NULL),
