  (980, 'Lomatium', 'Lomatium dissectum', 'Root', 'Falcarindiol', 'Polyacetylene', 'Polyacetylene', 'Moderate', 'Present', 'Characteristic polyacetylene contributing to the root''s antimicrobial chemistry and complementing the dominant furanocoumarin fraction.', NULL),
  (448, 'Ma Huang', 'Ephedra sinica', 'Stem', 'Ephedrine', 'Alkaloid', 'Phenethylamine alkaloid', 'High', 'Marker', 'Principal sympathomimetic alkaloid responsible for much of the herb''s bronchodilatory and stimulant activity.', 'Ephedra sinica is defined almost entirely by its ephedrine alkaloids, particularly ephedrine and pseudoephedrine, which account for much of its bronchodilatory, decongestant, and central nervous system stimulant activity. Few medicinal plants exhibit such a dominant phenethylamine alkaloid profile, making additional constituent classes of only secondary importance.'),
  (448, 'Ma Huang', 'Ephedra sinica', 'Stem', 'Pseudoephedrine', 'Alkaloid', 'Phenethylamine alkaloid', 'High', 'Marker', 'Major alkaloid contributing bronchodilatory and nasal decongestant activity.', NULL),
