  (107, 'Marjoram', 'Origanum majorana', 'Aerial parts', 'Carvacrol', 'Terpenoid', 'Monoterpenoid phenol', 'Low–Moderate', 'Present', 'Minor constituent that complements the herb''s antimicrobial activity in some chemotypes.', NULL),
  (193, 'Mouse Ear', 'Hieracium pilosella', 'Aerial parts', 'Umbelliferone', 'Coumarin', 'Simple coumarin', 'High', 'Marker', 'Principal coumarin contributing to the herb''s mild diuretic and antimicrobial activity.', 'Hieracium pilosella is defined primarily by its coumarins and caffeoylquinic acids, which account for much of its traditional diuretic, urinary antiseptic, and anti-inflammatory activity. The flavones provide complementary antioxidant support while remaining secondary to the herb''s characteristic phenolic chemistry.'),
  (193, 'Mouse Ear', 'Hieracium pilosella', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'High', 'Major', 'Major phenolic contributing antioxidant activity and supporting the herb''s traditional urinary applications.', NULL),
  (193, 'Mouse Ear', 'Hieracium pilosella', 'Aerial parts', 'Luteolin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Characteristic flavone contributing anti-inflammatory and antioxidant activity.', NULL),
  (193, 'Mouse Ear', 'Hieracium pilosella', 'Aerial parts', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Present', 'Supporting flavone contributing anti-inflammatory activity.', NULL),
  (193, 'Mouse Ear', 'Hieracium pilosella', 'Aerial parts', 'Isochlorogenic acid A', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Present', 'Dicaffeoylquinic acid supporting antioxidant and urinary tract activity.', NULL),
  (221, 'Narrow-Leaf Echinacea', 'Echinacea angustifolia', 'Root', 'Echinacoside', 'Polyphenol', 'Phenylethanoid glycoside', 'High', 'Marker', 'Principal phenylethanoid glycoside contributing antioxidant activity and serving as a characteristic marker of the root.', 'Echinacea angustifolia is defined by its complementary alkamides and caffeic acid derivatives, which together account for much of its immunomodulatory, anti-inflammatory, and antimicrobial activity. The inclusion of arabinogalactan represents the herb''s characteristic polysaccharide fraction while preserving the dominant lipophilic and phenolic chemistry.'),
  (221, 'Narrow-Leaf Echinacea', 'Echinacea angustifolia', 'Root', 'Cynarin', 'Polyphenol', 'Phenylpropanoid ester', 'High', 'Major', 'Characteristic dicaffeoyl derivative contributing immunomodulatory and antioxidant activity.', NULL),
  (221, 'Narrow-Leaf Echinacea', 'Echinacea angustifolia', 'Root', 'Dodeca-2E,4E,8Z,10E-tetraenoic acid isobutylamide', 'Lipid', 'Alkamide', 'High', 'Marker', 'Representative alkamide contributing to immunomodulatory activity and the characteristic tingling sensation.', NULL),
  (221, 'Narrow-Leaf Echinacea', 'Echinacea angustifolia', 'Root', 'Undeca-2E,4E-diene-8,10-diynoic acid isobutylamide', 'Lipid', 'Alkamide', 'Moderate', 'Major', 'Characteristic polyacetylenic alkamide supporting the defining lipophilic fraction.', NULL),
  (221, 'Narrow-Leaf Echinacea', 'Echinacea angustifolia', 'Root', 'Dodeca-2E,4E-dienoic acid isobutylamide', 'Lipid', 'Alkamide', 'Moderate', 'Major', 'Major alkamide representative of the diverse isobutylamide profile.', NULL),
  (221, 'Narrow-Leaf Echinacea', 'Echinacea angustifolia', 'Root', 'Arabinogalactan', 'Polysaccharide', 'Arabinogalactan', 'Moderate', 'Present', 'High-molecular-weight polysaccharide contributing complementary immunomodulatory activity.', NULL),
  (NULL, 'Neroli', 'Citrus × aurantium var. amara', 'Flower', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene alcohol contributing the characteristic floral aroma and calming activity.', 'Citrus × aurantium var. amara flowers are defined by their oxygenated monoterpenes, particularly linalool and linalyl acetate, which account for much of neroli''s characteristic fragrance, calming effects, and antimicrobial activity. The supporting sesquiterpene alcohols reinforce this distinctive floral chemistry without overshadowing the dominant volatile monoterpene profile.'),
  (NULL, 'Neroli', 'Citrus × aurantium var. amara', 'Flower', 'Linalyl acetate', 'Terpenoid', 'Monoterpene ester', 'High', 'Marker', 'Major ester contributing the characteristic fragrance and relaxing properties of the essential oil.', NULL),
  (NULL, 'Neroli', 'Citrus × aurantium var. amara', 'Flower', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic citrus monoterpene contributing aromatic and digestive activity.', NULL),
  (NULL, 'Neroli', 'Citrus × aurantium var. amara', 'Flower', 'β-Myrcene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic monoterpene contributing to the fresh citrus aroma and complementing the dominant oxygenated monoterpenes.', NULL),
  (NULL, 'Neroli', 'Citrus × aurantium var. amara', 'Flower', 'Nerolidol', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Sesquiterpene alcohol contributing calming and antimicrobial activity.', NULL),
  (NULL, 'Neroli', 'Citrus × aurantium var. amara', 'Flower', 'Farnesol', 'Terpenoid', 'Sesquiterpene', 'Low–Moderate', 'Present', 'Characteristic sesquiterpene alcohol contributing floral aroma and antimicrobial effects.', NULL),
  (NULL, 'Oak', 'Quercus robur', 'Bark', 'Vescalagin', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Principal ellagitannin contributing the bark''s pronounced astringent and antioxidant activity.', 'Quercus robur is defined by its exceptionally rich ellagitannin chemistry, particularly vescalagin and castalagin, which account for much of its astringent, antimicrobial, and tissue-toning activity. The profile emphasizes these characteristic hydrolyzable tannins while limiting inclusion of simpler phenolics to representative degradation products.'),
  (NULL, 'Oak', 'Quercus robur', 'Bark', 'Castalagin', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Characteristic ellagitannin widely recognized as a major constituent of oak bark.', NULL),
  (NULL, 'Oak', 'Quercus robur', 'Bark', 'Roburin A', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Representative C-glycosidic ellagitannin contributing to the herb''s characteristic tannin profile.', NULL),
  (NULL, 'Oak', 'Quercus robur', 'Bark', 'Roburin D', 'Tannin', 'Ellagitannin', 'Moderate', 'Present', 'Characteristic ellagitannin supporting the dominant hydrolyzable tannin fraction.', NULL),
  (NULL, 'Oak', 'Quercus robur', 'Bark', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Present', 'Oxidative product of ellagitannins contributing antioxidant activity and serving as a useful analytical marker.', NULL),
  (NULL, 'Oak', 'Quercus robur', 'Bark', 'Gallic acid', 'Polyphenol', 'Phenolic acid', 'Low–Moderate', 'Present', 'Supporting phenolic acid associated with the hydrolyzable tannin fraction.', NULL),
  (406, 'Oregano', 'Origanum vulgare', 'Aerial parts', 'Carvacrol', 'Terpenoid', 'Monoterpenoid phenol', 'High', 'Marker', 'Principal phenolic monoterpene responsible for much of the herb''s antimicrobial and antioxidant activity.', 'Origanum vulgare is defined primarily by its phenolic monoterpenes, especially carvacrol and thymol, which account for much of its antimicrobial, antioxidant, and digestive activity. Rosmarinic acid provides a complementary non-volatile phenolic fraction, while the remaining terpenes support the herb''s characteristic aromatic chemistry without overshadowing its defining monoterpenes.'),
  (406, 'Oregano', 'Origanum vulgare', 'Aerial parts', 'Thymol', 'Terpenoid', 'Monoterpenoid phenol', 'High', 'Major', 'Characteristic phenolic monoterpene contributing antimicrobial and preservative properties.', NULL),
  (406, 'Oregano', 'Origanum vulgare', 'Aerial parts', 'p-Cymene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Biosynthetic precursor that complements the dominant phenolic monoterpenes and contributes aromatic activity.', NULL),
  (406, 'Oregano', 'Origanum vulgare', 'Aerial parts', 'γ-Terpinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Monoterpene precursor supporting the biosynthesis of carvacrol and thymol while contributing antioxidant activity.', NULL),
  (406, 'Oregano', 'Origanum vulgare', 'Aerial parts', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Moderate', 'Major', 'Principal non-volatile phenolic contributing antioxidant and anti-inflammatory activity.', NULL),
  (406, 'Oregano', 'Origanum vulgare', 'Aerial parts', 'β-Caryophyllene', 'Terpenoid', 'Sesquiterpene', 'Low–Moderate', 'Present', 'Characteristic sesquiterpene contributing anti-inflammatory activity and complementing the dominant monoterpene profile.', NULL),
  (1402, 'Parsley Piert', 'Aphanes arvensis', 'Aerial parts', 'Agrimoniin', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Principal ellagitannin contributing the herb''s astringent and antioxidant activity.', 'Aphanes arvensis is defined primarily by its hydrolyzable tannins, particularly ellagitannins, which account for much of its astringent, antioxidant, and traditional urinary tract activity. The flavonols provide complementary antioxidant effects while remaining secondary to the herb''s dominant tannin chemistry.'),
  (1402, 'Parsley Piert', 'Aphanes arvensis', 'Aerial parts', 'Pedunculagin', 'Tannin', 'Ellagitannin', 'High', 'Major', 'Characteristic ellagitannin supporting the herb''s traditional urinary applications.', NULL),
  (1402, 'Parsley Piert', 'Aphanes arvensis', 'Aerial parts', 'Tellimagrandin I', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Representative hydrolyzable tannin contributing to the herb''s characteristic tannin profile.', NULL),
  (1402, 'Parsley Piert', 'Aphanes arvensis', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Supporting flavonol contributing antioxidant activity.', NULL),
  (1402, 'Parsley Piert', 'Aphanes arvensis', 'Aerial parts', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Characteristic flavonol complementing the tannin-rich phenolic fraction.', NULL),
  (188, 'Partridgeberry', 'Mitchella repens', 'Aerial parts', 'Asperuloside', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid glycoside contributing to the herb''s traditional uterine and anti-inflammatory activity.', 'Mitchella repens is defined primarily by its iridoid glycosides, especially asperuloside, which account for much of its traditional anti-inflammatory and female reproductive applications. Phenolic acids and flavonoids provide complementary antioxidant activity while remaining secondary to the herb''s characteristic iridoid chemistry.'),
  (188, 'Partridgeberry', 'Mitchella repens', 'Aerial parts', 'Deacetylasperulosidic acid', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Characteristic iridoid glycoside supporting the herb''s defining iridoid chemistry.', NULL),
  (188, 'Partridgeberry', 'Mitchella repens', 'Aerial parts', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Principal phenolic contributing antioxidant activity and complementing the iridoid fraction.', NULL),
  (188, 'Partridgeberry', 'Mitchella repens', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Present', 'Characteristic flavonoid supporting vascular and antioxidant activity.', NULL),
  (188, 'Partridgeberry', 'Mitchella repens', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Supporting flavonol contributing complementary antioxidant effects.', NULL),
  (36, 'Pasqueflower', 'Pulsatilla vulgaris', 'Aerial parts', 'Protoanemonin', 'Terpenoid', 'Iridoid ester', 'High', 'Marker', 'Reactive constituent responsible for much of the fresh herb''s acrid, antimicrobial, and vesicant activity.', 'Pulsatilla vulgaris is defined by its unstable ranunculin-derived constituents, particularly protoanemonin and anemonin, which account for much of its antimicrobial activity and the fresh herb''s acridity. The accompanying triterpenoid saponins provide complementary anti-inflammatory effects but remain secondary to this distinctive chemistry.'),
  (36, 'Pasqueflower', 'Pulsatilla vulgaris', 'Aerial parts', 'Anemonin', 'Terpenoid', 'Iridoid ester', 'High', 'Major', 'Dimerization product of protoanemonin contributing antimicrobial activity and characteristic chemistry.', NULL),
  (36, 'Pasqueflower', 'Pulsatilla vulgaris', 'Aerial parts', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Major', 'Principal triterpenoid aglycone representative of the herb''s characteristic saponin fraction.', NULL),
  (36, 'Pasqueflower', 'Pulsatilla vulgaris', 'Aerial parts', 'Pulsatilloside A', 'Glycoside', 'Triterpenoid saponin', 'Moderate', 'Major', 'Characteristic triterpenoid saponin contributing anti-inflammatory activity.', NULL),
  (36, 'Pasqueflower', 'Pulsatilla vulgaris', 'Aerial parts', 'Pulsatilloside D', 'Glycoside', 'Triterpenoid saponin', 'Low–Moderate', 'Present', 'Representative saponin supporting the herb''s characteristic triterpenoid fraction.', NULL),
  (320, 'Peach', 'Prunus persica', 'Leaf', 'Amygdalin', 'Glycoside', 'Cyanogenic glycoside', 'High', 'Marker', 'Principal cyanogenic glycoside responsible for much of the herb''s traditional activity and toxicological significance.', 'Prunus persica leaves are defined primarily by their cyanogenic glycosides, especially amygdalin and prunasin, which account for much of their traditional medicinal use and toxicological significance. The accompanying phenolic constituents provide complementary antioxidant activity while remaining secondary to the herb''s characteristic cyanogenic chemistry.'),
  (320, 'Peach', 'Prunus persica', 'Leaf', 'Prunasin', 'Glycoside', 'Cyanogenic glycoside', 'High', 'Major', 'Characteristic cyanogenic glycoside contributing to the herb''s defining chemistry.', NULL),
  (320, 'Peach', 'Prunus persica', 'Leaf', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Moderate', 'Major', 'Principal phenolic contributing antioxidant activity.', NULL),
  (320, 'Peach', 'Prunus persica', 'Leaf', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Characteristic flavonol contributing anti-inflammatory and antioxidant activity.', NULL),
  (320, 'Peach', 'Prunus persica', 'Leaf', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Supporting flavonol complementing the leaf''s phenolic profile.', NULL),
  (135, 'Pennyroyal', 'Mentha pulegium', 'Aerial parts', 'Pulegone', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene ketone responsible for much of the herb''s characteristic aroma, insect-repellent properties, and hepatotoxicity.', 'Mentha pulegium is defined primarily by its monoterpene ketones, especially pulegone, which account for much of its aromatic, insect-repellent, and emmenagogue activity as well as its well-recognized hepatotoxicity. Rosmarinic acid provides a complementary non-volatile phenolic fraction while remaining secondary to the herb''s defining volatile chemistry.'),
  (135, 'Pennyroyal', 'Mentha pulegium', 'Aerial parts', 'Menthone', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Characteristic monoterpene ketone contributing mint aroma and supporting the volatile profile.', NULL),
  (135, 'Pennyroyal', 'Mentha pulegium', 'Aerial parts', 'Isomenthone', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Companion monoterpene ketone characteristic of pennyroyal essential oil.', NULL),
  (135, 'Pennyroyal', 'Mentha pulegium', 'Aerial parts', 'Piperitenone', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Monoterpene ketone contributing to the characteristic volatile chemistry.', NULL),
  (135, 'Pennyroyal', 'Mentha pulegium', 'Aerial parts', 'Piperitone', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic monoterpene ketone supporting the herb''s distinctive aroma.', NULL),
  (135, 'Pennyroyal', 'Mentha pulegium', 'Aerial parts', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Low–Moderate', 'Present', 'Principal non-volatile phenolic contributing antioxidant activity and complementing the dominant monoterpene fraction.', NULL),
  (55, 'Peppermint', 'Mentha × piperita', 'Leaf', 'Menthol', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene alcohol responsible for much of the herb''s cooling, antispasmodic, and analgesic activity.', 'Mentha × piperita is defined primarily by its menthol-rich monoterpenes, which account for much of its cooling, digestive, antispasmodic, and antimicrobial activity. Rosmarinic acid provides the principal non-volatile phenolic fraction while remaining secondary to the herb''s characteristic volatile chemistry.'),
  (55, 'Peppermint', 'Mentha × piperita', 'Leaf', 'Menthone', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Major monoterpene ketone contributing to the characteristic aroma and digestive activity.', NULL),
  (55, 'Peppermint', 'Mentha × piperita', 'Leaf', 'Menthyl acetate', 'Terpenoid', 'Monoterpene ester', 'Moderate', 'Major', 'Characteristic ester contributing to the herb''s aroma and flavor profile.', NULL),
  (55, 'Peppermint', 'Mentha × piperita', 'Leaf', '1,8-Cineole', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Oxygenated monoterpene contributing respiratory and antimicrobial activity.', NULL),
  (55, 'Peppermint', 'Mentha × piperita', 'Leaf', 'Menthofuran', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic peppermint monoterpene formed during menthol biosynthesis and useful as a chemotaxonomic marker.', NULL),
  (55, 'Peppermint', 'Mentha × piperita', 'Leaf', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Moderate', 'Major', 'Principal non-volatile phenolic contributing antioxidant and anti-inflammatory activity.', NULL),
  (NULL, 'Periwinkle', 'Vinca minor', 'Aerial parts', 'Vincamine', 'Alkaloid', 'Monoterpene indole alkaloid', 'High', 'Marker', 'Principal indole alkaloid associated with cerebral vasodilatory and neurovascular activity.', 'Vinca minor is defined almost entirely by its monoterpene indole alkaloids, particularly vincamine, which account for much of its historical cerebrovascular and neurovascular use. Few medicinal herbs possess such a dominant indole alkaloid profile, making additional constituent classes of only secondary importance.'),
  (NULL, 'Periwinkle', 'Vinca minor', 'Aerial parts', 'Vincamajine', 'Alkaloid', 'Monoterpene indole alkaloid', 'High', 'Major', 'Characteristic monoterpene indole alkaloid contributing to the herb''s defining alkaloid profile.', NULL),
  (NULL, 'Periwinkle', 'Vinca minor', 'Aerial parts', 'Eburnamonine', 'Alkaloid', 'Monoterpene indole alkaloid', 'Moderate', 'Major', 'Representative indole alkaloid supporting the characteristic vinca alkaloid fraction.', NULL),
  (NULL, 'Periwinkle', 'Vinca minor', 'Aerial parts', 'Vincadifformine', 'Alkaloid', 'Monoterpene indole alkaloid', 'Moderate', 'Present', 'Characteristic indole alkaloid contributing to the species'' distinctive alkaloid chemistry.', NULL),
  (NULL, 'Periwinkle', 'Vinca minor', 'Aerial parts', 'Akuammicine', 'Alkaloid', 'Monoterpene indole alkaloid', 'Low–Moderate', 'Present', 'Biosynthetically important indole alkaloid representative of the genus.', NULL),
  (228, 'Pilewort', 'Ficaria verna', 'Fresh aerial parts', 'Protoanemonin', 'Lactone', 'Unsaturated lactone', 'High', 'Marker', 'Reactive constituent responsible for much of the fresh herb''s acridity and vesicant activity.', 'Ficaria verna is defined by its ranunculin-derived lactones, particularly protoanemonin, which account for much of the fresh herb''s acridity, antimicrobial activity, and irritant properties. Although flavonoids and triterpenoids are present, the unstable ranunculin chemistry overwhelmingly distinguishes the species and dominates its medicinal and toxicological profile.'),
  (228, 'Pilewort', 'Ficaria verna', 'Fresh aerial parts', 'Anemonin', 'Lactone', 'Unsaturated lactone', 'High', 'Major', 'Dimerization product of protoanemonin contributing antimicrobial activity and characteristic chemistry.', NULL),
  (228, 'Pilewort', 'Ficaria verna', 'Fresh aerial parts', 'Ranunculin', 'Glycoside', 'Ranunculin glycoside', 'Moderate', 'Major', 'Glycosidic precursor of protoanemonin that defines the chemistry of fresh plant material.', NULL),
  (228, 'Pilewort', 'Ficaria verna', 'Fresh aerial parts', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'Moderate', 'Present', 'Representative triterpenoid contributing to the herb''s supporting chemistry.', NULL),
  (228, 'Pilewort', 'Ficaria verna', 'Fresh aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Supporting flavonoid contributing antioxidant activity.', NULL),
  (NULL, 'Pill-Bearing Spurge', 'Euphorbia lathyris', 'Seed', 'Euphorbia factor L₃', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Representative lathyrane diterpene ester contributing to the seed''s characteristic irritant and purgative activity.', 'Euphorbia lathyris is defined almost entirely by its lathyrane diterpenoids and diterpene esters, which account for much of its drastic purgative activity and irritant properties. Few medicinal plants exhibit such a dominant diterpenoid profile, making additional constituent classes of only secondary importance.'),
  (NULL, 'Pill-Bearing Spurge', 'Euphorbia lathyris', 'Seed', 'Lathyrol', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Characteristic lathyrane diterpenoid that defines the species chemically.', NULL),
  (NULL, 'Pill-Bearing Spurge', 'Euphorbia lathyris', 'Seed', 'Jolkinolide B', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic diterpenoid contributing to the herb''s irritant and biological activity.', NULL),
  (NULL, 'Pill-Bearing Spurge', 'Euphorbia lathyris', 'Seed', 'Euphorbia factor L₁', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Representative diterpene ester contributing to the seed''s characteristic irritant chemistry.', NULL),
  (NULL, 'Pill-Bearing Spurge', 'Euphorbia lathyris', 'Seed', 'Euphorbia factor L₂', 'Terpenoid', 'Diterpenoid', 'Low–Moderate', 'Present', 'Characteristic diterpene ester supporting the defining diterpenoid profile.', NULL),
  (NULL, 'Poppy', 'Papaver somniferum', 'Latex', 'Morphine', 'Alkaloid', 'Morphinan alkaloid', 'High', 'Marker', 'Principal analgesic alkaloid responsible for much of the latex''s pharmacological activity.', 'Papaver somniferum is defined almost entirely by its isoquinoline alkaloids, particularly morphine, codeine, and thebaine, which account for much of its analgesic, antitussive, antispasmodic, and central nervous system activity. Few medicinal plants possess such a chemically dominant alkaloid profile, making additional constituent classes of only secondary importance.'),
  (NULL, 'Poppy', 'Papaver somniferum', 'Latex', 'Codeine', 'Alkaloid', 'Morphinan alkaloid', 'High', 'Major', 'Major analgesic alkaloid contributing antitussive and analgesic activity.', NULL),
  (NULL, 'Poppy', 'Papaver somniferum', 'Latex', 'Thebaine', 'Alkaloid', 'Morphinan alkaloid', 'Moderate', 'Major', 'Biosynthetically important alkaloid with stimulant pharmacology and pharmaceutical significance.', NULL),
  (NULL, 'Poppy', 'Papaver somniferum', 'Latex', 'Noscapine', 'Alkaloid', 'Phthalide isoquinoline alkaloid', 'Moderate', 'Major', 'Characteristic alkaloid contributing antitussive activity and distinguishing the alkaloid profile.', NULL),
  (NULL, 'Poppy', 'Papaver somniferum', 'Latex', 'Papaverine', 'Alkaloid', 'Benzylisoquinoline alkaloid', 'Moderate', 'Major', 'Smooth muscle relaxant alkaloid contributing antispasmodic activity.', NULL),
  (NULL, 'Poppy', 'Papaver somniferum', 'Latex', 'Narceine', 'Alkaloid', 'Benzylisoquinoline alkaloid', 'Low–Moderate', 'Present', 'Minor characteristic alkaloid completing the representative opium alkaloid profile.', NULL),
  (274, 'Privet', 'Ligustrum lucidum', 'Fruit', 'Oleanolic acid', 'Terpenoid', 'Oleanane triterpenoid', 'High', 'Marker', 'Principal triterpenoid contributing hepatoprotective and anti-inflammatory activity.', 'Ligustrum lucidum is defined by its complementary secoiridoid glycosides and pentacyclic triterpenoids, which account for much of its hepatoprotective, immunomodulatory, and antioxidant activity. The inclusion of specnuezhenide highlights the distinctive Ligustrum secoiridoid chemistry while preserving the herb''s dominant glycoside profile.'),
  (274, 'Privet', 'Ligustrum lucidum', 'Fruit', 'Ursolic acid', 'Terpenoid', 'Ursane triterpenoid', 'High', 'Major', 'Characteristic triterpenoid complementing the oleanane fraction and contributing immunomodulatory activity.', NULL),
  (274, 'Privet', 'Ligustrum lucidum', 'Fruit', 'Nuezhenide', 'Glycoside', 'Secoiridoid glycoside', 'High', 'Marker', 'Characteristic secoiridoid glycoside widely used as an analytical marker for the fruit.', NULL),
  (274, 'Privet', 'Ligustrum lucidum', 'Fruit', 'Oleuropein', 'Glycoside', 'Secoiridoid glycoside', 'Moderate', 'Major', 'Representative secoiridoid contributing antioxidant and anti-inflammatory activity.', NULL),
  (274, 'Privet', 'Ligustrum lucidum', 'Fruit', 'Ligustroside', 'Glycoside', 'Secoiridoid glycoside', 'Moderate', 'Major', 'Characteristic secoiridoid supporting the herb''s defining glycoside fraction.', NULL),
  (274, 'Privet', 'Ligustrum lucidum', 'Fruit', 'Specnuezhenide', 'Glycoside', 'Secoiridoid glycoside', 'Moderate', 'Present', 'Characteristic secoiridoid unique to Ligustrum species and contributing to the fruit''s tonic activity.', NULL),
  (183, 'Pumpkin', 'Cucurbita pepo', 'Seed', 'Cucurbitin', 'Nitrogenous compound', 'Amino acid derivative', 'High', 'Marker', 'Characteristic non-protein amino acid associated with the seed''s traditional anthelmintic activity.', 'Cucurbita pepo seeds are defined primarily by their distinctive Δ7-phytosterols and cucurbitin, which account for much of their traditional anthelmintic and prostate-supportive activity. Although the seeds are rich in common fatty acids, the characteristic sterol profile is far more chemotaxonomically distinctive and therefore forms the basis of this entry.'),
  (183, 'Pumpkin', 'Cucurbita pepo', 'Seed', 'Δ7-Stigmastenol', 'Sterol', 'Phytosterol', 'High', 'Marker', 'Characteristic Δ7-phytosterol distinguishing pumpkin seed from many other edible seeds.', NULL),
  (183, 'Pumpkin', 'Cucurbita pepo', 'Seed', 'Spinasterol', 'Sterol', 'Phytosterol', 'High', 'Major', 'Principal phytosterol contributing to the characteristic sterol profile and supporting prostate health applications.', NULL),
  (183, 'Pumpkin', 'Cucurbita pepo', 'Seed', 'Schottenol', 'Sterol', 'Phytosterol', 'Moderate', 'Major', 'Representative Δ7-phytosterol complementing the dominant sterol fraction.', NULL)
