  (183, 'Pumpkin', 'Cucurbita pepo', 'Seed', 'Δ7,25-Stigmastadienol', 'Sterol', 'Phytosterol', 'Moderate', 'Major', 'Characteristic Δ7-phytosterol contributing to the distinctive sterol profile of pumpkin seed.', NULL),
  (183, 'Pumpkin', 'Cucurbita pepo', 'Seed', 'Δ7-Avenasterol', 'Sterol', 'Phytosterol', 'Moderate', 'Present', 'Representative Δ7-phytosterol complementing the dominant sterol fraction associated with prostate-supportive activity.', NULL),
  (155, 'Raspberry', 'Rubus idaeus', 'Leaf', 'Sanguiin H-6', 'Tannin', 'Ellagitannin', 'High', 'Marker', 'Principal ellagitannin contributing much of the leaf''s astringent and antioxidant activity.', 'Rubus idaeus leaf is defined primarily by its ellagitannins, especially sanguiin H-6 and lambertianin C, which account for much of its astringent, antioxidant, and traditional uterine tonic activity. Flavonoids and caffeoylquinic acids provide complementary phenolic support while remaining secondary to the herb''s dominant tannin chemistry.'),
  (155, 'Raspberry', 'Rubus idaeus', 'Leaf', 'Lambertianin C', 'Tannin', 'Ellagitannin', 'High', 'Major', 'Characteristic high-molecular-weight ellagitannin reinforcing the herb''s astringent properties.', NULL),
  (155, 'Raspberry', 'Rubus idaeus', 'Leaf', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Moderate', 'Major', 'Representative hydrolysis product of ellagitannins contributing antioxidant activity.', NULL),
  (155, 'Raspberry', 'Rubus idaeus', 'Leaf', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Characteristic flavonol contributing complementary anti-inflammatory and antioxidant activity.', NULL),
  (155, 'Raspberry', 'Rubus idaeus', 'Leaf', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Low–Moderate', 'Present', 'Supporting flavonol complementing the leaf''s phenolic profile.', NULL),
  (155, 'Raspberry', 'Rubus idaeus', 'Leaf', 'Chlorogenic acid', 'Polyphenol', 'Caffeoylquinic acid', 'Low–Moderate', 'Present', 'Representative caffeoylquinic acid providing a complementary phenolic fraction.', NULL),
  (981, 'Red Root', 'Ceanothus americanus', 'Root / root bark', 'Ceanothic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'High', 'Marker', 'Characteristic triterpenoid contributing antimicrobial activity and defining the root chemistry.', 'Ceanothus americanus root is best represented by ceanothane-type triterpenoids, especially ceanothic acid and ceanothetric acid, which account for its antimicrobial and tissue-toning reputation. The two maesopsin flavanonols are retained because they are species-documented, while vague tannins, “ceanothine,” and unsupported anthraquinones are omitted.'),
  (981, 'Red Root', 'Ceanothus americanus', 'Root / root bark', 'Ceanothetric acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'High', 'Marker', 'Characteristic triterpenoid with documented antimicrobial activity against oral pathogens.', NULL),
  (981, 'Red Root', 'Ceanothus americanus', 'Root / root bark', '27-Hydroxyceanothic acid', 'Terpenoid', 'Pentacyclic triterpenoid', 'Moderate', 'Major', 'Oxygenated ceanothane-type triterpenoid supporting the root’s diagnostic triterpenoid profile.', NULL),
  (981, 'Red Root', 'Ceanothus americanus', 'Root / root bark', 'Maesopsin', 'Flavonoid', 'Flavanonol', 'Low–Moderate', 'Present', 'Species-documented flavanonol providing a minor supporting phenolic fraction.', NULL),
  (981, 'Red Root', 'Ceanothus americanus', 'Root / root bark', 'Maesopsin-6-O-glucoside', 'Flavonoid', 'Flavanonol glycoside', 'Low', 'Reported', 'Glycosylated derivative reported from the species but secondary to the defining ceanothane triterpenoids.', NULL),
  (956, 'Red Sage', 'Salvia miltiorrhiza', 'Root and rhizome', 'Salvianolic acid B', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'High', 'Marker', 'Principal water-soluble phenolic contributing antioxidant and vasoprotective activity.', 'Salvia miltiorrhiza is defined by complementary tanshinones and salvianolic acids, which together account for much of its anti-inflammatory, antioxidant, vasoprotective, and microcirculatory activity. The coexistence of abundant lipophilic diterpenoids and hydrophilic phenolic acids distinguishes Red Sage from most other medicinal Salvia species.'),
  (956, 'Red Sage', 'Salvia miltiorrhiza', 'Root and rhizome', 'Tanshinone IIA', 'Terpenoid', 'Diterpenoid', 'High', 'Marker', 'Principal lipophilic diterpenoid responsible for much of the herb''s anti-inflammatory and microcirculatory activity.', NULL),
  (956, 'Red Sage', 'Salvia miltiorrhiza', 'Root and rhizome', 'Cryptotanshinone', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Characteristic tanshinone contributing anti-inflammatory and antimicrobial activity.', NULL),
  (956, 'Red Sage', 'Salvia miltiorrhiza', 'Root and rhizome', 'Tanshinone I', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Major', 'Representative diterpenoid supporting the defining tanshinone fraction.', NULL),
  (956, 'Red Sage', 'Salvia miltiorrhiza', 'Root and rhizome', 'Dihydrotanshinone I', 'Terpenoid', 'Diterpenoid', 'Moderate', 'Present', 'Characteristic diterpenoid complementing the principal tanshinones.', NULL),
  (956, 'Red Sage', 'Salvia miltiorrhiza', 'Root and rhizome', 'Rosmarinic acid', 'Polyphenol', 'Hydroxycinnamic acid derivative', 'Low–Moderate', 'Present', 'Representative supporting phenolic contributing complementary antioxidant activity.', NULL),
  (223, 'Rehmannia', 'Rehmannia glutinosa', 'Root', 'Catalpol', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid glycoside responsible for much of the herb''s nephroprotective and anti-inflammatory activity.', 'Rehmannia glutinosa is defined primarily by its iridoid glycosides, especially catalpol and the rehmanniosides, which account for much of its traditional kidney-tonifying, anti-inflammatory, and neuroprotective activity. Phenylethanoid glycosides provide a complementary antioxidant fraction while remaining secondary to the herb''s defining iridoid chemistry.'),
  (223, 'Rehmannia', 'Rehmannia glutinosa', 'Root', 'Rehmannioside D', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Characteristic iridoid glycoside representative of the rehmannioside fraction.', NULL),
  (223, 'Rehmannia', 'Rehmannia glutinosa', 'Root', 'Acteoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Moderate', 'Major', 'Major phenylethanoid glycoside contributing antioxidant and neuroprotective activity.', NULL),
  (223, 'Rehmannia', 'Rehmannia glutinosa', 'Root', 'Rehmannioside A', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Present', 'Characteristic iridoid glycoside complementing catalpol and representing the distinctive rehmannioside family.', NULL),
  (223, 'Rehmannia', 'Rehmannia glutinosa', 'Root', 'Ajugol', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Present', 'Characteristic iridoid glycoside complementing the dominant catalpol chemistry.', NULL),
  (223, 'Rehmannia', 'Rehmannia glutinosa', 'Root', 'Verbascoside', 'Polyphenol', 'Phenylethanoid glycoside', 'Low–Moderate', 'Present', 'Representative phenylethanoid glycoside reinforcing the herb''s antioxidant profile.', NULL),
  (11, 'Reishi Mushroom', 'Ganoderma lingzhi', 'Fruiting body', 'Ganoderic acid A', 'Terpenoid', 'Triterpenoid', 'High', 'Marker', 'Principal lanostane triterpenoid contributing anti-inflammatory and hepatoprotective activity.', 'Ganoderma lingzhi is defined by complementary lanostane triterpenoids and β-glucans, which together account for much of its immunomodulatory, anti-inflammatory, hepatoprotective, and adaptogenic activity. Both constituent families are represented because neither alone adequately captures the distinctive medicinal chemistry of Reishi.'),
  (11, 'Reishi Mushroom', 'Ganoderma lingzhi', 'Fruiting body', 'Ganoderic acid B', 'Terpenoid', 'Triterpenoid', 'High', 'Major', 'Characteristic triterpenoid supporting the mushroom''s defining bitter fraction.', NULL),
  (11, 'Reishi Mushroom', 'Ganoderma lingzhi', 'Fruiting body', 'Ganoderic acid C2', 'Terpenoid', 'Triterpenoid', 'Moderate', 'Major', 'Representative lanostane triterpenoid contributing immunomodulatory activity.', NULL),
  (11, 'Reishi Mushroom', 'Ganoderma lingzhi', 'Fruiting body', 'β-(1→3),(1→6)-D-glucan', 'Polysaccharide', 'β-Glucan', 'High', 'Marker', 'Principal structural polysaccharide responsible for much of the mushroom''s immunomodulatory activity.', NULL),
  (11, 'Reishi Mushroom', 'Ganoderma lingzhi', 'Fruiting body', 'Ganoderic acid H', 'Terpenoid', 'Triterpenoid', 'Moderate', 'Major', 'Representative lanostane triterpenoid complementing the major ganoderic acids.', NULL),
  (11, 'Reishi Mushroom', 'Ganoderma lingzhi', 'Fruiting body', 'Lucidenic acid A', 'Terpenoid', 'Triterpenoid', 'Moderate', 'Present', 'Characteristic lanostane triterpenoid supporting the mushroom''s distinctive bitter triterpenoid chemistry.', NULL),
  (220, 'Rhatany', 'Krameria lappacea', 'Root', 'Ratanhiaphenol I', 'Lignan', 'Neolignan', 'High', 'Marker', 'Principal neolignan contributing to the herb''s characteristic antimicrobial and astringent activity.', 'Krameria lappacea is defined by its unique neolignans, particularly the ratanhiaphenols, which contribute antimicrobial activity and distinguish the genus chemically. Although the root is highly astringent because of its condensed tannins, the neolignans provide the most chemotaxonomically distinctive feature and therefore anchor this profile.'),
  (220, 'Rhatany', 'Krameria lappacea', 'Root', 'Ratanhiaphenol II', 'Lignan', 'Neolignan', 'High', 'Major', 'Characteristic neolignan supporting the defining phenolic profile.', NULL),
  (220, 'Rhatany', 'Krameria lappacea', 'Root', 'Conocarpan', 'Lignan', 'Neolignan', 'Moderate', 'Major', 'Representative neolignan contributing to the herb''s distinctive chemistry.', NULL),
  (220, 'Rhatany', 'Krameria lappacea', 'Root', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Major', 'Representative flavan-3-ol contributing to the condensed tannin fraction.', NULL),
  (220, 'Rhatany', 'Krameria lappacea', 'Root', 'Epicatechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Supporting flavan-3-ol complementing the tannin chemistry.', NULL),
  (220, 'Rhatany', 'Krameria lappacea', 'Root', 'Procyanidin B2', 'Tannin', 'Condensed tannin', 'Moderate', 'Present', 'Representative proanthocyanidin contributing to the herb''s pronounced astringency.', NULL),
  (213, 'Roman Chamomile', 'Chamaemelum nobile', 'Flower', 'Angelic acid', 'Phenylpropanoid', 'Aromatic acid', 'High', 'Marker', 'Characteristic acid forming the distinctive angelate esters that define the essential oil.', 'Chamaemelum nobile is defined by its unusual angelate esters, which account for much of its characteristic aroma, antispasmodic activity, and calming reputation. Unlike German chamomile, Roman chamomile is not characterized by chamazulene-rich sesquiterpenes, making its ester chemistry the dominant phytochemical feature.'),
  (213, 'Roman Chamomile', 'Chamaemelum nobile', 'Flower', 'Isobutyl angelate', 'Phenylpropanoid', 'Aromatic ester', 'High', 'Marker', 'Characteristic angelate ester contributing much of the herb''s calming aroma and antispasmodic activity.', NULL),
  (213, 'Roman Chamomile', 'Chamaemelum nobile', 'Flower', 'Isoamyl angelate', 'Phenylpropanoid', 'Aromatic ester', 'High', 'Major', 'Representative angelate ester defining the herb''s distinctive volatile chemistry.', NULL),
  (213, 'Roman Chamomile', 'Chamaemelum nobile', 'Flower', 'Tiglic acid', 'Phenylpropanoid', 'Aromatic acid', 'Moderate', 'Major', 'Structural analogue of angelic acid contributing to the characteristic ester profile.', NULL),
  (213, 'Roman Chamomile', 'Chamaemelum nobile', 'Flower', 'Apigenin', 'Flavonoid', 'Flavone', 'Moderate', 'Major', 'Principal flavone contributing anti-inflammatory and calming activity.', NULL),
  (213, 'Roman Chamomile', 'Chamaemelum nobile', 'Flower', 'Luteolin', 'Flavonoid', 'Flavone', 'Low–Moderate', 'Present', 'Supporting flavone contributing antioxidant and anti-inflammatory activity.', NULL),
  (849, 'Rosehips', 'Rosa canina', 'Fruit', 'Trans-tiliroside', 'Flavonoid', 'Flavonol glycoside', 'High', 'Marker', 'Characteristic flavonoid associated with anti-inflammatory activity and frequently used as an analytical marker.', 'Rosa canina fruit is defined by its unique combination of ellagitannins, flavonoids, and the characteristic galactolipid GOPO®, which together account for much of its antioxidant, anti-inflammatory, and joint-supportive activity. Although rosehips are widely associated with vitamin C, their polyphenols and galactolipids are far more distinctive phytochemically and therefore define this profile.'),
  (849, 'Rosehips', 'Rosa canina', 'Fruit', 'Tellimagrandin I', 'Tannin', 'Ellagitannin', 'High', 'Major', 'Representative hydrolyzable tannin contributing antioxidant and astringent activity.', NULL),
  (849, 'Rosehips', 'Rosa canina', 'Fruit', 'Tellimagrandin II', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Characteristic ellagitannin supporting the dominant polyphenol fraction.', NULL),
  (849, 'Rosehips', 'Rosa canina', 'Fruit', 'Galactolipid GOPO® (1,2-di-O-α-linolenoyl-3-O-β-D-galactopyranosyl-sn-glycerol)', 'Lipid', 'Galactolipid', 'High', 'Marker', 'Characteristic galactolipid associated with the fruit''s anti-inflammatory and joint-supportive activity.', NULL),
  (849, 'Rosehips', 'Rosa canina', 'Fruit', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Supporting flavonol contributing antioxidant activity.', NULL),
  (849, 'Rosehips', 'Rosa canina', 'Fruit', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Representative flavan-3-ol complementing the fruit''s polyphenol profile.', NULL),
  (413, 'Sandalwood', 'Santalum album', 'Heartwood', 'α-Santalol', 'Terpenoid', 'Sesquiterpene', 'High', 'Marker', 'Principal sesquiterpene alcohol responsible for much of the wood''s characteristic aroma, anti-inflammatory activity, and calming effects.', 'Santalum album is defined almost entirely by its sesquiterpene alcohols, particularly α-santalol and β-santalol, which account for much of its characteristic fragrance, anti-inflammatory activity, antimicrobial effects, and calming reputation. The remaining sesquiterpenes reinforce this distinctive chemistry while contributing comparatively little to the herb''s overall pharmacological identity.'),
  (413, 'Sandalwood', 'Santalum album', 'Heartwood', 'β-Santalol', 'Terpenoid', 'Sesquiterpene', 'High', 'Marker', 'Companion sesquiterpene alcohol contributing antimicrobial and anxiolytic activity.', NULL),
  (413, 'Sandalwood', 'Santalum album', 'Heartwood', 'α-Santalene', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Characteristic sesquiterpene hydrocarbon supporting the defining santalol chemistry.', NULL),
  (413, 'Sandalwood', 'Santalum album', 'Heartwood', 'β-Santalene', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Representative sesquiterpene contributing to the wood''s characteristic fragrance profile.', NULL),
  (413, 'Sandalwood', 'Santalum album', 'Heartwood', 'Bergamotol', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Present', 'Characteristic sesquiterpene alcohol complementing the dominant santalol fraction.', NULL),
  (413, 'Sandalwood', 'Santalum album', 'Heartwood', 'Lanceol', 'Terpenoid', 'Sesquiterpene', 'Low–Moderate', 'Present', 'Supporting sesquiterpene alcohol representative of the heartwood''s distinctive volatile chemistry.', NULL),
  (313, 'Sassafras', 'Sassafras albidum', 'Root bark', 'Safrole', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Marker', 'Principal constituent responsible for much of the root bark''s characteristic aroma, carminative activity, and toxicological significance.', 'Sassafras albidum is defined primarily by its phenylpropenes, especially safrole, which account for much of its characteristic aroma, carminative activity, and historical medicinal use while also defining its toxicological profile. The accompanying monoterpenes contribute to the volatile oil but remain secondary to the herb''s distinctive safrole chemistry.'),
  (313, 'Sassafras', 'Sassafras albidum', 'Root bark', 'Methyleugenol', 'Phenylpropanoid', 'Phenylpropene', 'High', 'Major', 'Characteristic phenylpropene contributing aromatic and antimicrobial activity.', NULL),
  (313, 'Sassafras', 'Sassafras albidum', 'Root bark', 'Eugenol', 'Phenylpropanoid', 'Phenylpropene', 'Moderate', 'Major', 'Representative phenylpropene contributing analgesic and antimicrobial effects.', NULL),
  (313, 'Sassafras', 'Sassafras albidum', 'Root bark', 'Camphor', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Oxygenated monoterpene contributing to the characteristic aroma and biological activity.', NULL),
  (313, 'Sassafras', 'Sassafras albidum', 'Root bark', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Supporting monoterpene contributing to the volatile profile.', NULL),
  (313, 'Sassafras', 'Sassafras albidum', 'Root bark', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Characteristic monoterpene alcohol complementing the dominant phenylpropene fraction.', NULL),
  (469, 'Scots Pine', 'Pinus sylvestris', 'Needle', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene contributing much of the herb''s expectorant, antimicrobial, and decongestant activity.', 'Pinus sylvestris is defined primarily by its monoterpenes, especially α-pinene and β-pinene, which account for much of its expectorant, antimicrobial, and decongestant activity. Bornyl acetate and the remaining terpenes reinforce the characteristic conifer aroma while remaining secondary to the dominant pinene chemistry.'),
  (469, 'Scots Pine', 'Pinus sylvestris', 'Needle', 'β-Pinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Characteristic monoterpene supporting the defining volatile chemistry.', NULL),
  (469, 'Scots Pine', 'Pinus sylvestris', 'Needle', 'Bornyl acetate', 'Terpenoid', 'Monoterpene ester', 'Moderate', 'Major', 'Characteristic ester contributing to the fresh balsamic aroma and respiratory activity.', NULL),
  (469, 'Scots Pine', 'Pinus sylvestris', 'Needle', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Supporting monoterpene complementing the characteristic terpene profile.', NULL),
  (469, 'Scots Pine', 'Pinus sylvestris', 'Needle', 'δ-3-Carene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic conifer monoterpene contributing to the distinctive resinous aroma.', NULL),
  (469, 'Scots Pine', 'Pinus sylvestris', 'Needle', 'β-Caryophyllene', 'Terpenoid', 'Sesquiterpene', 'Low–Moderate', 'Present', 'Representative sesquiterpene contributing complementary anti-inflammatory activity.', NULL),
  (852, 'Shatavari', 'Asparagus racemosus', 'Root', 'Shatavarin IV', 'Glycoside', 'Steroidal glycoside', 'High', 'Marker', 'Principal steroidal saponin contributing much of the herb''s adaptogenic, galactagogue, and reproductive tonic activity.', 'Asparagus racemosus is defined primarily by its steroidal saponins, especially the shatavarins, which account for much of its adaptogenic, galactagogue, and reproductive tonic activity. The characteristic sapogenins and the unique alkaloid asparagamine A complement this defining steroidal chemistry while remaining secondary to the dominant shatavarin fraction.'),
  (852, 'Shatavari', 'Asparagus racemosus', 'Root', 'Shatavarin I', 'Glycoside', 'Steroidal glycoside', 'High', 'Major', 'Characteristic steroidal saponin representative of the dominant shatavarin fraction.', NULL),
  (852, 'Shatavari', 'Asparagus racemosus', 'Root', 'Sarsasapogenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Major', 'Principal sapogenin underlying the characteristic steroidal saponins.', NULL),
  (852, 'Shatavari', 'Asparagus racemosus', 'Root', 'Diosgenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Major', 'Characteristic sapogenin contributing to the defining steroidal chemistry.', NULL),
  (852, 'Shatavari', 'Asparagus racemosus', 'Root', 'Asparagamine A', 'Alkaloid', 'Pyrrolidine alkaloid', 'Moderate', 'Present', 'Characteristic polycyclic alkaloid unique to Asparagus racemosus.', NULL),
  (852, 'Shatavari', 'Asparagus racemosus', 'Root', 'Shatavarin II', 'Glycoside', 'Steroidal glycoside', 'Moderate', 'Present', 'Characteristic steroidal saponin reinforcing the defining shatavarin profile.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Sinigrin', 'Glycoside', 'Glucosinolate', 'High', 'Marker', 'Principal glucosinolate contributing to the herb''s characteristic pungent chemistry and enzymatic hydrolysis products.', 'Capsella bursa-pastoris is defined by its glucosinolates together with unusually abundant choline compounds, which contribute much of its traditional hemostatic, circulatory, and urinary activity. The flavonoids provide complementary vascular support while remaining secondary to the herb''s defining sulfur and quaternary ammonium chemistry.'),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Glucotropaeolin', 'Glycoside', 'Glucosinolate', 'High', 'Major', 'Characteristic glucosinolate supporting the defining sulfur-containing chemistry.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Choline', 'Nitrogenous compound', 'Quaternary ammonium compound', 'Moderate', 'Major', 'Characteristic quaternary ammonium compound associated with the herb''s traditional hemostatic use.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Acetylcholine', 'Glycoside', 'Choline ester', 'Moderate', 'Major', 'Biologically active choline ester contributing to the herb''s cardiovascular and smooth muscle effects.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Representative flavonol contributing antioxidant activity and supporting the herb''s vascular actions.', NULL),
  (71, 'Shepherd''s Purse', 'Capsella bursa-pastoris', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Supporting flavonoid complementing the herb''s phenolic fraction.', NULL),
  (226, 'Shiitake', 'Lentinula edodes', 'Fruiting body', 'Lentinan', 'Polysaccharide', 'β-Glucan', 'High', 'Marker', 'Principal β-(1→3),(1→6)-glucan responsible for much of the mushroom''s immunomodulatory activity.', 'Lentinula edodes is defined primarily by its β-glucans, especially lentinan, which account for much of its immunomodulatory and antitumor activity. Eritadenine and lenthionine distinguish shiitake from many other medicinal mushrooms by contributing characteristic lipid-modulating and organosulfur chemistry, while ergosterol represents the dominant fungal sterol.'),
  (226, 'Shiitake', 'Lentinula edodes', 'Fruiting body', 'Eritadenine', 'Nitrogenous compound', 'Amino acid derivative', 'High', 'Marker', 'Unique purine derivative associated with cholesterol-lowering and lipid-modulating activity.', NULL),
  (226, 'Shiitake', 'Lentinula edodes', 'Fruiting body', 'Ergosterol', 'Sterol', 'Fungal sterol', 'Moderate', 'Major', 'Principal fungal sterol and precursor of vitamin D₂.', NULL),
  (226, 'Shiitake', 'Lentinula edodes', 'Fruiting body', 'Ergothioneine', 'Nitrogenous compound', 'Amino acid derivative', 'Moderate', 'Major', 'Sulfur-containing antioxidant characteristic of edible mushrooms, contributing cytoprotective activity.', NULL),
  (226, 'Shiitake', 'Lentinula edodes', 'Fruiting body', 'Lenthionine', 'Organosulfur compound', 'Sulfide', 'Moderate', 'Major', 'Cyclic organosulfur compound responsible for much of shiitake''s characteristic aroma and antimicrobial activity.', NULL),
  (226, 'Shiitake', 'Lentinula edodes', 'Fruiting body', 'KS-2 β-Glucan', 'Polysaccharide', 'β-Glucan', 'Low–Moderate', 'Reported', 'Protein-associated β-glucan reported from the fruiting body, included only as a structurally characterized polysaccharide rather than as an extract preparation.', NULL),
  (NULL, 'Silk Tassel', 'Garrya elliptica', 'Bark', 'Garryoside A', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal bitter iridoid glycoside defining the bark''s characteristic chemistry.', 'Garrya elliptica is defined almost entirely by its garryoside iridoid glycosides, which account for much of its intensely bitter, gastric stimulant, and digestive tonic activity. Because the species has received little modern phytochemical investigation, the profile is intentionally restricted to its well-documented iridoid chemistry rather than expanding into speculative supporting constituents.'),
  (NULL, 'Silk Tassel', 'Garrya elliptica', 'Bark', 'Garryoside B', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Characteristic iridoid glycoside contributing to the herb''s bitter tonic activity.', NULL),
  (NULL, 'Silk Tassel', 'Garrya elliptica', 'Bark', 'Garryoside C', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Representative iridoid glycoside supporting the defining iridoid fraction.', NULL),
  (1252, 'Solomon''s Seal', 'Polygonatum biflorum', 'Rhizome', 'Diosgenin', 'Steroid', 'Steroidal sapogenin', 'High', 'Major', 'Principal sapogenin contributing to the herb''s steroidal saponin profile.', NULL),
  (1252, 'Solomon''s Seal', 'Polygonatum biflorum', 'Rhizome', 'Pennogenin', 'Steroid', 'Steroidal sapogenin', 'Moderate', 'Major', 'Characteristic sapogenin complementing the dominant steroidal glycosides.', NULL),
  (1252, 'Solomon''s Seal', 'Polygonatum biflorum', 'Rhizome', 'Polygonatum polysaccharide', 'Polysaccharide', 'Glucomannan', 'Moderate', 'Major', 'Characteristic storage polysaccharide contributing demulcent and immunomodulatory activity.', NULL),
  (1252, 'Solomon''s Seal', 'Polygonatum biflorum', 'Rhizome', 'β-Sitosterol', 'Sterol', 'Phytosterol', 'Low–Moderate', 'Present', 'Representative sterol providing a minor supporting component of the rhizome chemistry.', NULL),
  (1102, 'Sorrel', 'Rumex acetosa', 'Leaf', 'Oxalic acid', 'Organic acid', 'Dicarboxylic acid', 'High', 'Marker', 'Principal organic acid responsible for the characteristic sour taste and defining the leaf''s chemistry.', 'Rumex acetosa is defined primarily by its oxalic acid content, which gives the leaves their characteristic sour flavor and distinguishes the species from most medicinal greens. Flavonols provide the principal supporting phenolic chemistry while remaining secondary to the herb''s distinctive organic acid profile.'),
  (1102, 'Sorrel', 'Rumex acetosa', 'Leaf', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Characteristic flavonol glycoside contributing antioxidant activity.', NULL),
  (1102, 'Sorrel', 'Rumex acetosa', 'Leaf', 'Quercetin', 'Flavonoid', 'Flavonol', 'Moderate', 'Major', 'Principal flavonol complementing the herb''s phenolic profile.', NULL),
  (1102, 'Sorrel', 'Rumex acetosa', 'Leaf', 'Kaempferol', 'Flavonoid', 'Flavonol', 'Moderate', 'Present', 'Supporting flavonol contributing antioxidant activity.', NULL),
  (1102, 'Sorrel', 'Rumex acetosa', 'Leaf', 'Nepodin', 'Anthraquinone', 'Anthraquinone', 'Low–Moderate', 'Present', 'Characteristic anthraquinone reported from Rumex species that complements the leaf''s distinctive chemistry more effectively than a ubiquitous phenolic acid.', NULL),
  (NULL, 'Stonebreaker', 'Phyllanthus niruri', 'Aerial parts', 'Phyllanthin', 'Lignan', 'Dibenzylbutane lignan', 'High', 'Marker', 'Principal lignan associated with the herb''s hepatoprotective and urinary tract activity.', 'Phyllanthus niruri is defined by its complementary lignans and ellagitannins, particularly phyllanthin, hypophyllanthin, geraniin, and corilagin, which account for much of its traditional hepatoprotective, antiviral, and urinary tract activity. The coexistence of these two dominant constituent families distinguishes the species chemically while simple phenolic acids remain secondary.'),
  (NULL, 'Stonebreaker', 'Phyllanthus niruri', 'Aerial parts', 'Hypophyllanthin', 'Lignan', 'Dibenzylbutane lignan', 'High', 'Major', 'Characteristic lignan complementing phyllanthin and defining the species'' lignan chemistry.', NULL),
  (NULL, 'Stonebreaker', 'Phyllanthus niruri', 'Aerial parts', 'Niranthin', 'Lignan', 'Dibenzylbutane lignan', 'Moderate', 'Major', 'Representative lignan contributing to the herb''s characteristic hepatoprotective profile.', NULL),
  (NULL, 'Stonebreaker', 'Phyllanthus niruri', 'Aerial parts', 'Corilagin', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Characteristic hydrolyzable tannin contributing antioxidant and antiviral activity.', NULL),
  (NULL, 'Stonebreaker', 'Phyllanthus niruri', 'Aerial parts', 'Geraniin', 'Tannin', 'Ellagitannin', 'Moderate', 'Major', 'Principal ellagitannin reinforcing the herb''s antioxidant and antiviral chemistry.', NULL),
  (NULL, 'Stonebreaker', 'Phyllanthus niruri', 'Aerial parts', 'Ellagic acid', 'Polyphenol', 'Phenolic acid', 'Low–Moderate', 'Present', 'Representative hydrolysis product of the dominant ellagitannins.', NULL),
  (748, 'Sweet Orange', 'Citrus × sinensis', 'Peel', 'Limonene', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene responsible for much of the peel''s characteristic aroma, digestive activity, and antimicrobial properties.', 'Citrus × sinensis peel is defined by its complementary monoterpenes and citrus flavonoids, particularly limonene and hesperidin, which account for much of its characteristic aroma, digestive activity, and antioxidant properties. The polymethoxylated flavones provide a distinctive chemotaxonomic feature while remaining secondary to the dominant volatile oil and flavanone fractions.'),
  (748, 'Sweet Orange', 'Citrus × sinensis', 'Peel', 'β-Pinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Characteristic monoterpene contributing to the peel''s fresh citrus aroma and complementing the limonene-rich volatile fraction.', NULL),
  (748, 'Sweet Orange', 'Citrus × sinensis', 'Peel', 'Linalool', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Oxygenated monoterpene contributing floral aroma and antimicrobial activity.', NULL),
  (748, 'Sweet Orange', 'Citrus × sinensis', 'Peel', 'Hesperidin', 'Flavonoid', 'Flavanone glycoside', 'High', 'Marker', 'Principal flavanone glycoside contributing vascular and antioxidant activity.', NULL),
