  (748, 'Sweet Orange', 'Citrus × sinensis', 'Peel', 'Sinensetin', 'Flavonoid', 'Polymethoxylated flavone', 'Moderate', 'Present', 'Characteristic polymethoxylated flavone distinguishing sweet orange peel chemistry from many other citrus species.', NULL),
  (1442, 'Tea Tree', 'Melaleuca alternifolia', 'Leaf', 'Terpinen-4-ol', 'Terpenoid', 'Monoterpenoid', 'High', 'Marker', 'Principal monoterpene alcohol responsible for much of the herb''s antimicrobial, antifungal, and anti-inflammatory activity.', 'Melaleuca alternifolia is defined almost entirely by its monoterpene-rich essential oil, particularly terpinen-4-ol, which accounts for much of its antimicrobial, antifungal, and anti-inflammatory activity. The remaining monoterpenes reinforce this characteristic chemistry, while quality medicinal oils are distinguished by maintaining relatively low concentrations of 1,8-cineole.'),
  (1442, 'Tea Tree', 'Melaleuca alternifolia', 'Leaf', 'γ-Terpinene', 'Terpenoid', 'Monoterpenoid', 'High', 'Major', 'Characteristic monoterpene contributing to the defining essential oil profile.', NULL),
  (1442, 'Tea Tree', 'Melaleuca alternifolia', 'Leaf', 'α-Terpinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Major', 'Representative monoterpene supporting the characteristic volatile chemistry.', NULL),
  (1442, 'Tea Tree', 'Melaleuca alternifolia', 'Leaf', 'p-Cymene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic biosynthetic intermediate complementing the terpinen-4-ol-rich essential oil profile.', NULL),
  (1442, 'Tea Tree', 'Melaleuca alternifolia', 'Leaf', 'α-Terpineol', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Characteristic monoterpene alcohol complementing terpinen-4-ol in the essential oil.', NULL),
  (1442, 'Tea Tree', 'Melaleuca alternifolia', 'Leaf', 'Terpinolene', 'Terpenoid', 'Monoterpenoid', 'Low–Moderate', 'Present', 'Supporting monoterpene contributing to the herb''s distinctive volatile profile.', NULL),
  (112, 'Usnea', 'Usnea spp.', 'Thallus', 'Usnic acid', 'Dibenzofuran', 'Dibenzofuran', 'High', 'Marker', 'Principal lichen metabolite responsible for much of the thallus'' antimicrobial activity and chemotaxonomic identity.', 'Usnea species are chemically defined by specialized lichen metabolites, particularly usnic acid together with depsides and depsidones, which account for much of their antimicrobial activity and chemotaxonomic identity. The profile emphasizes these uniquely lichenized compounds because they distinguish Usnea from virtually all vascular medicinal plants while avoiding more ubiquitous supporting metabolites.'),
  (112, 'Usnea', 'Usnea spp.', 'Thallus', 'Diffractaic acid', 'Polyphenol', 'Depside', 'High', 'Major', 'Characteristic lichen depside contributing antimicrobial and antioxidant activity.', NULL),
  (112, 'Usnea', 'Usnea spp.', 'Thallus', 'Barbatic acid', 'Polyphenol', 'Depside', 'Moderate', 'Major', 'Representative depside supporting the characteristic lichen phenolic profile.', NULL),
  (112, 'Usnea', 'Usnea spp.', 'Thallus', 'Salazinic acid', 'Depsidone', 'Depsidone', 'Moderate', 'Major', 'Characteristic depsidone contributing antimicrobial activity and distinguishing many Usnea chemotypes.', NULL),
  (112, 'Usnea', 'Usnea spp.', 'Thallus', 'Norstictic acid', 'Depsidone', 'Depsidone', 'Moderate', 'Present', 'Representative depsidone complementing the dominant lichen metabolites.', NULL),
  (112, 'Usnea', 'Usnea spp.', 'Thallus', 'Atranorin', 'Polyphenol', 'Depside', 'Moderate', 'Present', 'Common cortical depside complementing the characteristic lichen secondary metabolite profile.', NULL),
  (198, 'Violet', 'Viola odorata', 'Aerial parts', 'Violanthin', 'Flavonoid', 'Flavone glycoside', 'High', 'Marker', 'Characteristic flavone glycoside representing the principal flavonoid fraction of the aerial parts.', 'Viola odorata is chemically distinguished by its cyclotides, a unique family of cyclic peptides found throughout the genus that contribute to its biological activity and chemotaxonomic identity. Flavonoids and methyl salicylate complement this distinctive peptide chemistry, while the inclusion of violanthin preserves the characteristic flavonoid profile without diluting the emphasis on the defining cyclotide family.'),
  (198, 'Violet', 'Viola odorata', 'Aerial parts', 'Rutin', 'Flavonoid', 'Flavonol glycoside', 'Moderate', 'Major', 'Principal flavonoid supporting capillary-protective and antioxidant activity.', NULL),
  (198, 'Violet', 'Viola odorata', 'Aerial parts', 'Methyl salicylate', 'Phenylpropanoid', 'Aromatic ester', 'Moderate', 'Major', 'Characteristic volatile constituent contributing mild analgesic and anti-inflammatory properties.', NULL),
  (198, 'Violet', 'Viola odorata', 'Aerial parts', 'Cycloviolacin O2', 'Protein', 'Cyclotide', 'High', 'Marker', 'Representative cyclotide contributing to the species'' distinctive cyclic peptide chemistry.', NULL),
  (198, 'Violet', 'Viola odorata', 'Aerial parts', 'Cycloviolacin O8', 'Protein', 'Cyclotide', 'Moderate', 'Major', 'Characteristic cyclotide reinforcing the defining peptide profile of the genus.', NULL),
  (198, 'Violet', 'Viola odorata', 'Aerial parts', 'Delphinidin 3-rutinoside', 'Flavonoid', 'Anthocyanin', 'Low–Moderate', 'Present', 'Principal anthocyanin contributing to the characteristic violet flower pigmentation.', NULL),
  (173, 'Wahoo', 'Euonymus atropurpureus', 'Root bark', 'Euonymin', 'Steroid', 'Cardiac glycoside', 'High', 'Marker', 'Principal cardiac glycoside contributing to the herb''s traditional cardiotonic and cathartic activity.', 'Euonymus atropurpureus is chemically defined by its cardiac glycosides, which account for both its historical medicinal use and its narrow therapeutic margin. Because phytochemical investigation of the species remains limited, the profile is intentionally restricted to the well-documented cardenolide chemistry rather than expanded with common supporting metabolites that do little to distinguish the herb.'),
  (173, 'Wahoo', 'Euonymus atropurpureus', 'Root bark', 'Euonoside A', 'Steroid', 'Cardiac glycoside', 'High', 'Major', 'Characteristic cardiac glycoside supporting the defining cardenolide chemistry.', NULL),
  (173, 'Wahoo', 'Euonymus atropurpureus', 'Root bark', 'Euonoside B', 'Steroid', 'Cardiac glycoside', 'Moderate', 'Major', 'Representative cardiac glycoside complementing the dominant euonosides.', NULL),
  (586, 'Western Coltsfoot', 'Petasites frigidus var. palmatus', 'Leaf', 'Petasin', 'Terpenoid', 'Sesquiterpenoid ester', 'High', 'Marker', 'Principal sesquiterpene ester contributing to the herb''s traditional antispasmodic and respiratory activity.', 'Petasites frigidus var. palmatus is chemically defined by its petasin sesquiterpene esters, which account for much of its traditional antispasmodic and respiratory activity. Pyrrolizidine alkaloids are included because they remain an important part of the plant''s toxicological profile, while avoiding unrelated ubiquitous metabolites preserves the defining sesquiterpene chemistry.'),
  (586, 'Western Coltsfoot', 'Petasites frigidus var. palmatus', 'Leaf', 'Isopetasin', 'Terpenoid', 'Sesquiterpenoid ester', 'High', 'Major', 'Characteristic sesquiterpene ester supporting the defining petasin chemistry.', NULL),
  (586, 'Western Coltsfoot', 'Petasites frigidus var. palmatus', 'Leaf', 'Neopetasin', 'Terpenoid', 'Sesquiterpenoid ester', 'Moderate', 'Major', 'Representative petasin ester reinforcing the characteristic sesquiterpene profile.', NULL),
  (586, 'Western Coltsfoot', 'Petasites frigidus var. palmatus', 'Leaf', 'Furanopetasin', 'Terpenoid', 'Sesquiterpenoid ester', 'Moderate', 'Present', 'Characteristic petasin derivative complementing the dominant sesquiterpene ester fraction.', NULL),
  (586, 'Western Coltsfoot', 'Petasites frigidus var. palmatus', 'Leaf', 'Senkirkine', 'Alkaloid', 'Pyrrolizidine alkaloid', 'Moderate', 'Present', 'Representative pyrrolizidine alkaloid included because it contributes to the herb''s toxicological profile.', NULL),
  (125, 'Wild Carrot', 'Daucus carota', 'Seed', 'Carotol', 'Terpenoid', 'Sesquiterpene', 'High', 'Marker', 'Principal sesquiterpene alcohol responsible for much of the seed''s characteristic aroma and antimicrobial activity.', 'Daucus carota seed is chemically defined by its sesquiterpene-rich essential oil, particularly carotol and daucol, which account for much of its traditional urinary, digestive, and antimicrobial activity. The accompanying monoterpenes and esters complete the characteristic volatile profile while remaining secondary to the distinctive sesquiterpene chemistry.'),
  (125, 'Wild Carrot', 'Daucus carota', 'Seed', 'Dauca-4,8-diene', 'Terpenoid', 'Sesquiterpene', 'High', 'Major', 'Characteristic sesquiterpene hydrocarbon contributing to the distinctive seed oil profile.', NULL),
  (125, 'Wild Carrot', 'Daucus carota', 'Seed', 'β-Bisabolene', 'Terpenoid', 'Sesquiterpene', 'Moderate', 'Major', 'Representative sesquiterpene contributing to the characteristic seed essential oil profile.', NULL),
  (125, 'Wild Carrot', 'Daucus carota', 'Seed', 'α-Pinene', 'Terpenoid', 'Monoterpenoid', 'Moderate', 'Present', 'Supporting monoterpene complementing the dominant sesquiterpene fraction.', NULL),
