  (87, 'Willow', 'Salix spp.', 'Bark', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Moderate', 'Present', 'Representative flavan-3-ol contributing antioxidant activity and complementing the salicylate chemistry.', NULL),
  (87, 'Willow', 'Salix spp.', 'Bark', 'Procyanidin B1', 'Tannin', 'Condensed tannin', 'Low–Moderate', 'Present', 'Representative proanthocyanidin supporting the bark''s astringent and antioxidant properties.', NULL),
  (77, 'Wintergreen', 'Gaultheria procumbens', 'Leaf', 'Methyl salicylate', 'Phenylpropanoid', 'Aromatic ester', 'High', 'Marker', 'Principal volatile ester responsible for much of the herb''s characteristic aroma, analgesic activity, and anti-inflammatory effects.', 'Gaultheria procumbens is chemically defined by its salicylate derivatives, particularly methyl salicylate and gaultherin, which account for much of its characteristic analgesic and anti-inflammatory activity. The additional salicylate glycosides preserve this defining chemistry, while the flavonoids provide only a minor supporting antioxidant fraction.'),
  (77, 'Wintergreen', 'Gaultheria procumbens', 'Leaf', 'Gaultherin', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Characteristic salicylate glycoside serving as the natural precursor to methyl salicylate.', NULL),
  (77, 'Wintergreen', 'Gaultheria procumbens', 'Leaf', 'Monotropitoside', 'Glycoside', 'Phenolic glycoside', 'Moderate', 'Major', 'Characteristic salicylate glycoside supporting the defining salicylate chemistry.', NULL),
  (77, 'Wintergreen', 'Gaultheria procumbens', 'Leaf', 'Catechin', 'Flavonoid', 'Flavan-3-ol', 'Low–Moderate', 'Present', 'Representative flavan-3-ol supporting the leaf''s complementary polyphenol fraction.', NULL),
  (77, 'Wintergreen', 'Gaultheria procumbens', 'Leaf', 'Hyperoside', 'Flavonoid', 'Flavonol glycoside', 'Low–Moderate', 'Present', 'Supporting flavonoid complementing the herb''s phenolic profile.', NULL),
  (207, 'Wood Betony', 'Stachys officinalis', 'Aerial parts', 'Harpagide', 'Glycoside', 'Iridoid glycoside', 'High', 'Marker', 'Principal iridoid glycoside contributing much of the herb''s bitter tonic and anti-inflammatory activity.', 'Stachys officinalis is chemically defined by its iridoid glycosides, particularly harpagide and its derivatives, which account for much of its traditional anti-inflammatory and bitter tonic activity. The inclusion of phenylethanoid glycosides preserves the herb''s complementary antioxidant chemistry while maintaining emphasis on the defining iridoid profile.'),
  (207, 'Wood Betony', 'Stachys officinalis', 'Aerial parts', '8-O-Acetylharpagide', 'Glycoside', 'Iridoid glycoside', 'High', 'Major', 'Characteristic acetylated iridoid glycoside reinforcing the defining iridoid chemistry.', NULL),
  (207, 'Wood Betony', 'Stachys officinalis', 'Aerial parts', 'Ajugol', 'Glycoside', 'Iridoid glycoside', 'Moderate', 'Major', 'Representative iridoid glycoside complementing the dominant harpagide derivatives.', NULL),
