  (207, 'Wood Betony', 'Stachys officinalis', 'Aerial parts', 'Stachydrine', 'Nitrogenous compound', 'Betaine', 'Low–Moderate', 'Present', 'Characteristic betaine supporting the herb''s traditional tonic and circulatory applications.', NULL),
  (1, 'Wu Jia Pi', 'Acanthopanax sessiliflorus', 'Root bark', 'Acanthoside D', 'Glycoside', 'Phenolic glycoside', 'High', 'Marker', 'Principal phenolic glycoside contributing to the herb''s adaptogenic and anti-inflammatory activity.', 'Acanthopanax sessiliflorus is defined primarily by its eleutherosides and related phenolic and lignan glycosides, which account for much of its traditional adaptogenic, musculoskeletal, and anti-inflammatory activity. The inclusion of sesamin preserves the characteristic lignan chemistry while chlorogenic acid represents a minor supporting phenolic fraction that does not overshadow the herb''s defining glycosides.'),
  (1, 'Wu Jia Pi', 'Acanthopanax sessiliflorus', 'Root bark', 'Eleutheroside B', 'Glycoside', 'Phenolic glycoside', 'High', 'Major', 'Characteristic phenolic glycoside representative of the eleutheroside fraction.', NULL),
  (1, 'Wu Jia Pi', 'Acanthopanax sessiliflorus', 'Root bark', 'Eleutheroside E', 'Glycoside', 'Lignan glycoside', 'High', 'Major', 'Principal lignan glycoside supporting the defining adaptogenic chemistry.', NULL),
