  (1, 'Wu Jia Pi', 'Acanthopanax sessiliflorus', 'Root bark', 'Sesamin', 'Lignan', 'Furofuran lignan', 'Moderate', 'Present', 'Representative lignan reinforcing the herb''s lignan chemistry.', NULL),
  (1, 'Wu Jia Pi', 'Acanthopanax sessiliflorus', 'Root bark', 'Syringaresinol', 'Lignan', 'Furofuran lignan', 'Low–Moderate', 'Present', 'Characteristic lignan reinforcing the herb''s distinctive eleutheroside and lignan chemistry.', NULL),
  (645, 'Yellow Jasmine', 'Gelsemium sempervirens', 'Root', 'Gelsemine', 'Alkaloid', 'Indole alkaloid', 'High', 'Marker', 'Principal indole alkaloid responsible for much of the plant''s pharmacological activity and toxicity.', 'Gelsemium sempervirens is chemically defined almost entirely by its indole alkaloids, which account for both its historical medicinal use and its significant toxicity. The profile intentionally focuses exclusively on representative members of this distinctive alkaloid family, as they overwhelmingly define the pharmacology and chemotaxonomic identity of the species.'),
  (645, 'Yellow Jasmine', 'Gelsemium sempervirens', 'Root', 'Gelseminine', 'Alkaloid', 'Indole alkaloid', 'High', 'Major', 'Characteristic indole alkaloid contributing to the defining alkaloid profile.', NULL),
